window.SITE_COURSES=window.SITE_COURSES||{};SITE_COURSES["arabiya-bayna-yadayk-1"]={"lessons":[{"id":"abyb1-001","title":"السلام عليكم: كيف نبدأ الحوار؟","summary":"الحوار الأول من الوحدة الأولى: التحية، والسؤال عن الاسم، والسؤال عن الحال.","segments":[{"body":["نبدأ بأول كلمة يقولها المسلمون عند اللقاء: السلام عليكم. معناها: السلامة لكم.","والجواب: وعليكم السلام. أي: ولكم السلامة أيضًا.","هذه تحية تُقال للكبير وللصغير، وفي أول اللقاء وعند الدخول على الناس.","بعد التحية نسأل عن الاسم. السؤال: ما اسمك؟ ومعناه: ما هو اسمك؟","والجواب: اسمي خالد. كلمة «اسمي» تعني: اسمٌ لي. فنضع بعدها اسمنا.","المصطلح «تحية»: كلمة نقولها عند اللقاء. والمصطلح «سؤال»: جملة نطلب بها معلومة."],"examples":["السَّلَامُ عَلَيْكُمْ. (تحية)","وَعَلَيْكُمُ السَّلَامُ. (جواب التحية)","مَا اسْمُكَ؟ (سؤال عن الاسم)","اسْمِي خَالِد. (جواب)","اسْمِي خَلِيل. (جواب)"],"questions":[{"question":"ما جواب «السلام عليكم»؟","options":["كيف حالك؟","ما اسمك؟","وعليكم السلام","اسمي خالد"],"answer":2,"explanation":"الجواب المعتاد: وعليكم السلام."},{"question":"ماذا تعني «ما اسمك؟»","options":["من أين أنت؟","كيف حالك؟","أين بيتك؟","ما هو اسمك؟"],"answer":3,"explanation":"«ما» تعني: ما هو، و«اسمك» أي اسمك أنت."},{"question":"كيف تقول اسمك إذا كان اسمك علي؟","options":["ما اسمك علي","اسمي علي","أنا اسم علي","علي اسمك"],"answer":1,"explanation":"نقول: اسمي، ثم نضع الاسم."},{"question":"متى نقول «السلام عليكم»؟","options":["لا نقولها أبدًا","عند الأكل فقط","عند اللقاء","عند النوم فقط"],"answer":2,"explanation":"هي تحية اللقاء."}]},{"body":["الآن نسأل عن الحال. السؤال: كيف حالك؟ ومعناه: كيف أنت؟ هل أنت بخير؟","والجواب: بخير، والحمد لله. كلمة «بخير» تعني: في حال جيدة.","«الحمد لله» جملة شكر. معناها: الشكر لله. يقولها المسلمون كثيرًا.","بعد أن نجيب نسأل الشخص الآخر: وكيف حالك أنت؟ والمعنى: وأنت، كيف حالك؟","لاحظ الحرف الأخير في «حالك». إذا سألنا رجلًا نقول: حالُك. وإذا سألنا امرأة نقول: حالُكِ. هذا سيأتي لاحقًا."],"examples":["كَيْفَ حَالُكَ؟","بِخَيْرٍ، وَالْحَمْدُ لِلَّهِ.","وَكَيْفَ حَالُكَ أَنْتَ؟","خَالِد: بِخَيْرٍ، وَالْحَمْدُ لِلَّهِ."],"questions":[{"question":"ماذا تعني «كيف حالك؟»","options":["من أين أنت؟","كيف أنت؟","ما اسمك؟","أين أنت؟"],"answer":1,"explanation":"«كيف» تسأل عن الطريقة أو الحال."},{"question":"ما الجواب المناسب لـ «كيف حالك؟»","options":["وعليكم السلام","أنا من مصر","اسمي خالد","بخير، والحمد لله"],"answer":3,"explanation":"نجيب عن الحال بكلمة «بخير»."},{"question":"ماذا تعني «الحمد لله»؟","options":["مع السلامة","ما اسمك","أهلًا وسهلًا","الشكر لله"],"answer":3,"explanation":"هي جملة شكر لله."},{"question":"رتّب الحوار: ما الجملة الأولى؟","options":["مع السلامة","السلام عليكم","اسمي خليل","بخير"],"answer":1,"explanation":"الحوار يبدأ بالتحية."},{"question":"بعد أن تقول «بخير» ماذا تسأل؟","options":["ما اسمي؟","من أنا؟","وكيف حالك أنت؟","السلام عليكم فقط"],"answer":2,"explanation":"نرد السؤال على الشخص الآخر."}]}]},{"id":"abyb1-002","title":"من أين أنت؟ وما جنسيتك؟","summary":"الحوار الثاني: السؤال عن البلد والجنسية، وقول «أهلًا وسهلًا».","segments":[{"body":["نقرأ هذا الحوار من الكتاب. في الحوار رجلان يلتقيان لأول مرة.","الأول يسأل: من أين أنت؟ والمعنى: ما هو بلدك؟ كلمة «أين» تسأل عن المكان.","والثاني يجيب: أنا من باكستان. كلمة «من» هنا تعني: مأخوذ من بلد. أي: بلدي باكستان.","المصطلح «بلد»: المكان الذي نعيش فيه أو جئنا منه، مثل مصر وتركيا وسوريا.","المصطلح «جنسية»: صفة الشخص بحسب بلده. من باكستان فجنسيته باكستاني.","وفي آخر الحوار نقول: أهلًا وسهلًا. هي كلمة ترحيب. معناها: مرحبًا بك."],"examples":["مُحَمَّد: مِنْ أَيْنَ أَنْتَ؟","شَرِيف: أَنَا مِنْ بَاكِسْتَان.","مُحَمَّد: هَلْ أَنْتَ بَاكِسْتَانِيٌّ؟","شَرِيف: نَعَمْ، أَنَا بَاكِسْتَانِيٌّ. وَمَا جِنْسِيَّتُكَ أَنْتَ؟","مُحَمَّد: أَنَا تُرْكِيٌّ. أَنَا مِنْ تُرْكِيَا.","شَرِيف: أَهْلًا وَسَهْلًا."],"questions":[{"question":"ماذا تعني «من أين أنت؟»","options":["ما اسمك؟","من هذا؟","كيف حالك؟","ما بلدك؟"],"answer":3,"explanation":"«أين» تسأل عن المكان، فالسؤال عن البلد."},{"question":"كيف تجيب إذا كنت من مصر؟","options":["اسمي مصر","أنا من مصر","أنا مصر من","من أنت مصر"],"answer":1,"explanation":"نقول: أنا من، ثم اسم البلد."},{"question":"ما معنى «أهلًا وسهلًا»؟","options":["أنا بخير","إلى اللقاء","شكرًا","مرحبًا بك"],"answer":3,"explanation":"هي عبارة ترحيب."},{"question":"من أين محمد في الحوار؟","options":["من سوريا","من مصر","من تركيا","من باكستان"],"answer":2,"explanation":"محمد قال: أنا من تركيا."},{"question":"ما «الجنسية»؟","options":["اسم الشخص","عمل الشخص","صفة الشخص بحسب بلده","مدينة الشخص"],"answer":2,"explanation":"مثل: باكستاني، تركي، مصري."}]},{"body":["الحوار الثاني (ب) بين امرأتين: مريم وزينب. المعنى نفسه، لكن الكلمات للمرأة.","مريم تسأل: من أين أنتِ؟ لاحظ: للمرأة نقول «أنتِ» بكسرة في آخرها. وللرجل «أنتَ» بفتحة.","زينب تجيب: أنا من مصر. ثم تقول: أنا مصريّة. هذه جنسيتها.","للرجل نقول: مصريّ. وللمرأة نقول: مصريّة. نزيد حرف التاء المربوطة (ة) في آخر الكلمة للمؤنث.","المصطلح «مذكّر»: كلمة للرجل. والمصطلح «مؤنّث»: كلمة للمرأة."],"examples":["مَرْيَم: مِنْ أَيْنَ أَنْتِ؟","زَيْنَب: أَنَا مِنْ مِصْر.","مَرْيَم: هَلْ أَنْتِ مِصْرِيَّةٌ؟","زَيْنَب: نَعَمْ، أَنَا مِصْرِيَّةٌ. وَمَا جِنْسِيَّتُكِ أَنْتِ؟","مَرْيَم: أَنَا سُورِيَّةٌ. أَنَا مِنْ سُورِيَا."],"questions":[{"question":"كيف نسأل امرأة: من أين ...؟","options":["أنتَ","هي","هو","أنتِ"],"answer":3,"explanation":"للمرأة نقول: أنتِ، بكسرة."},{"question":"ما جنسية امرأة من سوريا؟","options":["سورية","سوري","سوريا","سوريان"],"answer":0,"explanation":"نزيد ة للمؤنث: سورية."},{"question":"ما الكلمة المؤنثة؟","options":["مصرية","باكستاني","مصري","تركي"],"answer":0,"explanation":"التاء المربوطة علامة المؤنث هنا."},{"question":"أنتَ بفتحة نقولها لـ:","options":["كل النساء","رجل","امرأة","طفلة"],"answer":1,"explanation":"أنتَ للرجل، وأنتِ للمرأة."},{"question":"زينب في الحوار:","options":["باكستانية","مصرية","تركية","سورية"],"answer":1,"explanation":"زينب قالت: أنا مصرية."}]}]},{"id":"abyb1-003","title":"هذا أخي وهذه أختي: تقديم الناس","summary":"الحوار الثالث: تقديم الأخ والصديق والأخت، وقول «مع السلامة».","segments":[{"body":["في الحوار الثالث أحمد يقدّم أخاه وصديقه لبدر. «يقدّم» أي: يعرّف شخصًا بشخص.","أحمد يقول: هذا أخي، هو مدرّس. كلمة «هذا» تشير إلى رجل أو شيء قريب منك.","ثم: هذا صديقي، هو مهندس. «صديقي» أي: صديق لي. و«أخي» أي: أخ لي.","الياء في آخر الكلمة تعني: لي. أخ + ي = أخي. صديق + ي = صديقي. اسم + ي = اسمي.","المصطلح «مدرّس»: من يعلّم الطلاب. والمصطلح «مهندس»: من يبني ويصمّم، مثل البيوت والجسور."],"examples":["أَحْمَد: هَذَا أَخِي، هُوَ مُدَرِّسٌ.","بَدْر: أَهْلًا وَسَهْلًا.","أَحْمَد: هَذَا صَدِيقِي، هُوَ مُهَنْدِسٌ.","أَحْمَد: مَعَ السَّلَامَةِ.","بَدْر: مَعَ السَّلَامَةِ."],"questions":[{"question":"ماذا تعني الياء في «أخي»؟","options":["لها","لك","له","لي"],"answer":3,"explanation":"الياء في آخر الاسم تعني: لي."},{"question":"ما معنى «مع السلامة»؟","options":["كلمة نقولها عند الفراق","سؤال عن الاسم","كلمة نقولها عند اللقاء","سؤال عن البلد"],"answer":0,"explanation":"نقولها عند الوداع."},{"question":"من هو المدرّس؟","options":["من يعالج المرضى","من يعلّم الطلاب","من يتعلم","من يبني البيوت"],"answer":1,"explanation":"المدرّس هو المعلّم."},{"question":"كيف تقول: صديق لي؟","options":["صديقها","صديقك","صديقه","صديقي"],"answer":3,"explanation":"نزيد الياء: صديقي."},{"question":"هو في «هو مهندس» يعود إلى:","options":["طفلة","رجل","مدينة","امرأة"],"answer":1,"explanation":"«هو» للمذكر الغائب."}]},{"body":["الحوار الثالث (ب) بين ندى وهدى. هنا الكلام عن نساء.","ندى تقول: هذه أختي، هي طبيبة. لاحظ: «هذه» للمؤنث، و«هذا» للمذكر.","ثم: هذه صديقتي، هي طالبة. «صديقتي» مؤنث «صديقي». «طالبة» مؤنث «طالب».","و«هي» للمرأة، و«هو» للرجل. هو مدرس. هي مدرّسة.","المصطلح «طبيبة»: امرأة تعالج المرضى. والمصطلح «طالبة»: امرأة تتعلم في المدرسة أو الجامعة."],"examples":["نَدَى: هَذِهِ أُخْتِي، هِيَ طَبِيبَةٌ.","هُدَى: أَهْلًا وَسَهْلًا.","نَدَى: هَذِهِ صَدِيقَتِي، هِيَ طَالِبَةٌ.","نَدَى: مَعَ السَّلَامَةِ.","هُدَى: مَعَ السَّلَامَةِ."],"questions":[{"question":"نشير إلى امرأة قريبة فنقول:","options":["هو","هذه","هذا","أنتَ"],"answer":1,"explanation":"هذه للمؤنث، وهذا للمذكر."},{"question":"مؤنث «صديقي» هو:","options":["صديقان","صديقك","صدّيق","صديقتي"],"answer":3,"explanation":"نزيد التاء المربوطة: صديقة، ثم ياء المتكلم."},{"question":"كيف نقول: هي ... (امرأة تعالج المرضى)؟","options":["طبيبة","طبيب","مهندس","مدرس"],"answer":0,"explanation":"المؤنث: طبيبة."},{"question":"اختر الجملة الصحيحة:","options":["هذا أخي، هو طالب","هذا أختي، هو طالب","هذه أخي، هي طالب","هذه أخي، هو طالبة"],"answer":0,"explanation":"مذكر مع مذكر: هذا، هو، طالب."},{"question":"«هي» تعود إلى:","options":["كتاب مذكر","رجل","ولد","امرأة"],"answer":3,"explanation":"«هي» للمؤنث."}]}]},{"id":"abyb1-004","title":"هل أنت باكستاني؟ نعم، أنا باكستاني","summary":"تركيب نحوي: السؤال بـ «هل» والجواب بـ «نعم»، وجنسيات المذكر والمؤنث.","segments":[{"body":["مثال أولًا: هل أنت باكستاني؟ نعم، أنا باكستاني.","«هل» كلمة نضعها في أول الجملة لنسأل سؤالًا جوابه نعم أو لا.","إذا كان الجواب صحيحًا نقول: نعم. وإذا لم يكن صحيحًا نقول: لا.","الجنسية للرجل: باكستانيّ. وللمرأة: باكستانيّة.","القاعدة: نزيد ة في آخر الجنسية لنجعلها مؤنثة. تركيّ، تركيّة. مصريّ، مصريّة. سوريّ، سوريّة."],"examples":["هَلْ أَنْتَ بَاكِسْتَانِيٌّ؟ نَعَمْ، أَنَا بَاكِسْتَانِيٌّ.","هَلْ أَنْتِ بَاكِسْتَانِيَّةٌ؟ نَعَمْ، أَنَا بَاكِسْتَانِيَّةٌ.","تُرْكِيٌّ، تُرْكِيَّةٌ.","مِصْرِيٌّ، مِصْرِيَّةٌ.","سُورِيٌّ، سُورِيَّةٌ."],"questions":[{"question":"ما وظيفة «هل»؟","options":["تسأل عن الاسم","تسأل سؤالًا جوابه نعم أو لا","تسأل عن المكان","تعني: أنا"],"answer":1,"explanation":"«هل» لسؤال النعم واللا."},{"question":"مؤنث «تركي» هو:","options":["أتراك","تركيا","تركيان","تركية"],"answer":3,"explanation":"تركي، تركية."},{"question":"اختر السؤال الصحيح لرجل:","options":["هل أنتَ مصري؟","هل أنتَ مصرية؟","هل أنتِ مصري؟","هل أنا مصري؟"],"answer":0,"explanation":"رجل: أنتَ مصري."},{"question":"ما الجواب عن سؤال جوابه «صحيح»؟","options":["من","لا","نعم","هل"],"answer":2,"explanation":"«نعم» تعني: صحيح."},{"question":"امرأة من سوريا تقول:","options":["أنا سوري","هو سوري","أنا سورية","أنت سورية"],"answer":2,"explanation":"أنا + سورية."}]},{"body":["مثال ثانٍ: من أين أنت؟ أنا من باكستان.","هنا نسأل عن البلد بـ «من أين». والجواب يبدأ بـ «أنا من» ثم البلد.","فرّق بين السؤالين. سؤال الجنسية: هل أنت مصري؟ سؤال البلد: من أين أنت؟","البلد يأتي بعد «من»: من مصر، من تركيا، من سوريا. والجنسية تأتي بعد «أنا»: أنا مصري.","مثال: هي مصرية. هي من مصر. نقول الجملتين معًا بسهولة."],"examples":["مِنْ أَيْنَ أَنْتَ؟ أَنَا مِنْ بَاكِسْتَان.","أَنَا تُرْكِيٌّ. أَنَا مِنْ تُرْكِيَا.","هِيَ مِصْرِيَّةٌ. هِيَ مِنْ مِصْر.","هُوَ سُورِيٌّ. هُوَ مِنْ سُورِيَا."],"questions":[{"question":"أي جملة تعطي البلد؟","options":["أنا مصري","هو مصري","أنا من مصر","هي مصرية"],"answer":2,"explanation":"البلد بعد «من»."},{"question":"أي جملة تعطي الجنسية؟","options":["أنا من تركيا","كيف حالك","أنا تركي","من أين أنت"],"answer":2,"explanation":"الجنسية: تركي."},{"question":"اكمل: هي ... مصر. (البلد)","options":["من","نعم","هل","هذا"],"answer":0,"explanation":"هي من مصر."},{"question":"اكمل: هو ... (جنسية رجل من سوريا)","options":["من سوريا","سورية","سوريا","سوري"],"answer":3,"explanation":"جنسية الرجل: سوري."},{"question":"اختر أسلوب السؤال عن البلد:","options":["من أين أنت؟","هل أنت؟","ما اسمك؟","كيف حالك؟"],"answer":0,"explanation":"من أين = ما البلد."}]}]},{"id":"abyb1-005","title":"أنا طالب وهي مدرّسة: المهن والضمائر","summary":"كلمات الدرس الرابع: أخ وأخت وصديق ومدرس ومهندس وطبيب وطالب، مع هو وهي وأنا وأنت.","segments":[{"body":["نتعلم كلمات جديدة عن الناس: أخ، أخت، صديق، صديقة.","ونتعلم مهنًا. «مهنة» هي عمل الشخص. مدرّس، مهندس، طبيب، طالب.","لكل كلمة مذكر ومؤنث: مدرّس ومدرّسة، مهندس ومهندسة، طبيب وطبيبة، طالب وطالبة.","القاعدة سهلة: المذكر بلا علامة، والمؤنث ينتهي بتاء مربوطة (ة).","وأخ وأخت مختلفان في الشكل: الأخ رجل، والأخت امرأة. هذه كلمات خاصة نحفظها."],"examples":["أَخٌ، أُخْتٌ.","صَدِيقٌ، صَدِيقَةٌ.","مُدَرِّسٌ، مُدَرِّسَةٌ.","مُهَنْدِسٌ، مُهَنْدِسَةٌ.","طَبِيبٌ، طَبِيبَةٌ.","طَالِبٌ، طَالِبَةٌ."],"questions":[{"question":"مؤنث «مهندس»:","options":["مهندسة","مهندسون","مهندسي","مهندسان"],"answer":0,"explanation":"نزيد تاء مربوطة."},{"question":"ما «المهنة»؟","options":["عمل الشخص","بلد الشخص","اسم الشخص","حال الشخص"],"answer":0,"explanation":"المهنة هي العمل."},{"question":"أي كلمة مذكر؟","options":["مدرسة","طالبة","طبيب","طبيبة"],"answer":2,"explanation":"طبيب بلا تاء مربوطة."},{"question":"الأخت هي:","options":["مدرس","صديق","امرأة من الأسرة","رجل من الأسرة"],"answer":2,"explanation":"أخت: بنت من الأسرة نفسها."},{"question":"مؤنث «صديق»:","options":["صديقان","أصدقاء","صديقة","صدّيق"],"answer":2,"explanation":"صديق، صديقة."}]},{"body":["نربط الكلمات بالضمائر. «الضمير» كلمة تأخذ مكان الاسم.","أنا: أتكلم عن نفسي. أنت: أتكلم مع شخص أمامي. هو: رجل غائب. هي: امرأة غائبة.","أنا طالب. أنتَ مدرّس. هو مهندس. هي طبيبة.","لا نحتاج في العربية إلى فعل «يكون» هنا. نضع الضمير ثم الكلمة مباشرة. أنا طالب. أي: أنا + طالب.","هذا جزء مهم: الجملة الاسمية البسيطة تتكون من ضمير + اسم."],"examples":["أَنَا طَالِبٌ.","أَنْتَ مُدَرِّسٌ.","هُوَ مُهَنْدِسٌ.","هِيَ طَبِيبَةٌ.","أَنَا طَالِبَةٌ."],"questions":[{"question":"ما الضمير؟","options":["كلمة تأخذ مكان الاسم","سؤال","مهنة","اسم بلد"],"answer":0,"explanation":"مثل: أنا، أنت، هو، هي."},{"question":"كيف تقول: أنا طالب. (امرأة تتكلم)؟","options":["هي طالبة","أنا طالب","هو طالبة","أنا طالبة"],"answer":3,"explanation":"المتكلمة امرأة: طالبة."},{"question":"اختر الجملة الصحيحة:","options":["هي طبيبة","هي طبيب","أنا هي طبيب","هو طبيبة"],"answer":0,"explanation":"هي مع المؤنث."},{"question":"«أنت» نستعملها مع:","options":["بلد","شخص أمامنا","أنفسنا","شخص غائب"],"answer":1,"explanation":"أنت للمخاطب."},{"question":"هل نحتاج فعل «يكون» في «أنا طالب»؟","options":["لا","نعم دائمًا","فقط للنساء","فقط للأطفال"],"answer":0,"explanation":"نضع الضمير ثم الاسم مباشرة."}]}]},{"id":"abyb1-006","title":"أرقام من واحد إلى خمسة","summary":"تعلم الأعداد الأولى من الوحدة الأولى.","segments":[{"body":["الأعداد في الوحدة الأولى من ١ إلى ٥.","واحد، اثنان، ثلاثة، أربعة، خمسة. نقرأها بالترتيب مرات كثيرة.","الرقم بالأرقام العربية: ١ ٢ ٣ ٤ ٥. وهذه الأرقام تُكتب هكذا في الكتاب.","المصطلح «عدد»: كلمة نقولها لنعدّ الأشياء. المصطلح «رقم»: الشكل الذي نكتبه.","سنستعمل الأعداد في الوحدات القادمة عندما نتكلم عن الأسرة والبيت."],"examples":["واحِد: ١","اثْنَانِ: ٢","ثَلَاثَة: ٣","أَرْبَعَة: ٤","خَمْسَة: ٥"],"questions":[{"question":"كم الرقم ٣؟","options":["ثلاثة","أربعة","اثنان","واحد"],"answer":0,"explanation":"٣ هو ثلاثة."},{"question":"ما العدد بعد «أربعة»؟","options":["اثنان","واحد","ثلاثة","خمسة"],"answer":3,"explanation":"الترتيب: ٤ ثم ٥."},{"question":"ما الفرق بين العدد والرقم؟","options":["لا فرق","العدد للكبار فقط","الرقم كلمة فقط","العدد كلمة والرقم شكل مكتوب"],"answer":3,"explanation":"العدد كلمة، والرقم علامة مكتوبة."},{"question":"اكتب بالكلمة: ١","options":["خمسة","واحد","أربعة","اثنان"],"answer":1,"explanation":"١ = واحد."}]},{"body":["نتدرب على ترتيب الأعداد.","ثلاثة قبل أربعة. وأربعة قبل خمسة. وواحد قبل اثنين.","نقول: واحد، اثنان، ثلاثة. ثم: أربعة، خمسة.","في آخر درس العدّ نربط كل عدد بالصورة المناسبة. إذا رأيت خمسة أقلام نقول: خمسة أقلام.","المصطلح «قلم»: أداة نكتب بها."],"examples":["واحِد، اثْنَانِ، ثَلَاثَة.","أَرْبَعَة، خَمْسَة."],"questions":[{"question":"اكمل: واحد، اثنان، ...","options":["أربعة","لا شيء","خمسة","ثلاثة"],"answer":3,"explanation":"بعد اثنين ثلاثة."},{"question":"أي رقم يدل على «خمسة»؟","options":["٣","١","٢","٥"],"answer":3,"explanation":"٥ يدل على خمسة."},{"question":"عند عدّ أقلام الكتاب نقول:","options":["أهلًا وسهلًا","من أين أنت","مع السلامة","واحد، اثنان، ثلاثة..."],"answer":3,"explanation":"نعدّ بالترتيب."}]}]},{"id":"abyb1-007","title":"الأصوات: خ وك، وأول حروف الكتابة","summary":"الصوتان خ وك، وكتابة الحروف أ د ذ من الوحدة الأولى.","segments":[{"body":["في هذا الدرس نسمع صوتين قريبين: خ وك.","صوت الكاف (ك) نقوله من مقدمة الحلق. صوت الخاء (خ) نقوله من الحلق وفيه احتكاك.","الخاء تشبه صوت الاحتكاك في كلمة مثل: خالد. الكاف في كلمة مثل: كيف.","من كلمات الحوار: خالد، خليل، خولة، خديجة، بخير. كلها فيها حرف الخاء.","المصطلح «صوت»: ما نسمعه حين ننطق الحرف. والمصطلح «حرف»: الشكل الذي نكتبه."],"examples":["خَالِد","خَلِيل","خَوْلَة","خَدِيجَة","بِخَيْر","كَيْفَ"],"questions":[{"question":"أي كلمة فيها الخاء؟","options":["مدرس","كيف","أنا","خالد"],"answer":3,"explanation":"خالد تبدأ بالخاء."},{"question":"أي كلمة فيها الكاف؟","options":["كيف","بخير","خولة","خليل"],"answer":0,"explanation":"كيف تبدأ بالكاف."},{"question":"الخاء والكاف:","options":["صوتان مختلفان","صوت واحد","كلمتان","حرفان متماثلان"],"answer":0,"explanation":"الصوتان قريبان لكنهما مختلفان."},{"question":"بخير فيها:","options":["كاف","ذال","خاء","دال"],"answer":2,"explanation":"بخير: ب + خ + ي + ر."}]},{"body":["الكتابة: في الوحدة الأولى نتعلم ثلاثة حروف: أ، د، ذ.","العربية تُكتب من اليمين إلى اليسار. هذا عكس الإنجليزية.","الألف (أ): خط مستقيم. في أنا، في سأل، في توضّأ.","الدال (د): قوس صغير. في دار، في مدرس، في واحد.","الذال (ذ): تشبه الدال، لكن فوقها نقطة. في هذا، في ذهب، في لذيذ.","الحروف تتغير قليلًا حسب مكانها: في أول الكلمة أو وسطها أو آخرها. لكن د وذ وأ لا تتصل بما بعدها."],"examples":["أَنَا، سَأَلَ.","دَار، مُدَرِّس، وَاحِد.","هَذَا، ذَهَبَ، لَذِيذ."],"questions":[{"question":"من أي جهة نكتب العربية؟","options":["من اليمين إلى اليسار","من أعلى فقط","من اليسار إلى اليمين","لا فرق"],"answer":0,"explanation":"العربية من اليمين إلى اليسار."},{"question":"ما الفرق بين د وذ؟","options":["لا فرق","الذال فوقها نقطة","الدال فوقها نقطة","الدال خط مستقيم"],"answer":1,"explanation":"الذال = دال + نقطة."},{"question":"في أي كلمة حرف الذال؟","options":["أنا","واحد","هذا","دار"],"answer":2,"explanation":"هذا فيها الذال."},{"question":"في أي كلمة حرف الدال؟","options":["ذهب","دار","أنا","هذا"],"answer":1,"explanation":"دار تبدأ بدال."}]}]},{"id":"abyb1-008","title":"هذه صورة أسرتي","summary":"الحوار الأول من الوحدة الثانية: أفراد الأسرة، وسؤال «من هذا؟» و«من هذه؟».","segments":[{"body":["الأسرة هي: الأب والأم والأولاد. وقد تشمل الجد والجدة والعم والعمة.","علي يرى صديقه عمّار صورة أسرته. يقول: هذه صورة أسرتي. «صورة» أي: رسم من الكاميرا. «أسرتي» أي: أسرة لي.","عمّار يسأل: من هذا؟ نسأل بـ «من» عن الأشخاص. و«هذا» للرجل.","علي يجيب: هذا والدي عدنان، وهو مهندس. «والدي» أي: أبي. و«والد» كلمة رسمية للأب.","ثم يسأل عمّار عن امرأة: من هذه؟ فيجيب علي: هذه والدتي سعيدة، وهي طبيبة. «والدتي» أي: أمي.","عندما يعجبك شيء تقول: ما شاء الله. هذه عبارة تقال عند الإعجاب."],"examples":["عَلِيّ: هَذِهِ صُورَةُ أُسْرَتِي.","عَمَّار: مَا شَاءَ اللَّهُ! مَنْ هَذَا؟","عَلِيّ: هَذَا وَالِدِي عَدْنَان وَهُوَ مُهَنْدِس.","عَمَّار: وَمَنْ هَذِهِ؟","عَلِيّ: هَذِهِ وَالِدَتِي سَعِيدَة وَهِيَ طَبِيبَة."],"questions":[{"question":"ماذا تعني «أسرتي»؟","options":["أسرة لي","أسرة لك","أسرة له","أسرة لها"],"answer":0,"explanation":"الياء تعني: لي."},{"question":"نسأل عن رجل في الصورة بـ:","options":["من هذه؟","من هذا؟","ما هذه؟","أين هذه؟"],"answer":1,"explanation":"من هذا = من هو هذا الرجل؟"},{"question":"نسأل عن امرأة في الصورة بـ:","options":["من هذه؟","هل هذا؟","كم هذا؟","من هذا؟"],"answer":0,"explanation":"هذه للمؤنث."},{"question":"«والدتي» هي:","options":["أختي","جدي","أمي","أبي"],"answer":2,"explanation":"والدة = أم."},{"question":"متى نقول «ما شاء الله»؟","options":["عند الوداع","عند الغضب","عند الإعجاب","عند السؤال عن الاسم"],"answer":2,"explanation":"عبارة إعجاب جميلة."}]},{"body":["علي يكمل: هذا أخي عيسى وهو طالب. وهذه أختي عبلة وهي معلمة.","ثم يشير إلى الجد والجدة: هذا جدي، وهذه جدتي.","الجد هو أبو الأب أو أبو الأم. الجدة هي أم الأب أو أم الأم.","المصطلح «معلمة»: امرأة تعلم الطلاب. والمذكر «معلم».","لاحظ تكرار النمط: هذا + اسم الشخص. هذه + اسم المرأة. ثم هو أو هي + المهنة."],"examples":["هَذَا أَخِي عِيسَى وَهُوَ طَالِب.","هَذِهِ أُخْتِي عَبْلَة وَهِيَ مُعَلِّمَة.","وَهَذَا جَدِّي. وَهَذِهِ جَدَّتِي."],"questions":[{"question":"«جدي» تعني:","options":["صديقي","أخو أبي","ابن أخي","أبو أبي أو أبو أمي"],"answer":3,"explanation":"الجد: أبو الأب أو أبو الأم."},{"question":"مؤنث «معلم»:","options":["معلمون","معلمة","معلمان","علماء"],"answer":1,"explanation":"نزيد تاء مربوطة."},{"question":"اختر الصحيح:","options":["هذا أختي وهو طالبة","هذا أخي وهي طالب","هذه أختي وهو طالبة","هذه أختي وهي طالبة"],"answer":3,"explanation":"هذه + هي + المؤنث."},{"question":"اكمل: هذا ... عيسى (أخي)","options":["أختي","جدتي","والدتي","أخي"],"answer":3,"explanation":"أخي مذكر."},{"question":"الجدة هي:","options":["صديقة","أم الأب أو أم الأم","بنت الأخ","أخت الأب"],"answer":1,"explanation":"جدة = أم الأب أو الأم."}]}]},{"id":"abyb1-009","title":"شجرة العائلة: عم وعمة وابن وابنة","summary":"الحوار الثاني: كلمات الأسرة الموسعة وإضافة الضمير: والده، جدّه، عمّه، ابنه.","segments":[{"body":["في الحوار الثاني عمر وعثمان ينظران إلى شجرة. «شجرة» هنا شجرة العائلة. هي صورة تُظهر الأسرة.","عمر يسأل: هل هذه شجرة؟ عثمان يجيب: نعم، هذه أسرة الرسول صلى الله عليه وسلم.","ثم يقول عثمان: هذا والده عبد الله. أي: والد محمد. الهاء في آخر الكلمة تعني: له.","وهذه والدته آمنة. أي: أم محمد.","ثم يذكر العم والعمة: هذا عمه العباس. وهذه عمته صفية.","والابن والابنة: هذا ابنه القاسم. وهذه ابنته فاطمة."],"examples":["عُمَر: هَلْ هَذِهِ شَجَرَةٌ؟","عُثْمَان: نَعَمْ، هَذِهِ أُسْرَةُ الرَّسُولِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ.","عُثْمَان: هَذَا وَالِدُهُ عَبْدُ اللهِ.","عُمَر: وَهَذِهِ وَالِدَتُهُ آمِنَةُ.","عُثْمَان: وَهَذَا عَمُّهُ الْعَبَّاسُ.","عُثْمَان: وَهَذِهِ عَمَّتُهُ صَفِيَّةُ.","عُمَر: وَهَذَا ابْنُهُ الْقَاسِمُ."],"questions":[{"question":"ماذا تعني الهاء في «والده»؟","options":["له","لك","لي","لها"],"answer":0,"explanation":"الهاء في آخر الاسم تعني: له."},{"question":"«العم» هو:","options":["جد","أخو الأب","ابن الأخ","أخو الأم"],"answer":1,"explanation":"العم: أخو الأب."},{"question":"«العمة» هي:","options":["جدة","أخت الأب","أخت الأم","بنت العم"],"answer":1,"explanation":"العمة: أخت الأب."},{"question":"«الابن» ضد:","options":["الجد","العم","الأب","الابنة"],"answer":3,"explanation":"ابن للمذكر وابنة للمؤنث."},{"question":"«شجرة العائلة» تُظهر:","options":["الأعداد","أفراد الأسرة","الجنسيات","البلاد"],"answer":1,"explanation":"هي رسم للأسرة."}]},{"body":["نتعلم تغيير الكلمة حسب صاحبها. أولًا: لي، ثم له.","والدي = أبي. والده = أبوه. أخي = أخ لي. أخوه = أخ له.","في الكتاب تدريب: حوّل. مثال: هذا والدي عدنان. نحوّله: هذا والده عدنان.","القاعدة: ياء المتكلم (ي) تصير هاء (ـه) عندما نتكلم عن شخص آخر.","مثال للمؤنث: هذه والدتي خديجة. هذه والدته خديجة."],"examples":["هَذَا وَالِدِي عَدْنَان. هَذَا وَالِدُهُ عَدْنَان.","هَذِهِ أُخْتِي سَلْمَى. هَذِهِ أُخْتُهُ سَلْمَى.","هَذَا عَمِّي عُثْمَان. هَذَا عَمُّهُ عُثْمَان."],"questions":[{"question":"حوّل: هذا جدي. إلى:","options":["هذا جدها","هذا جده","هذا جدك","هذا جدنا"],"answer":1,"explanation":"ي تصير ه."},{"question":"حوّل: هذه عمتي. إلى:","options":["هذه عمتك","هذه عمتي","هذه عمته","هذا عمه"],"answer":2,"explanation":"عمتي تصير عمته."},{"question":"«ابنه» تعني:","options":["ابن لك","ابن لها","ابن لي","ابن له"],"answer":3,"explanation":"الهاء: له."},{"question":"«أخي» و«أخوه»: ما الفرق؟","options":["الثاني للأطفال","الأول لي والثاني له","لا فرق","الأول للنساء"],"answer":1,"explanation":"ي = لي، ه = له."}]}]},{"id":"abyb1-010","title":"أين سعيد؟ سعيد في الغرفة","summary":"الحوار الثالث: السؤال عن المكان بـ «أين»، واستعمال «في»، وفعلين: يتوضأ ويقرأ.","segments":[{"body":["الحوار الثالث في بيت. الأم والأب يبحثان عن الأولاد وقت الفجر.","«أذان الفجر» نداء الصلاة قبل الشمس. المؤذن يقول: الله أكبر.","الأب يسأل: أين الأولاد؟ «أين» تسأل عن المكان.","الأم تجيب: سعد في الحمام يتوضأ. «الحمام» غرفة الماء. «يتوضأ» أي: يغسل أعضاءه للصلاة.","الأب يسأل: وأين سعيد؟ الأم: سعيد في الغرفة يقرأ القرآن.","الأب: وأين سعيدة؟ الأم: سعيدة في المصلى تصلي. «المصلى» مكان الصلاة في البيت.","كلمة «في» تدل على المكان: في الحمام، في الغرفة، في المصلى."],"examples":["الْأُمّ: هَذَا أَذَانُ الْفَجْرِ.","الْأَب: أَيْنَ الْأَوْلَادُ؟","الْأُمّ: سَعْدٌ فِي الْحَمَّامِ يَتَوَضَّأُ.","الْأَب: وَأَيْنَ سَعِيدٌ؟","الْأُمّ: سَعِيدٌ فِي الْغُرْفَةِ يَقْرَأُ الْقُرْآنَ.","الْأُمّ: سَعِيدَةُ فِي الْمُصَلَّى تُصَلِّي."],"questions":[{"question":"«أين» تسأل عن:","options":["الشخص","الحال","العدد","المكان"],"answer":3,"explanation":"أين = في أي مكان."},{"question":"«في» تدل على:","options":["الوقت فقط","الجنسية","المكان","الاسم"],"answer":2,"explanation":"في الحمام: المكان."},{"question":"أين سعد؟","options":["في الحمام","في المصلى","في الغرفة","في المسجد"],"answer":0,"explanation":"الأم قالت: سعد في الحمام."},{"question":"ماذا تفعل سعيدة؟","options":["تقرأ","تتوضأ","تصلي","تنام"],"answer":2,"explanation":"سعيدة في المصلى تصلي."},{"question":"«الحمام» هو:","options":["مكان النوم","مكان الماء والغسل","مكان الصلاة","مكان الأكل"],"answer":1,"explanation":"الحمام: غرفة الماء."}]},{"body":["نكمل الحوار. الأب يسأل: أين المعطف؟ «المعطف» ثوب نلبسه في البرد.","سعد يجيب: هذا هو المعطف يا والدي. نقول «هذا هو» عندما نعطي الشيء الذي سُئل عنه.","الأب: وأين النظارة؟ سعيد: هذه هي النظارة يا والدي. «النظارة» شيء نضعه على العين لنرى جيدًا.","لاحظ: المعطف مذكر، فنقول: هذا هو. والنظارة مؤنث، فنقول: هذه هي.","في النهاية الأب يقول: هيا بنا إلى المسجد. «هيا بنا» أي: لنذهب معًا. و«المسجد» بيت الصلاة العام."],"examples":["الْأَب: أَيْنَ الْمِعْطَفُ؟","سَعْد: هَذَا هُوَ الْمِعْطَفُ يَا وَالِدِي.","الْأَب: وَأَيْنَ النَّظَّارَةُ؟","سَعِيد: هَذِهِ هِيَ النَّظَّارَةُ يَا وَالِدِي.","الْأَب: هَيَّا بِنَا إِلَى الْمَسْجِدِ."],"questions":[{"question":"أين النظارة؟ الجواب:","options":["هذه هو النظارة","هذه هي النظارة","هذا هو النظارة","هذا هي النظارة"],"answer":1,"explanation":"النظارة مؤنث: هذه هي."},{"question":"«المعطف» نلبسه في:","options":["الصلاة فقط","الحمام","البرد","الأكل"],"answer":2,"explanation":"المعطف ثوب البرد."},{"question":"ماذا تعني «هيا بنا»؟","options":["ما اسمك","لنذهب معًا","من أنت","مع السلامة"],"answer":1,"explanation":"دعوة للذهاب معًا."},{"question":"«المسجد» هو:","options":["المدرسة","غرفة النوم","الحمام","بيت الصلاة العام"],"answer":3,"explanation":"المسجد مكان صلاة الجماعة."}]}]},{"id":"abyb1-011","title":"كلمات البيت والصلاة","summary":"مفردات الوحدة الثانية: مسجد، مصلى، غرفة، حمام، معطف، نظارة، شجرة، صورة، أذان، قرآن.","segments":[{"body":["نتعلم كلمات المكان أولًا: بيت، غرفة، حمام، مسجد، مصلى.","الغرفة جزء من البيت. الحمام للغسل والوضوء. المسجد مكان عام للصلاة. المصلى مكان صغير للصلاة.","ونتعلم أشياء: صورة، شجرة، معطف، نظارة، قرآن.","«القرآن» كتاب المسلمين. نقول: يقرأ القرآن.","ونتعلم أفعالًا: يصلي، يقرأ، يتوضأ. الفعل كلمة تدل على عمل، مثل: يقرأ (عمل القراءة)."],"examples":["غُرْفَة، حَمَّام، مَسْجِد، مُصَلَّى.","صُورَة، شَجَرَة، مِعْطَف، نَظَّارَة، قُرْآن.","يُصَلِّي، يَقْرَأُ، يَتَوَضَّأُ."],"questions":[{"question":"«الفعل» هو:","options":["اسم مكان","اسم شخص","كلمة تدل على عمل","رقم"],"answer":2,"explanation":"مثل: يقرأ، يصلي."},{"question":"أي كلمة اسم مكان؟","options":["يقرأ","مسجد","شجرة","نظارة"],"answer":1,"explanation":"المسجد مكان."},{"question":"نضع النظارة على:","options":["العين","القدم","اليد","الرأس فقط"],"answer":0,"explanation":"النظارة للعين."},{"question":"اختر الفعل:","options":["أسرة","معطف","حمام","يتوضأ"],"answer":3,"explanation":"يتوضأ فعل."},{"question":"«يقرأ القرآن» أي:","options":["يأكل","يسافر","يقرأ كتاب المسلمين","يكتب"],"answer":2,"explanation":"القرآن كتاب يُقرأ."}]},{"body":["أعداد جديدة من الكتاب: ستة، سبعة، ثمانية، تسعة، عشرة.","ستة: ٦. سبعة: ٧. ثمانية: ٨. تسعة: ٩. عشرة: ١٠.","مع الأعداد الخمسة السابقة صار عندنا عشرة أعداد: واحد، اثنان، ثلاثة، أربعة، خمسة، ستة، سبعة، ثمانية، تسعة، عشرة.","نعدّ الأقلام في صورة الكتاب: ستة أقلام، سبعة أقلام، وهكذا.","تدرّب: قل الأعداد بصوت عالٍ من واحد إلى عشرة."],"examples":["سِتَّة: ٦","سَبْعَة: ٧","ثَمَانِيَة: ٨","تِسْعَة: ٩","عَشَرَة: ١٠"],"questions":[{"question":"كم ٨؟","options":["سبعة","ستة","ثمانية","تسعة"],"answer":2,"explanation":"٨ = ثمانية."},{"question":"العدد بعد تسعة:","options":["ستة","عشرة","خمسة","ثمانية"],"answer":1,"explanation":"بعد ٩ يأتي ١٠."},{"question":"ما رقم «سبعة»؟","options":["٦","٨","٩","٧"],"answer":3,"explanation":"سبعة = ٧."},{"question":"كم عددًا عندنا من ١ إلى ١٠؟","options":["ثمانية","عشرة","خمسة","تسعة"],"answer":1,"explanation":"من ١ إلى ١٠ عشرة أعداد."}]}]},{"id":"abyb1-012","title":"أين المعطف؟ هذا هو المعطف","summary":"التراكيب النحوية: السؤال بـ «أين»، والجواب بـ «هذا هو»، وأفعال الصلاة والقراءة.","segments":[{"body":["مثال أول من الكتاب: أين المعطف؟ هذا هو المعطف.","مثال ثانٍ: أين الغرفة؟ هذه هي الغرفة.","القاعدة: للشيء المذكر نقول: هذا هو. وللشيء المؤنث نقول: هذه هي.","كيف نعرف المؤنث؟ غالبًا ينتهي بتاء مربوطة: غرفة، نظارة، صورة، شجرة.","والمذكر غالبًا لا ينتهي بها: معطف، حمام، مسجد، مصلى."],"examples":["أَيْنَ الْمِعْطَفُ؟ هَذَا هُوَ الْمِعْطَفُ.","أَيْنَ الْغُرْفَةُ؟ هَذِهِ هِيَ الْغُرْفَةُ.","أَيْنَ الْمَسْجِدُ؟ هَذَا هُوَ الْمَسْجِدُ.","أَيْنَ النَّظَّارَةُ؟ هَذِهِ هِيَ النَّظَّارَةُ."],"questions":[{"question":"أين الحمام؟ الجواب:","options":["هذا هو الحمام","هذه هو الحمام","هذه هي الحمام","هذا هي الحمام"],"answer":0,"explanation":"الحمام مذكر."},{"question":"أين الصورة؟ الجواب:","options":["هذا هو الصورة","هذا هي الصورة","هذه هو الصورة","هذه هي الصورة"],"answer":3,"explanation":"الصورة مؤنث."},{"question":"أي كلمة مؤنث؟","options":["حمام","شجرة","معطف","مسجد"],"answer":1,"explanation":"تنتهي بتاء مربوطة."},{"question":"اكمل: أين الابن؟ هذا ... الابن.","options":["هما","هي","هذه","هو"],"answer":3,"explanation":"الابن مذكر."},{"question":"اكمل: أين الابنة؟ هذه ... الابنة.","options":["هي","هو","نحن","هذا"],"answer":0,"explanation":"الابنة مؤنث."}]},{"body":["مثال ثانٍ من الكتاب: أين سعيد؟ سعيد في الغرفة، يقرأ القرآن.","وللمؤنث: أين سعيدة؟ سعيدة في الغرفة، تقرأ القرآن.","لاحظ الفعل: للمذكر يقرأ، وللمؤنث تقرأ. للمذكر يصلي، وللمؤنث تصلي. للمذكر يتوضأ، وللمؤنث تتوضأ.","القاعدة: الفعل للمذكر يبدأ بحرف ي. والفعل للمؤنث يبدأ بحرف ت.","مثال: صالح في المسجد يصلي. صالحة في المصلى تصلي."],"examples":["أَيْنَ سَعِيد؟ سَعِيدٌ فِي الْغُرْفَةِ، يَقْرَأُ الْقُرْآنَ.","أَيْنَ سَعِيدَة؟ سَعِيدَةُ فِي الْغُرْفَةِ، تَقْرَأُ الْقُرْآنَ.","صَالِحٌ فِي الْمَسْجِدِ يُصَلِّي.","صَالِحَةُ فِي الْمُصَلَّى تُصَلِّي.","شَرِيفٌ فِي الْحَمَّامِ يَتَوَضَّأُ.","شَرِيفَةُ فِي الْبَيْتِ تَتَوَضَّأُ."],"questions":[{"question":"الفعل للمؤنث «... القرآن»:","options":["تقرأ","نقرأ","أقرأ","يقرأ"],"answer":0,"explanation":"للمؤنث نبدأ بحرف ت."},{"question":"الفعل للمذكر «... في المسجد»:","options":["أصلي","يصلي","نصلي","تصلي"],"answer":1,"explanation":"للمذكر نبدأ بحرف ي."},{"question":"اختر الصحيح:","options":["فاطمة في المصلى تصلون","فاطمة في المصلى تصلي","فاطمة في المصلى أصلي","فاطمة في المصلى يصلي"],"answer":1,"explanation":"فاطمة مؤنث، الفعل بالتاء."},{"question":"اختر الصحيح:","options":["بدر في البيت يتوضئون","بدر في البيت يتوضأ","بدر في البيت أتوضأ","بدر في البيت تتوضأ"],"answer":1,"explanation":"بدر مذكر، الفعل بالياء."},{"question":"أين زينب؟ زينب ... تقرأ القرآن.","options":["هو الغرفة","في الغرفة","هل الغرفة","من الغرفة"],"answer":1,"explanation":"نستعمل «في» للمكان."}]}]},{"id":"abyb1-013","title":"من هذا؟ وما هذا؟","summary":"الفرق بين «من» للأشخاص و«ما» للأشياء، مع أمثلة من الكتاب.","segments":[{"body":["مثال من الكتاب: من هذا؟ هذا أحمد. من هذه؟ هذه زينب.","وللأشياء: ما هذا؟ هذا مسجد. ما هذه؟ هذه صورة.","القاعدة: نسأل بـ «من» عن الشخص. ونسأل بـ «ما» عن الشيء.","ثم نراقب «هذا» و«هذه». للمذكر هذا، وللمؤنث هذه. هذا مسجد. هذه صورة.","المصطلح «شخص»: إنسان. المصطلح «شيء»: ما ليس إنسانًا، مثل الكتاب والبيت."],"examples":["مَنْ هَذَا؟ هَذَا أَحْمَدُ.","مَنْ هَذِهِ؟ هَذِهِ زَيْنَبُ.","مَا هَذَا؟ هَذَا مَسْجِدٌ.","مَا هَذِهِ؟ هَذِهِ صُورَةٌ."],"questions":[{"question":"نسأل عن إنسان بـ:","options":["أين","من","ما","كم"],"answer":1,"explanation":"من للأشخاص."},{"question":"نسأل عن شيء بـ:","options":["من","هل","ما","نعم"],"answer":2,"explanation":"ما للأشياء."},{"question":"أمام صورة امرأة اسمها ليلى نسأل:","options":["ما هذه؟","ما هذا؟","من هذا؟","من هذه؟"],"answer":3,"explanation":"امرأة: من هذه؟"},{"question":"أمام شجرة نسأل:","options":["ما هذه؟","كيف هذه؟","من هذا؟","من هذه؟"],"answer":0,"explanation":"شجرة شيء مؤنث: ما هذه؟"},{"question":"أمام مسجد نسأل:","options":["ما هذا؟","ما هذه؟","من هذا؟","من هذه؟"],"answer":0,"explanation":"مسجد شيء مذكر: ما هذا؟"}]},{"body":["نتدرب على الحوار الكامل. مثال من الكتاب: السلام عليكم. وعليكم السلام. ما هذه؟ هذه صورة أخي. هو مهندس. ما شاء الله.","نغيّر الكلمات ونحافظ على الشكل: هذه صورة + أخي/أختي/والدي/والدتي.","ثم نضيف المهنة: هو مهندس. هي طبيبة. هو معلم. هي طالبة.","ثم نضيف عبارة الإعجاب: ما شاء الله.","بهذا الشكل ننتقل من جملة واحدة إلى حوار صغير."],"examples":["السَّلَامُ عَلَيْكُمْ.","وَعَلَيْكُمُ السَّلَامُ.","مَا هَذِهِ؟","هَذِهِ صُورَةُ أَخِي. هُوَ مُهَنْدِسٌ.","مَا شَاءَ اللَّهُ."],"questions":[{"question":"كيف نقول: هذه صورة أختي. هي ...؟","options":["طبيب","طبيبة","معلم","مهندس"],"answer":1,"explanation":"أخت مؤنث، فنقول: طبيبة."},{"question":"ما الجملة المناسبة بعد: ما هذه؟","options":["هذا أخي","أنا طالب","نعم","هذه صورة أخي"],"answer":3,"explanation":"صورة مؤنث، فنقول هذه."},{"question":"اختر عبارة الإعجاب:","options":["مع السلامة","ما شاء الله","من أين أنت","كيف حالك"],"answer":1,"explanation":"ما شاء الله."},{"question":"اكمل: هذه صورة ... (أخ لي)","options":["أختي","والدتي","أخي","جدتي"],"answer":2,"explanation":"أخ: أخي."}]}]},{"id":"abyb1-014","title":"قراءة وكتابة: الأسرة والحروف ب ت ث","summary":"تدريب قراءة كلمات الأسرة، وكتابة الحروف ب ت ث من الوحدة الثانية.","segments":[{"body":["نقرأ كلمات الأسرة من الكتاب: والد، والدة، أخ، أخت، ابن، ابنة، جد، جدة، عم، عمة، أسرة، شجرة.","نصل كل كلمة بمعناها. مثال: ابن مع ابنة، جد مع جدة، عم مع عمة. كل زوج مذكر ومؤنث.","في التدريب كلمات أخرى: يصلي، مصلى، مسجد، يقرأ، الرسول، القرآن. نقرؤها بالترتيب.","قاعدة تذكّر: كل كلمة مؤنثة غالبًا تنتهي بتاء مربوطة.","اقرأ الكلمات بصوت عالٍ ثلاث مرات. القراءة المتكررة تساعد على الحفظ."],"examples":["وَالِد، وَالِدَة.","أَخ، أُخْت.","ابْن، ابْنَة.","جَدّ، جَدَّة.","عَمّ، عَمَّة."],"questions":[{"question":"مؤنث «جد»:","options":["أجداد","جدان","جدي","جدة"],"answer":3,"explanation":"جد: جدة."},{"question":"مؤنث «عم»:","options":["أعمام","عمة","عمان","عمي"],"answer":1,"explanation":"عم: عمة."},{"question":"مؤنث «ابن»:","options":["أبناء","بنون","ابنان","ابنة"],"answer":3,"explanation":"ابن: ابنة."},{"question":"أي كلمة مذكر؟","options":["جدة","والد","والدة","ابنة"],"answer":1,"explanation":"والد بلا تاء مربوطة."}]},{"body":["الكتابة: نتعلم الحروف ب، ت، ث.","الباء (ب): نقطة واحدة تحت الحرف. في بخير، طبيب، طالب.","التاء (ت): نقطتان فوق الحرف. في صلّى، يتوضأ، أنت.","الثاء (ث): ثلاث نقاط فوق الحرف. في ثوب، عثمان، كرّات.","الثلاثة تتشابه في الشكل. الفرق في عدد النقاط ومكانها فقط. النقطة تحت الباء، والنقطتان فوق التاء، والثلاث فوق الثاء."],"examples":["بَ: بِخَيْر، طَبِيب، طَالِب.","تَ: يُصَلِّي، يَتَوَضَّأُ، أَنْت.","ثَ: ثَوْب، عُثْمَان."],"questions":[{"question":"عدد نقاط الباء:","options":["ثلاث فوقه","لا نقاط","اثنتان فوقه","واحدة تحت الحرف"],"answer":3,"explanation":"ب: نقطة تحت."},{"question":"عدد نقاط التاء:","options":["ثلاث فوقه","اثنتان فوق الحرف","واحدة تحت","لا نقاط"],"answer":1,"explanation":"ت: نقطتان فوق."},{"question":"عدد نقاط الثاء:","options":["واحدة تحت","اثنتان فوقه","لا نقاط","ثلاث فوق الحرف"],"answer":3,"explanation":"ث: ثلاث نقاط فوق."},{"question":"في أي كلمة حرف الثاء؟","options":["ثوب","طبيب","بخير","أنت"],"answer":0,"explanation":"ثوب تبدأ بثاء."},{"question":"في أي كلمة حرف التاء؟","options":["ثوب","بخير","طالب","أنت"],"answer":3,"explanation":"أنت فيها تاء في آخرها."}]}]},{"id":"abyb1-015","title":"أين تسكن؟ أسكن في حي المطار","summary":"الحوار الأول من الوحدة الثالثة: السؤال عن السكن والحي والبيت والشقة.","segments":[{"body":["الوحدة الثالثة عن «السكن». السكن هو المكان الذي نعيش فيه: بيت أو شقة.","أحمد وحسان يتعارفان. أحمد يسأل: أين تسكن؟ ومعناه: في أي مكان بيتك؟","حسان يجيب: أسكن في حي المطار. «الحي» جزء من المدينة، فيه بيوت وشوارع. «المطار» مكان الطائرات.","ثم يسأل حسان: وأين تسكن أنت؟ فيقول أحمد: أسكن في حي الجامعة.","لاحظ الفعل: «تسكن» لمن نكلمه، و«أسكن» لنفسي. أنا أسكن. أنت تسكن."],"examples":["أَحْمَد: أَيْنَ تَسْكُنُ؟","حَسَّان: أَسْكُنُ فِي حَيِّ الْمَطَارِ.","حَسَّان: وَأَيْنَ تَسْكُنُ أَنْتَ؟","أَحْمَد: أَسْكُنُ فِي حَيِّ الْجَامِعَةِ."],"questions":[{"question":"ماذا تعني «أين تسكن؟»","options":["من أنت؟","في أي مكان تعيش؟","ما اسمك؟","كيف حالك؟"],"answer":1,"explanation":"أين = المكان، تسكن = تعيش."},{"question":"ما «الحي»؟","options":["عدد","جزء من المدينة","غرفة","اسم شخص"],"answer":1,"explanation":"الحي: جزء من المدينة."},{"question":"كيف أقول: أنا أعيش في حي الجامعة؟","options":["نسكن حي","أسكن في حي الجامعة","يسكن في حي الجامعة","تسكن في حي الجامعة"],"answer":1,"explanation":"أنا: أسكن."},{"question":"نقول لمن نكلمه: ...؟","options":["أين نسكن","أين يسكن","أين تسكن","أين أسكن"],"answer":2,"explanation":"للمخاطب: تسكن."}]},{"body":["حسان يسأل: هل تسكن في بيت؟ هذا سؤال جوابه نعم أو لا. نستعمل «هل».","أحمد: نعم، أسكن في بيت. ويسأل: وهل تسكن في بيت؟ حسان: لا، أسكن في شقة.","«البيت» مبنى كامل لأسرة. «الشقة» جزء من مبنى كبير، وفي المبنى شقق كثيرة.","ثم يسأل أحمد: ما رقم شقتك؟ حسان: خمسة (٥). وما رقم بيتك؟ أحمد: تسعة (٩).","«رقم» عدد نكتبه على الباب ليعرف الناس العنوان. المصطلح «عنوان»: مكان السكن بالتفصيل."],"examples":["حَسَّان: هَلْ تَسْكُنُ فِي بَيْتٍ؟","أَحْمَد: نَعَمْ، أَسْكُنُ فِي بَيْتٍ.","حَسَّان: لَا، أَسْكُنُ فِي شَقَّةٍ.","أَحْمَد: مَا رَقْمُ شَقَّتِكَ؟","حَسَّان: ٥. وَمَا رَقْمُ بَيْتِكَ؟","أَحْمَد: ٩."],"questions":[{"question":"ما الفرق بين البيت والشقة؟","options":["البيت في المطار فقط","لا فرق","البيت مبنى كامل والشقة جزء من مبنى","الشقة أكبر دائمًا"],"answer":2,"explanation":"الشقة في مبنى فيه شقق كثيرة."},{"question":"ما رقم شقة حسان؟","options":["١٠","٥","٣","٩"],"answer":1,"explanation":"حسان قال: ٥."},{"question":"ما جواب «هل تسكن في شقة؟» إن لم تسكن فيها؟","options":["نعم","من","لا","أين"],"answer":2,"explanation":"لا تعني: ليس صحيحًا."},{"question":"ما معنى «رقم شقتك»؟","options":["عدد على باب الشقة","بلدك","اسمك","جنسيتك"],"answer":0,"explanation":"الرقم عدد على الباب."}]}]},{"id":"abyb1-016","title":"أريد شقة من فضلك","summary":"الحوار الثاني: بين مستأجر ومؤجر، وطلب شقة بأدب.","segments":[{"body":["في الحوار الثاني رجل يريد شقة. هو «المستأجر»: من يدفع مالًا ليسكن. والمؤجر: صاحب الشقة.","المستأجر يقول: السلام عليكم. المؤجر: وعليكم السلام.","ثم يقول: أريد شقة من فضلك. «أريد» أي: أطلب وأرغب. و«من فضلك» عبارة أدب، مثل: please.","المؤجر: لدينا شقة جميلة. «لدينا» أي: عندنا. «جميلة» أي: حسنة المنظر.","نتعلم هنا طريقة الطلب: أريد + الشيء + من فضلك."],"examples":["الْمُسْتَأْجِر: أُرِيدُ شَقَّةً مِنْ فَضْلِكَ.","الْمُؤَجِّر: لَدَيْنَا شَقَّةٌ جَمِيلَةٌ."],"questions":[{"question":"ماذا تعني «أريد»؟","options":["أطلب وأرغب","هذا","هناك","أنا"],"answer":0,"explanation":"أريد: أطلب."},{"question":"ما وظيفة «من فضلك»؟","options":["الأدب في الطلب","الوداع","السؤال عن المكان","السؤال عن الاسم"],"answer":0,"explanation":"عبارة أدب."},{"question":"ماذا تعني «لدينا»؟","options":["عندنا","عندي","عندك","عنده"],"answer":0,"explanation":"لدينا = عندنا."},{"question":"من «المؤجر»؟","options":["المدرس","من يشتري","من يسكن فقط","صاحب الشقة"],"answer":3,"explanation":"المؤجر يعطي الشقة للسكن مقابل مال."}]},{"body":["المستأجر يسأل أسئلة أخرى. كم غرفة في الشقة؟ «كم» تسأل عن العدد.","المؤجر: في الشقة خمس غرف. ثم: في أي دور الشقة؟ «الدور» هو طابق المبنى.","المؤجر: الشقة في الدور الخامس. «الخامس» عدد ترتيبي: الأول، الثاني، الثالث، الرابع، الخامس.","ثم المستأجر: أريد مشاهدة الشقة. أي: أريد أن أنظر إليها. المؤجر: تفضّل، ادخل. هذا باب الشقة.","المستأجر: هذه شقة جميلة. «تفضل» كلمة ترحيب وتقديم: تفضل، ادخل."],"examples":["الْمُسْتَأْجِر: كَمْ غُرْفَةً فِي الشَّقَّةِ؟","الْمُؤَجِّر: فِي الشَّقَّةِ خَمْسُ غُرَفٍ.","الْمُسْتَأْجِر: فِي أَيِّ دَوْرٍ الشَّقَّةُ؟","الْمُؤَجِّر: الشَّقَّةُ فِي الدَّوْرِ الْخَامِسِ.","الْمُسْتَأْجِر: أُرِيدُ مُشَاهَدَةَ الشَّقَّةِ.","الْمُؤَجِّر: تَفَضَّلْ، ادْخُلْ. هَذَا بَابُ الشَّقَّةِ.","الْمُسْتَأْجِر: هَذِهِ شَقَّةٌ جَمِيلَةٌ."],"questions":[{"question":"«كم» تسأل عن:","options":["الاسم","العدد","المكان","الجنسية"],"answer":1,"explanation":"كم غرفة؟ = ما عدد الغرف؟"},{"question":"ما «الدور»؟","options":["طابق في المبنى","غرفة صغيرة","باب","حي"],"answer":0,"explanation":"الدور: الطابق."},{"question":"كم غرفة في الشقة؟","options":["أربع","خمس","ست","ثلاث"],"answer":1,"explanation":"المؤجر قال: خمس غرف."},{"question":"متى نقول «تفضل»؟","options":["عندما نرحب بشخص","عند السؤال عن الاسم","عند الغضب","عند الوداع"],"answer":0,"explanation":"تفضل: ترحيب وتقديم."},{"question":"ماذا تعني «مشاهدة الشقة»؟","options":["النظر إلى الشقة","بيع الشقة","شراء الشقة","بناء الشقة"],"answer":0,"explanation":"المشاهدة: النظر."}]}]},{"id":"abyb1-017","title":"أثاث البيت: ماذا تريد لغرفة النوم؟","summary":"الحوار الثالث: بين مشترٍ وبائع، وكلمات الأثاث وغرف البيت.","segments":[{"body":["في الحوار الثالث مشترٍ يريد أثاثًا. «الأثاث» هو أشياء البيت: السرير والأريكة والسجادة.","المشتري: السلام عليكم. البائع: وعليكم السلام. أي خدمة؟ «خدمة» أي: ماذا تريد مني؟","المشتري: أريد بعض الأثاث. البائع: ماذا تريد لغرفة النوم؟","المشتري: أريد سريرًا وستارة. «سرير» نام عليه. «ستارة» تغطي النافذة.","البائع: وماذا تريد لغرفة الجلوس؟ المشتري: أريد أريكة وسجادة. «أريكة» كرسي كبير مريح. «سجادة» تُفرش على الأرض."],"examples":["الْمُشْتَرِي: أُرِيدُ بَعْضَ الْأَثَاثِ.","الْبَائِع: مَاذَا تُرِيدُ لِغُرْفَةِ النَّوْمِ؟","الْمُشْتَرِي: أُرِيدُ سَرِيرًا وَسِتَارَةً.","الْبَائِع: وَمَاذَا تُرِيدُ لِغُرْفَةِ الْجُلُوسِ؟","الْمُشْتَرِي: أُرِيدُ أَرِيكَةً وَسَجَّادَةً."],"questions":[{"question":"ما «الأثاث»؟","options":["أشياء البيت مثل السرير والأريكة","أسماء الناس","الأعداد","الجنسيات"],"answer":0,"explanation":"الأثاث: ما نضعه في البيت."},{"question":"ماذا يريد المشتري لغرفة النوم؟","options":["سخانًا ومرآة","فرنًا وثلاجة","سريرًا وستارة","أريكة وسجادة"],"answer":2,"explanation":"لغرفة النوم: سرير وستارة."},{"question":"ماذا يريد لغرفة الجلوس؟","options":["مرآة","أريكة وسجادة","فرنًا","سريرًا"],"answer":1,"explanation":"لغرفة الجلوس: أريكة وسجادة."},{"question":"ما «البائع»؟","options":["من يبيع","من يعلم","من يسكن","من يشتري"],"answer":0,"explanation":"البائع يبيع، والمشتري يشتري."}]},{"body":["البائع يسأل عن المطبخ: وماذا تريد للمطبخ؟ المشتري: أريد فرنًا وثلاجة.","«المطبخ» مكان الطبخ. «الفرن» جهاز نطبخ فيه الخبز. «الثلاجة» جهاز نحفظ فيه الطعام باردًا.","للحمام: أريد سخانًا ومرآة. «السخان» جهاز يسخّن الماء. «المرآة» نرى فيها وجوهنا.","البائع: هل تريد شيئًا آخر؟ المشتري: شكرًا، أريد مشاهدة الأثاث. البائع: تفضل.","«شكرًا» كلمة نقولها عندما نشكر شخصًا."],"examples":["الْبَائِع: وَمَاذَا تُرِيدُ لِلْمَطْبَخِ؟","الْمُشْتَرِي: أُرِيدُ فُرْنًا وَثَلَّاجَةً.","الْبَائِع: وَمَاذَا تُرِيدُ لِلْحَمَّامِ؟","الْمُشْتَرِي: أُرِيدُ سَخَّانًا وَمِرْآةً.","الْبَائِع: هَلْ تُرِيدُ شَيْئًا آخَرَ؟","الْمُشْتَرِي: شُكْرًا، أُرِيدُ مُشَاهَدَةَ الْأَثَاثِ."],"questions":[{"question":"ماذا يريد المشتري للمطبخ؟","options":["سخانًا ومرآة","أريكة وسجادة","فرنًا وثلاجة","سريرًا وستارة"],"answer":2,"explanation":"للمطبخ: فرن وثلاجة."},{"question":"ما «الثلاجة»؟","options":["كرسي كبير","جهاز نحفظ فيه الطعام باردًا","جهاز يسخن الماء","غرفة النوم"],"answer":1,"explanation":"الثلاجة تبرّد الطعام."},{"question":"ما «السخان»؟","options":["جهاز للطبخ","للنظر","جهاز يسخن الماء","للجلوس"],"answer":2,"explanation":"السخان يسخن الماء."},{"question":"ماذا نقول عندما نشكر؟","options":["شكرًا","مع السلامة","أريد","من فضلك"],"answer":0,"explanation":"شكرًا للشكر."}]}]},{"id":"abyb1-018","title":"كلمات السكن: بيت وشقة وحي ودور","summary":"مفردات الوحدة الثالثة: السكن والمبنى والأثاث وغرف البيت.","segments":[{"body":["نجمع كلمات المكان: بيت، شقة، حي، دور، باب، غرفة، مطبخ، حمام.","غرف البيت: غرفة نوم، غرفة جلوس، مطبخ، حمام.","كلمة «غرفة نوم» جملة من كلمتين: غرفة + نوم. أي: غرفة للنوم. وغرفة جلوس: غرفة للجلوس.","هذه الكلمات المضافة تسمى «إضافة»: كلمتان تتبع إحداهما الأخرى.","مثال: حي الجامعة، حي المطار، باب الشقة، رقم البيت. كل واحدة إضافة."],"examples":["بَيْت، شَقَّة، حَيّ، دَوْر، بَاب.","غُرْفَةُ نَوْمٍ، غُرْفَةُ جُلُوسٍ، مَطْبَخ، حَمَّام.","حَيُّ الْجَامِعَةِ، حَيُّ الْمَطَارِ، بَابُ الشَّقَّةِ."],"questions":[{"question":"«غرفة نوم» أي:","options":["غرفة للجلوس","غرفة للأكل","غرفة للنوم","غرفة للصلاة"],"answer":2,"explanation":"نوم = النوم."},{"question":"أين نطبخ؟","options":["في المسجد","في المطبخ","في الحمام","في غرفة النوم"],"answer":1,"explanation":"المطبخ للطبخ."},{"question":"«باب الشقة» أي:","options":["شقة جديدة","باب تابع للشقة","دور","حي"],"answer":1,"explanation":"باب + الشقة."},{"question":"اختر إضافة:","options":["حي الجامعة","أنا أسكن","هل تسكن","من فضلك"],"answer":0,"explanation":"حي + الجامعة."}]},{"body":["الأثاث: سرير، أريكة، سجادة، ستارة، ثلاجة، فرن، سخان، مرآة.","ثلاجة وفرن في المطبخ. سخان ومرآة في الحمام. سرير في غرفة النوم. أريكة وسجادة في غرفة الجلوس.","أضداد صغيرة تساعدنا: جميل وغير جميل. نعم ولا.","كلمة «جميل» للمذكر، و«جميلة» للمؤنث. شقة جميلة. بيت جميل.","المصطلح «ضد»: الكلمة المعاكسة. ضد «نعم» هو «لا»."],"examples":["سَرِير، أَرِيكَة، سَجَّادَة، سِتَارَة.","ثَلَّاجَة، فُرْن، سَخَّان، مِرْآة.","شَقَّةٌ جَمِيلَةٌ. بَيْتٌ جَمِيلٌ."],"questions":[{"question":"أين نضع السرير عادة؟","options":["في المسجد","في غرفة النوم","في المطبخ","في الحمام"],"answer":1,"explanation":"السرير للنوم."},{"question":"أين نضع الفرن؟","options":["في الجامعة","في الحي","في غرفة النوم","في المطبخ"],"answer":3,"explanation":"الفرن في المطبخ."},{"question":"اختر الصحيح:","options":["بيت جميلة","شقة جميلة","غرفة جميل","شقة جميل"],"answer":1,"explanation":"المؤنث مع المؤنث."},{"question":"ضد «نعم»:","options":["من","لا","هل","أريد"],"answer":1,"explanation":"نعم ولا ضدان."}]}]},{"id":"abyb1-019","title":"هل تسكن في بيت؟ التراكيب الأساسية","summary":"أمثلة من الكتاب: هل تسكن، أسكن في، كم غرفة، في أي دور.","segments":[{"body":["مثال أول: هل تسكن في بيت؟ نعم، أسكن في بيت.","مثال ثانٍ: هل تسكن في بيت؟ لا، أسكن في شقة.","نبدأ السؤال بـ «هل» ونجيب بـ «نعم» أو «لا». ثم نكرر الجملة.","نضع «في» قبل المكان: في بيت، في شقة، في حي الجامعة.","القاعدة: أسكن في + المكان. تسكن في + المكان."],"examples":["هَلْ تَسْكُنُ فِي بَيْتٍ؟ نَعَمْ، أَسْكُنُ فِي بَيْتٍ.","هَلْ تَسْكُنُ فِي بَيْتٍ؟ لَا، أَسْكُنُ فِي شَقَّةٍ.","أَسْكُنُ فِي حَيِّ الْجَامِعَةِ."],"questions":[{"question":"اختر الجواب الصحيح لـ «هل تسكن في شقة؟» إن كنت تسكن في بيت:","options":["نعم، تسكن شقة","لا، تسكن في بيت","لا، أسكن في بيت","نعم، أسكن في بيت"],"answer":2,"explanation":"إن لم تكن في شقة تقول لا."},{"question":"ما الكلمة قبل المكان؟","options":["هل","في","كم","من"],"answer":1,"explanation":"في الحي، في البيت."},{"question":"اختر الجملة الصحيحة:","options":["في أسكن مكة","أسكن في مكة","أسكن مكة في","مكة أسكن في أنا"],"answer":1,"explanation":"أسكن + في + المكان."},{"question":"نسأل عن الحي بـ:","options":["هل أين؟","كم تسكن؟","من تسكن؟","أين تسكن؟"],"answer":3,"explanation":"أين = المكان."}]},{"body":["مثال ثالث: كم غرفة في الشقة؟ في الشقة خمس غرف.","«كم» تسأل عن العدد. بعدها نقول الشيء المعدود: كم غرفة؟","ثم مثال رابع: في أي دور الشقة؟ في الدور الخامس.","الأعداد الترتيبية: الأول، الثاني، الثالث، الرابع، الخامس. نستعملها مع الدور.","مثال: في الشقة ثلاث غرف، في الدور الثالث. وفي الشقة أربع غرف، في الدور الرابع."],"examples":["كَمْ غُرْفَةً فِي الشَّقَّةِ؟ فِي الشَّقَّةِ خَمْسُ غُرَفٍ.","فِي أَيِّ دَوْرٍ الشَّقَّةُ؟ فِي الدَّوْرِ الْخَامِسِ.","ثَلَاثُ غُرَفٍ فِي الدَّوْرِ الثَّالِثِ.","أَرْبَعُ غُرَفٍ فِي الدَّوْرِ الرَّابِعِ."],"questions":[{"question":"«كم غرفة؟» تسأل عن:","options":["لون الغرفة","مكان الغرفة","اسم الغرفة","عدد الغرف"],"answer":3,"explanation":"كم = عدد."},{"question":"الدور بعد «الرابع»:","options":["الثاني","الخامس","الأول","الثالث"],"answer":1,"explanation":"الترتيب: الرابع ثم الخامس."},{"question":"اكمل: في الدور ... (الترتيبي من ٣)","options":["الثالث","ثلاثة","الأول","الخامس"],"answer":0,"explanation":"الدور الثالث."},{"question":"«في أي دور؟» نجيب بـ:","options":["في الحي","خمس غرف","نعم","في الدور الخامس"],"answer":3,"explanation":"السؤال عن الدور."},{"question":"اختر السؤال عن العدد:","options":["من الشقة؟","أين الشقة؟","كم غرفة في الشقة؟","هل الشقة؟"],"answer":2,"explanation":"كم للعدد."}]}]},{"id":"abyb1-020","title":"أريد، لدينا، ماذا تريد؟","summary":"تركيب الطلب: أريد شقة، لدينا بيت جميل، ماذا تريد للمطبخ؟","segments":[{"body":["مثال أول: أريد شقة من فضلك. «أريد» نقولها عندما نطلب شيئًا.","أنا أريد. أنت تريد. نقول: أريد (أنا)، وتريد (أنت).","سؤال البائع: ماذا تريد؟ «ماذا» تسأل عن الشيء. الجواب: أريد سريرًا.","وللمكان نقول: ماذا تريد لغرفة النوم؟ أريد سريرًا وستارة.","ملاحظة: في آخر «سريرًا» وفي «فرنًا» علامة تنوين النصب: ـً. هذا سيأتي لاحقًا بالتدريج."],"examples":["أُرِيدُ شَقَّةً مِنْ فَضْلِكَ.","مَاذَا تُرِيدُ؟ أُرِيدُ سَرِيرًا.","مَاذَا تُرِيدُ لِغُرْفَةِ النَّوْمِ؟ أُرِيدُ سِتَارَةً."],"questions":[{"question":"نسأل البائع: ...؟ أريد سريرًا","options":["هل تسكن","من أنت","ماذا تريد","كم الساعة"],"answer":2,"explanation":"ماذا = ما الشيء."},{"question":"أنا أقول:","options":["نريد","تريد","أريد","يريد"],"answer":2,"explanation":"أنا: أريد."},{"question":"أنت تسأل شخصًا: ماذا ...؟","options":["أريدون","تريد","يريد","أريد"],"answer":1,"explanation":"لمن أمامك: تريد."},{"question":"«من فضلك» نقولها:","options":["عند النوم","في الطلب","في الوداع","عند الاسم"],"answer":1,"explanation":"عبارة أدب."}]},{"body":["مثال ثانٍ: لدينا شقة جميلة. ولدينا بيت جميل.","«لدينا» نستعملها مع البائع: عندنا. معناها: نحن نملك.","نصف الشيء بكلمة جميلة: شقة جميلة. المؤنث مع المؤنث.","ونتعلم جملة جديدة: أريد مشاهدة الشقة. ثم يقول المؤجر: هذه هي الشقة، هذه شقة جميلة.","للمذكر: بيت جميل. للمؤنث: شقة جميلة."],"examples":["لَدَيْنَا شَقَّةٌ جَمِيلَةٌ.","لَدَيْنَا بَيْتٌ جَمِيلٌ.","أُرِيدُ مُشَاهَدَةَ الشَّقَّةِ.","هَذِهِ هِيَ الشَّقَّةُ. هَذِهِ شَقَّةٌ جَمِيلَةٌ."],"questions":[{"question":"اختر الجملة الصحيحة:","options":["لدينا غرفة جميل","لدينا شقة جميلة","لدينا شقة جميل","لدينا بيت جميلة"],"answer":1,"explanation":"شقة مؤنث، جميلة."},{"question":"«لدينا» تعني:","options":["عنده","عندك","عندنا","عندي"],"answer":2,"explanation":"لدينا = عندنا."},{"question":"ماذا تقول لتنظر إلى الشقة؟","options":["كم غرفة؟","هل تسكن؟","أريد مشاهدة الشقة","من هذا؟"],"answer":2,"explanation":"المشاهدة: النظر."},{"question":"اكمل: لدينا ... جميل (مذكر)","options":["غرفة","شقة","بيت","سجادة"],"answer":2,"explanation":"بيت مذكر."}]}]},{"id":"abyb1-021","title":"أيام الأسبوع","summary":"من الصفحة الإضافية في الوحدة الثالثة: أيام الأسبوع وشهر محرم.","segments":[{"body":["الأسبوع سبعة أيام. نقرؤها بالترتيب كما في الكتاب: السبت، الأحد، الإثنين، الثلاثاء، الأربعاء، الخميس، الجمعة.","يوم الجمعة يوم مهم عند المسلمين، فيه صلاة الجمعة.","المصطلح «أسبوع»: سبعة أيام. المصطلح «يوم»: ليل ونهار معًا.","في الكتاب جدول لشهر محرّم: الأيام ١ إلى ٣٠ موزعة على أسابيع.","السبت أول يوم في الجدول عند الكتاب."],"examples":["السَّبْت، الْأَحَد، الْإِثْنَيْن.","الثُّلَاثَاء، الْأَرْبِعَاء.","الْخَمِيس، الْجُمُعَة."],"questions":[{"question":"كم يومًا في الأسبوع؟","options":["ستة","سبعة","خمسة","ثمانية"],"answer":1,"explanation":"الأسبوع سبعة أيام."},{"question":"اليوم بعد السبت:","options":["الجمعة","الإثنين","الخميس","الأحد"],"answer":3,"explanation":"السبت ثم الأحد."},{"question":"اليوم قبل الجمعة:","options":["الأحد","السبت","الخميس","الثلاثاء"],"answer":2,"explanation":"الخميس ثم الجمعة."},{"question":"ما «الأسبوع»؟","options":["سبعة أيام","يوم واحد","شهر","سنة"],"answer":0,"explanation":"أسبوع = ٧ أيام."}]},{"body":["نتدرب على ترتيب الأيام. نكمل الأيام الناقصة.","السبت، ... ، الإثنين. اليوم الناقص: الأحد.","الثلاثاء، الأربعاء، ... ، الجمعة. اليوم الناقص: الخميس.","نربط كل يوم بنشاط. مثال: يوم الجمعة نصلي في المسجد.","قل الأيام السبعة بصوت عالٍ ثلاث مرات."],"examples":["السَّبْتُ، الْأَحَدُ، الْإِثْنَيْنِ.","الثُّلَاثَاءُ، الْأَرْبِعَاءُ، الْخَمِيسُ."],"questions":[{"question":"اكمل: السبت، ... ، الإثنين","options":["الأربعاء","الخميس","الأحد","الجمعة"],"answer":2,"explanation":"الأحد."},{"question":"اكمل: الثلاثاء، ... ، الخميس","options":["الجمعة","السبت","الأربعاء","الأحد"],"answer":2,"explanation":"الأربعاء."},{"question":"اختر يومًا من أيام الأسبوع:","options":["الحي","الدور","الباب","الخميس"],"answer":3,"explanation":"الخميس يوم."},{"question":"اليوم الأخير في الجدول:","options":["الأحد","الإثنين","الجمعة","السبت"],"answer":2,"explanation":"الجمعة آخر الأسبوع هنا."}]}]},{"id":"abyb1-022","title":"قراءة وكتابة: الحروف ج ح خ","summary":"قراءة كلمات السكن، وكتابة الحروف ج ح خ.","segments":[{"body":["نقرأ كلمات الوحدة: بيت، شقة، دور، مطبخ، سرير، ستارة، أريكة، سجادة، غرفة جلوس، غرفة نوم، حمام.","نصل الكلمات بمعانيها: نعم ضد لا. تسكن فعل. حي جزء من مدينة. جميلة صفة. ثلاجة جهاز. رقم عدد. أثاث أشياء البيت.","القراءة تساعدنا على رؤية الحرف في الكلمة.","مثال: كلمة «شقة» فيها ثلاثة حروف قبل التاء المربوطة: ش، ق، ة.","اقرأ الكلمات من اليمين إلى اليسار."],"examples":["بَيْت، شَقَّة، دَوْر.","مَطْبَخ، سَرِير، سِتَارَة.","أَرِيكَة، سَجَّادَة، غُرْفَةُ جُلُوسٍ."],"questions":[{"question":"اختر ضد «نعم»:","options":["لا","أريد","شقة","حي"],"answer":0,"explanation":"نعم ولا."},{"question":"اختر جهازًا:","options":["رقم","بيت","ثلاجة","حي"],"answer":2,"explanation":"الثلاجة جهاز."},{"question":"«أثاث» تعني:","options":["أعداد","جنسيات","أشياء البيت","أسماء"],"answer":2,"explanation":"الأثاث: أشياء البيت."},{"question":"نقرأ العربية من:","options":["اليمين إلى اليسار","أسفل إلى أعلى","اليسار إلى اليمين","لا اتجاه"],"answer":0,"explanation":"اتجاه القراءة."}]},{"body":["الكتابة: نتعلم ثلاثة حروف: ج، ح، خ. شكلها قريب، والنقطة تفرّق بينها.","الجيم (ج): نقطة واحدة تحت الحرف. في جميلة، سجادة، سراج.","الحاء (ح): بلا نقطة. في حي، الحمد، صباح.","الخاء (خ): نقطة واحدة فوق الحرف. في خمس، سخان، ينسخ.","إذا رأيت كلمة «حي» فأولها حاء بلا نقطة. وإذا رأيت «خمس» فأولها خاء بنقطة فوقها."],"examples":["جَ: جَمِيلَة، سَجَّادَة، سِرَاج.","حَ: حَيّ، الْحَمْد، صَبَاح.","خَ: خَمْس، سَخَّان، يَنْسَخ."],"questions":[{"question":"أي حرف نقطته تحت؟","options":["د","خ","ح","ج"],"answer":3,"explanation":"الجيم: نقطة تحت."},{"question":"أي حرف بلا نقطة؟","options":["خ","ب","ح","ج"],"answer":2,"explanation":"الحاء بلا نقطة."},{"question":"أي حرف نقطته فوق؟","options":["ب","خ","ح","ج"],"answer":1,"explanation":"الخاء نقطة فوق."},{"question":"في كلمة «حي» الحرف الأول:","options":["ج","خ","ه","ح"],"answer":3,"explanation":"حي تبدأ بحاء."},{"question":"في كلمة «خمس» الحرف الأول:","options":["د","ج","ح","خ"],"answer":3,"explanation":"خمس تبدأ بخاء."}]}]},{"id":"abyb1-023","title":"متى تستيقظ؟ أستيقظ عند الفجر","summary":"الحوار الأول من الوحدة الرابعة: الاستيقاظ والصلاة والمدرسة.","segments":[{"body":["الوحدة الرابعة عن «الحياة اليومية». هي ما نفعله كل يوم من الصباح إلى الليل.","طارق يسأل طاهرًا: متى تستيقظ؟ «متى» تسأل عن الوقت. «تستيقظ» أي: تفتح عينيك من النوم.","طاهر يجيب: أستيقظ عند الفجر. «الفجر» أول الصباح قبل طلوع الشمس.","طارق: أين تصلي الفجر؟ طاهر: أصلي الفجر في المسجد.","نلاحظ أن الفعل مع «أنا» يبدأ بحرف أ: أستيقظ، أصلي. ومع «أنت» يبدأ بحرف ت: تستيقظ، تصلي."],"examples":["طَارِق: مَتَى تَسْتَيْقِظُ؟","طَاهِر: أَسْتَيْقِظُ عِنْدَ الْفَجْرِ.","طَارِق: أَيْنَ تُصَلِّي الْفَجْرَ؟","طَاهِر: أُصَلِّي الْفَجْرَ فِي الْمَسْجِدِ."],"questions":[{"question":"«متى» تسأل عن:","options":["الوقت","الاسم","المكان","العدد"],"answer":0,"explanation":"متى = في أي وقت."},{"question":"ما «الفجر»؟","options":["وقت الغروب","آخر الليل بعد العشاء","أول الصباح قبل الشمس","وقت الظهر"],"answer":2,"explanation":"الفجر: بداية الصباح."},{"question":"الفعل مع «أنا» يبدأ بحرف:","options":["ت","ي","ن","أ"],"answer":3,"explanation":"أستيقظ، أصلي."},{"question":"الفعل مع «أنت» يبدأ بحرف:","options":["ت","أ","ي","ن"],"answer":0,"explanation":"تستيقظ، تصلي."},{"question":"أين يصلي طاهر الفجر؟","options":["في المسجد","في البيت","في الحافلة","في المدرسة"],"answer":0,"explanation":"في المسجد."}]},{"body":["طارق: هل تنام بعد الصلاة؟ طاهر: لا، لا أنام بعد الصلاة.","«لا أنام» أي: لا أفعل النوم. نضع «لا» قبل الفعل لننفيه.","طارق: ماذا تفعل بعد الصلاة؟ طاهر: أقرأ القرآن.","طارق: ومتى تذهب إلى المدرسة؟ طاهر: أذهب الساعة السابعة. «الساعة» وقت اليوم: الساعة السابعة.","طارق: هل تذهب بالسيارة؟ طاهر: لا، أذهب بالحافلة. «الحافلة» سيارة كبيرة للركاب. «بـ» تعني: بواسطة."],"examples":["طَارِق: هَلْ تَنَامُ بَعْدَ الصَّلَاةِ؟","طَاهِر: لَا، لَا أَنَامُ بَعْدَ الصَّلَاةِ.","طَارِق: مَاذَا تَفْعَلُ بَعْدَ الصَّلَاةِ؟","طَاهِر: أَقْرَأُ الْقُرْآنَ.","طَارِق: وَمَتَى تَذْهَبُ إِلَى الْمَدْرَسَةِ؟","طَاهِر: أَذْهَبُ السَّاعَةَ السَّابِعَةَ.","طَارِق: هَلْ تَذْهَبُ بِالسَّيَّارَةِ؟","طَاهِر: لَا، أَذْهَبُ بِالْحَافِلَةِ."],"questions":[{"question":"«لا أنام» تعني:","options":["أنا أنام","أنت تنام","أنا لا أنام","هو ينام"],"answer":2,"explanation":"لا + أنام: نفي."},{"question":"ماذا يفعل طاهر بعد الصلاة؟","options":["يطبخ","يذهب للعمل","يقرأ القرآن","ينام"],"answer":2,"explanation":"أقرأ القرآن."},{"question":"كيف يذهب طاهر إلى المدرسة؟","options":["بالطائرة","بالحافلة","ماشيًا فقط","بالسيارة"],"answer":1,"explanation":"أذهب بالحافلة."},{"question":"«ماذا تفعل؟» تسأل عن:","options":["الاسم","الوقت","المكان","العمل"],"answer":3,"explanation":"ماذا تفعل = ما عملك."},{"question":"متى يذهب طاهر إلى المدرسة؟","options":["بعد العشاء","الساعة الخامسة","عند الفجر","الساعة السابعة"],"answer":3,"explanation":"الساعة السابعة."}]}]},{"id":"abyb1-024","title":"ماذا ستفعل يا طارق؟ سأكنس غرفة الجلوس","summary":"الحوار الثاني: يوم العطلة وأعمال البيت، واستعمال سين المستقبل.","segments":[{"body":["في الحوار الثاني الأسرة في البيت. الأم تقول: هذا يوم العطلة. والأب يقول: هذا يوم العمل.","«يوم العطلة» يوم لا نذهب فيه إلى العمل أو المدرسة. «يوم العمل» يوم نعمل فيه.","الأم تسأل طارقًا: ماذا ستفعل يا طارق؟ «ستفعل» أي: ماذا ستعمل بعد قليل؟","طارق: سأكنس غرفة الجلوس. «سـ» قبل الفعل تعني: في المستقبل، أي: بعد قليل أو غدًا.","«يكنس» أي: ينظف الأرض بالمكنسة."],"examples":["الْأُمّ: هَذَا يَوْمُ الْعُطْلَةِ.","الْأَب: هَذَا يَوْمُ الْعَمَلِ.","الْأُمّ: مَاذَا سَتَفْعَلُ يَا طَارِقُ؟","طَارِق: سَأَكْنُسُ غُرْفَةَ الْجُلُوسِ."],"questions":[{"question":"ما «يوم العطلة»؟","options":["يوم بلا عمل أو مدرسة","يوم الصلاة فقط","يوم النوم فقط","يوم العمل"],"answer":0,"explanation":"عطلة: راحة."},{"question":"ماذا تعني «سـ» قبل الفعل؟","options":["ضد نعم","في الماضي","في المستقبل","في الحاضر فقط"],"answer":2,"explanation":"س + فعل = مستقبل."},{"question":"«سأكنس» أي:","options":["سأقرأ","سأنظف الأرض","سأذهب","سأنام"],"answer":1,"explanation":"يكنس = ينظف الأرض."},{"question":"ماذا سيفعل طارق؟","options":["سينام","سيغسل الأطباق","سيكنس غرفة الجلوس","سيكوي الملابس"],"answer":2,"explanation":"سأكنس غرفة الجلوس."}]},{"body":["الأم تسأل الباقين. لفاطمة: وماذا ستفعلين يا فاطمة؟ لاحظ الياء في «ستفعلين» للمرأة.","فاطمة: سأكنس غرفة النوم. ولأحمد: وماذا ستفعل يا أحمد؟ أحمد: سأغسل الملابس.","ولطيفة: ماذا ستفعلين؟ لطيفة: سأكوي الملابس. «يكوي» أي: يجعل الثوب مستويًا بالمكواة.","الجدة: أنا سأغسل الأطباق. الجد: وأنا سأقرأ القرآن.","للمذكر: ستفعل. للمؤنث: ستفعلين. و«أنا» دائمًا: سأفعل."],"examples":["الْأُمّ: وَمَاذَا سَتَفْعَلِينَ يَا فَاطِمَةُ؟","فَاطِمَة: سَأَكْنُسُ غُرْفَةَ النَّوْمِ.","أَحْمَد: سَأَغْسِلُ الْمَلَابِسَ.","لَطِيفَة: سَأَكْوِي الْمَلَابِسَ.","الْجَدَّة: أَنَا سَأَغْسِلُ الْأَطْبَاقَ.","الْجَدّ: وَأَنَا سَأَقْرَأُ الْقُرْآنَ."],"questions":[{"question":"نسأل امرأة: ماذا ...؟","options":["ستفعل","ستفعلين","سيفعل","سأفعل"],"answer":1,"explanation":"للمؤنث: ستفعلين."},{"question":"«يغسل الملابس» أي:","options":["يكويها","يخيطها","ينظفها بالماء","يقرؤها"],"answer":2,"explanation":"غسل = تنظيف بالماء."},{"question":"«يكوي» نفعله على:","options":["الأطباق","الكتاب","الملابس","الأرض"],"answer":2,"explanation":"نكوي الملابس."},{"question":"من ستقرأ القرآن؟","options":["طارق","فاطمة","الجدة","الجد"],"answer":3,"explanation":"الجد قال: سأقرأ القرآن."},{"question":"نقول عن أنفسنا:","options":["ستغسل","ستغسلين","سأغسل","سيغسل"],"answer":2,"explanation":"أنا + سأ..."}]}]},{"id":"abyb1-025","title":"يوم العمل ويوم العطلة: كلمات الحياة اليومية","summary":"مفردات الوحدة: ينام، يستيقظ، يذهب، سيارة، حافلة، مدرسة، يكنس، يغسل، يكوي، ملابس، أطباق.","segments":[{"body":["نتعلم أفعالًا يومية: ينام، يستيقظ، يذهب.","ينام في الليل. يستيقظ في الصباح. يذهب إلى المدرسة.","ونتعلم وسائل المواصلات: سيارة، حافلة. «وسيلة» ما نركبه لنصل.","الساعة السابعة وقت الذهاب إلى المدرسة في الحوار.","نكوّن جملة: أستيقظ الساعة الخامسة. أذهب إلى المدرسة بالحافلة."],"examples":["يَنَامُ، يَسْتَيْقِظُ، يَذْهَبُ.","سَيَّارَة، حَافِلَة، مَدْرَسَة.","أَسْتَيْقِظُ السَّاعَةَ الْخَامِسَةَ."],"questions":[{"question":"ما الفعل المضاد لـ «ينام»؟","options":["يستيقظ","يذهب","يكوي","يغسل"],"answer":0,"explanation":"النوم والاستيقاظ ضدان."},{"question":"أي كلمة وسيلة مواصلات؟","options":["ملابس","حافلة","مدرسة","فجر"],"answer":1,"explanation":"الحافلة نركبها."},{"question":"نذهب إلى المدرسة بـ:","options":["الفرن","الثلاجة","الحافلة","المعطف"],"answer":2,"explanation":"بالحافلة."},{"question":"«الساعة السابعة» نقولها لـ:","options":["المكان","الجنسية","الوقت","الاسم"],"answer":2,"explanation":"الساعة وقت."}]},{"body":["أعمال البيت: يكنس، يغسل، يكوي.","يكنس الغرفة. يغسل الملابس. يغسل الأطباق. يكوي الملابس.","«الملابس» ما نلبسه. «الأطباق» أواني الأكل.","ونتعلم كلمات التسلية: تلفاز، كتاب، صحيفة. «التلفاز» جهاز نشاهد فيه البرامج. «الصحيفة» ورق فيه الأخبار.","الأفعال: يشاهد التلفاز، يقرأ الكتاب، يقرأ الصحيفة."],"examples":["يَكْنُسُ الْغُرْفَةَ. يَغْسِلُ الْمَلَابِسَ. يَكْوِي الْمَلَابِسَ.","تَغْسِلُ الْأَطْبَاقَ.","يُشَاهِدُ التِّلْفَازَ. يَقْرَأُ كِتَابًا. يَقْرَأُ صَحِيفَةً."],"questions":[{"question":"ما «الأطباق»؟","options":["أثاث غرفة النوم","ملابس","أواني الأكل","كتب"],"answer":2,"explanation":"الأطباق: أواني الطعام."},{"question":"نشاهد:","options":["الملابس","التلفاز","الصحيفة فقط","الأطباق"],"answer":1,"explanation":"نشاهد التلفاز."},{"question":"نقرأ:","options":["صحيفة","ملابس","أطباق","التلفاز"],"answer":0,"explanation":"نقرأ الصحيفة."},{"question":"أي فعل لتنظيف الأرض؟","options":["يسافر","يكوي","يشاهد","يكنس"],"answer":3,"explanation":"يكنس."}]}]},{"id":"abyb1-026","title":"متى تستيقظ يوم العطلة؟","summary":"الحوار الثالث: مبكرًا ومتأخرًا، والصباح، وصلاة الجمعة.","segments":[{"body":["الحوار الثالث بين عادل وفيصل. عادل يسأل: متى تستيقظ يوم العطلة؟","فيصل: أستيقظ مبكرًا. «مبكرًا» أي: في أول الوقت. وعادل يسأل: ومتى تستيقظ أنت؟","عادل: أستيقظ متأخرًا. «متأخرًا» أي: بعد الوقت المعتاد.","«مبكر» ضد «متأخر». الصباح الباكر مبكر، والظهر متأخر للاستيقاظ.","ويلاحظ الحرف ً في آخر الكلمتين: مبكرًا، متأخرًا. هذه علامة تنوين النصب."],"examples":["عَادِل: مَتَى تَسْتَيْقِظُ يَوْمَ الْعُطْلَةِ؟","فَيْصَل: أَسْتَيْقِظُ مُبَكِّرًا.","فَيْصَل: وَمَتَى تَسْتَيْقِظُ أَنْتَ؟","عَادِل: أَسْتَيْقِظُ مُتَأَخِّرًا."],"questions":[{"question":"ضد «مبكر»:","options":["سريع","كبير","جميل","متأخر"],"answer":3,"explanation":"المبكر ضد المتأخر."},{"question":"متى يستيقظ فيصل يوم العطلة؟","options":["مبكرًا","بعد العصر","متأخرًا","لا يستيقظ"],"answer":0,"explanation":"فيصل: أستيقظ مبكرًا."},{"question":"متى يستيقظ عادل؟","options":["عند الفجر","ليلًا","متأخرًا","مبكرًا"],"answer":2,"explanation":"عادل: أستيقظ متأخرًا."},{"question":"«مبكرًا» تعني:","options":["في الغروب","في أول الوقت","في الليل","بعد الوقت"],"answer":1,"explanation":"مبكرًا = early."}]},{"body":["فيصل يسأل عن الصباح: ماذا تفعل في الصباح؟ عادل: أشاهد التلفاز.","وعادل يسأل فيصلًا: وماذا تفعل أنت؟ فيصل: أقرأ صحيفة أو كتابًا.","«أو» تعني: واحدًا من الاثنين: صحيفة أو كتابًا.","ثم يسأل عادل عن الجمعة: أين تصلي الجمعة؟ فيصل: أصلي الجمعة في المسجد الكبير.","عادل: وأين تصلي أنت؟ فيصل: أصلي في المسجد الكبير أيضًا. «أيضًا» تعني: مثلك."],"examples":["فَيْصَل: مَاذَا تَفْعَلُ فِي الصَّبَاحِ؟","عَادِل: أُشَاهِدُ التِّلْفَازَ.","فَيْصَل: أَقْرَأُ صَحِيفَةً أَوْ كِتَابًا.","عَادِل: أَيْنَ تُصَلِّي الْجُمُعَةَ؟","فَيْصَل: أُصَلِّي الْجُمُعَةَ فِي الْمَسْجِدِ الْكَبِيرِ.","عَادِل: أُصَلِّي فِي الْمَسْجِدِ الْكَبِيرِ أَيْضًا."],"questions":[{"question":"ماذا تعني «أو»؟","options":["نعم","شكر","اختيار واحد من اثنين","وداع"],"answer":2,"explanation":"أو: اختيار."},{"question":"ماذا يفعل عادل في الصباح؟","options":["يغسل","يشاهد التلفاز","يقرأ كتابًا","يكنس"],"answer":1,"explanation":"عادل: أشاهد التلفاز."},{"question":"أين يصلي فيصل الجمعة؟","options":["في المدرسة","في المسجد الكبير","في الحافلة","في البيت"],"answer":1,"explanation":"المسجد الكبير."},{"question":"«أيضًا» تعني:","options":["مثل غيري","قبل","ضد","بعد"],"answer":0,"explanation":"أيضًا: too."}]}]},{"id":"abyb1-027","title":"الساعة والأعداد الترتيبية","summary":"الأعداد الترتيبية: الأول إلى الخامس، وقول الساعة.","segments":[{"body":["في الدرس نتعلم الترتيب: الأول، الثاني، الثالث، الرابع، الخامس.","الأول: رقم ١ في الترتيب. الثاني: رقم ٢. الثالث: ٣. الرابع: ٤. الخامس: ٥.","الفرق بين العدد والترتيب: واحد، اثنان، ثلاثة هي أعداد. الأول، الثاني، الثالث هي ترتيب.","نقول: الدور الخامس. الساعة الخامسة. الشقة في الدور الأول.","للمؤنث نزيد تاء: الأولى، الثانية، الثالثة، الرابعة، الخامسة."],"examples":["الْأَوَّل، الثَّانِي، الثَّالِث، الرَّابِع، الْخَامِس.","الْأُولَى، الثَّانِيَة، الثَّالِثَة، الرَّابِعَة، الْخَامِسَة."],"questions":[{"question":"ما الترتيبي من ٣؟","options":["الثاني","الأول","الثالث","الخامس"],"answer":2,"explanation":"٣ = الثالث."},{"question":"اكمل: الدور ... (٥)","options":["الأول","الرابع","الخامس","الثالث"],"answer":2,"explanation":"الدور الخامس."},{"question":"مؤنث «الرابع»:","options":["الرابعون","الرابعة","الرابعين","الرباعي"],"answer":1,"explanation":"الرابعة."},{"question":"ما الفرق بين «ثلاثة» و«الثالث»؟","options":["الأول عدد والثاني ترتيب","لا فرق","الأول ترتيب","الثاني للنساء فقط"],"answer":0,"explanation":"عدد وترتيب."}]},{"body":["الساعة نقولها بالترتيبي المؤنث: الساعة الواحدة، الثانية، الثالثة، الرابعة، الخامسة، السادسة، السابعة.","أمثلة: المدرسة الساعة السابعة. المسجد الساعة الثالثة. الطبيب الساعة الثانية. العم الساعة السادسة.","للساعة الأولى نقول: الواحدة. هذا شكل خاص.","نسأل: متى تذهب إلى المدرسة؟ ونجيب: أذهب الساعة السابعة.","نستعمل «في» ولا نحتاجها هنا: نقول مباشرة: الساعة السابعة."],"examples":["مَتَى تَذْهَبُ إِلَى الْمَدْرَسَةِ؟ أَذْهَبُ السَّاعَةَ السَّابِعَةَ.","الْبَيْتُ: السَّاعَةَ الْوَاحِدَةَ.","الطَّبِيبُ: السَّاعَةَ الثَّانِيَةَ.","الْمَسْجِدُ: السَّاعَةَ الثَّالِثَةَ."],"questions":[{"question":"الساعة التي بعد الثانية:","options":["الخامسة","الأولى","الثالثة","السابعة"],"answer":2,"explanation":"٢ ثم ٣."},{"question":"كيف نقول Seven o'clock؟","options":["الساعة سبع","الساعة السبعة","الساعة السابعة","الساعة السابع"],"answer":2,"explanation":"الساعة + ترتيبي مؤنث."},{"question":"اختر الساعة الصحيحة:","options":["الساعة خمسة","الساعة خمس","الساعة الخامسة","الساعة الخامس"],"answer":2,"explanation":"الساعة الخامسة."},{"question":"«الساعة الواحدة» تعني:","options":["الساعة ٥","الساعة ٢","الساعة ١","الساعة ٧"],"answer":2,"explanation":"الواحدة = ١."}]}]},{"id":"abyb1-028","title":"أنا أصلي وأنت تصلي: الفعل مع الضمائر","summary":"تركيب نحوي: الفعل مع أنا وأنت وهو وهي، والسؤال بـ ماذا ومتى وأين.","segments":[{"body":["مثال من الكتاب: أين تصلي الفجر؟ أصلي الفجر في المسجد.","الفعل يتغير مع الشخص. مع «أنا» نقول: أصلي. مع «أنت» نقول: تصلي. مع «هو» نقول: يصلي. مع «هي» نقول: تصلي.","إذا كان الفاعل امرأة غائبة نقول: هي تصلي. وإذا كان رجلًا: هو يصلي.","الحرف الأول من الفعل يدلنا على الشخص: أ (أنا)، ت (أنت أو هي)، ي (هو).","المصطلح «فاعل»: من يقوم بالفعل."],"examples":["أَنَا أُصَلِّي. أَنْتَ تُصَلِّي. هُوَ يُصَلِّي. هِيَ تُصَلِّي.","أَيْنَ تُصَلِّي الْفَجْرَ؟ أُصَلِّي الْفَجْرَ فِي الْمَسْجِدِ."],"questions":[{"question":"الفعل مع «هو»:","options":["نصلي","تصلي","أصلي","يصلي"],"answer":3,"explanation":"هو: يصلي."},{"question":"الفعل مع «هي»:","options":["أصلي","نصلي","يصلي","تصلي"],"answer":3,"explanation":"هي: تصلي."},{"question":"الفعل مع «أنا»:","options":["أصلي","نصلي","يصلي","تصلي"],"answer":0,"explanation":"أنا: أصلي."},{"question":"من «الفاعل» في «يقرأ أحمد»؟","options":["يقرأ","في","أحمد","القرآن"],"answer":2,"explanation":"أحمد يقوم بالقراءة."}]},{"body":["مثال ثانٍ: ماذا تفعل؟ أقرأ القرآن. وللمرأة: ماذا تفعلين؟ أقرأ القرآن.","للرجل نقول: ماذا تفعلُ؟ وللمرأة: ماذا تفعلين؟ النون والياء علامة المؤنثة المخاطبة.","ثم مثال: ماذا يفعل أحمد؟ يقرأ القرآن. ماذا تفعل خديجة؟ تقرأ القرآن.","نسأل: متى تذهب؟ أين تصلي؟ ماذا تفعل؟ كل سؤال يعطي معلومة مختلفة.","متى = وقت. أين = مكان. ماذا = عمل."],"examples":["مَاذَا تَفْعَلُ؟ أَقْرَأُ الْقُرْآنَ.","مَاذَا تَفْعَلِينَ؟ أَقْرَأُ الْقُرْآنَ.","مَاذَا يَفْعَلُ أَحْمَدُ؟ يَقْرَأُ الْقُرْآنَ.","مَاذَا تَفْعَلُ خَدِيجَةُ؟ تَقْرَأُ الْقُرْآنَ."],"questions":[{"question":"نسأل امرأة: ماذا ...؟","options":["تفعلين","يفعل","تفعل","أفعل"],"answer":0,"explanation":"للمؤنثة: تفعلين."},{"question":"«متى» تعطينا:","options":["المكان","الوقت","العمل","الاسم"],"answer":1,"explanation":"متى = وقت."},{"question":"ماذا تفعل خديجة؟ خديجة ... القرآن.","options":["يقرأ","نقرأ","أقرأ","تقرأ"],"answer":3,"explanation":"خديجة مؤنث."},{"question":"اختر السؤال عن المكان:","options":["كم تصلي؟","أين تصلي؟","ماذا تصلي؟","متى تصلي؟"],"answer":1,"explanation":"أين."},{"question":"ماذا يفعل أحمد؟ أحمد ... القرآن.","options":["يقرأ","أقرأ","تقرأ","تقرئين"],"answer":0,"explanation":"أحمد مذكر."}]}]},{"id":"abyb1-029","title":"الصلوات الخمس والمساجد","summary":"الفجر والظهر والعصر والمغرب والعشاء، وأين نصلي الجمعة.","segments":[{"body":["عند المسلمين خمس صلوات في اليوم. نذكرها بالترتيب: الفجر، الظهر، العصر، المغرب، العشاء.","الفجر قبل الشمس. الظهر عند منتصف النهار. العصر بعد الظهر. المغرب عند الغروب. العشاء في الليل.","وفي الكتاب أمثلة على المساجد: مسجد عمر للفجر، مسجد بلال للظهر، مسجد عثمان للعصر.","ثم: مسجد علي للمغرب، مسجد عمار للعشاء، ومسجد طارق للجمعة.","المصطلح «صلاة»: عبادة المسلم لله خمس مرات في اليوم."],"examples":["الْفَجْر، الظُّهْر، الْعَصْر.","الْمَغْرِب، الْعِشَاء.","الْجُمُعَة: أُصَلِّي الْجُمُعَةَ فِي الْمَسْجِدِ الْكَبِيرِ."],"questions":[{"question":"كم صلاة في اليوم؟","options":["خمس","ست","سبع","ثلاث"],"answer":0,"explanation":"خمس صلوات."},{"question":"الصلاة بعد الظهر:","options":["العشاء","الفجر","العصر","المغرب"],"answer":2,"explanation":"الظهر ثم العصر."},{"question":"الصلاة قبل الشمس:","options":["الظهر","العشاء","الفجر","العصر"],"answer":2,"explanation":"الفجر."},{"question":"الصلاة في الليل:","options":["العشاء","الظهر","الفجر","العصر"],"answer":0,"explanation":"العشاء."}]},{"body":["نتدرب على سؤال وجواب. مثال: أين تصلي الجمعة؟ أصلي في المسجد الكبير.","ثم: وأين تصلي أنت؟ أصلي في المسجد الكبير أيضًا.","نبدل المسجد ونتدرب: أين تصلي الفجر؟ أصلي الفجر في مسجد عمر.","في الدرس نسأل ونجيب مع زميل، كل واحد يسأل وكل واحد يجيب.","هذه الطريقة تعلم الكلام بسرعة."],"examples":["أَيْنَ تُصَلِّي الْجُمُعَةَ؟ أُصَلِّي فِي الْمَسْجِدِ الْكَبِيرِ.","أَيْنَ تُصَلِّي الْفَجْرَ؟ أُصَلِّي الْفَجْرَ فِي مَسْجِدِ عُمَرَ.","وَأَيْنَ تُصَلِّي أَنْتَ؟ أُصَلِّي هُنَا أَيْضًا."],"questions":[{"question":"أين تصلي الجمعة؟ الجواب:","options":["أذهب بالحافلة","أقرأ الصحيفة","أصلي في المسجد الكبير","أنام في المسجد"],"answer":2,"explanation":"نجيب عن المكان."},{"question":"نسأل: وأين تصلي ...؟","options":["أنا","هي","هو","أنت"],"answer":3,"explanation":"للمخاطب: أنت."},{"question":"اكمل: أصلي الفجر ... المسجد","options":["هل","من","ما","في"],"answer":3,"explanation":"في المسجد."},{"question":"هذه الطريقة تعلم:","options":["الكتابة فقط","الكلام","الرسم","الحساب"],"answer":1,"explanation":"السؤال والجواب يعلم الكلام."}]}]},{"id":"abyb1-030","title":"حياتي اليومية: نص كامل صغير","summary":"تجميع كل ما تعلمناه في الوحدة الرابعة في فقرة قصيرة.","segments":[{"body":["الآن نكتب فقرة قصيرة عن يومك. نستعمل ما تعلمنا.","أنا أستيقظ عند الفجر. أصلي الفجر في المسجد. أقرأ القرآن. بعد ذلك أذهب إلى المدرسة الساعة السابعة بالحافلة.","في يوم العطلة أستيقظ متأخرًا. أشاهد التلفاز وأقرأ صحيفة. أصلي الجمعة في المسجد الكبير.","في الفقرة نرى ترتيب الأحداث: أولًا، ثم، بعد ذلك.","المصطلح «فقرة»: جزء قصير من نص، فيه عدة جمل."],"examples":["أَنَا أَسْتَيْقِظُ عِنْدَ الْفَجْرِ.","أُصَلِّي الْفَجْرَ فِي الْمَسْجِدِ.","أَذْهَبُ إِلَى الْمَدْرَسَةِ بِالْحَافِلَةِ."],"questions":[{"question":"متى يستيقظ الكاتب في يوم العمل؟","options":["بعد الظهر","متأخرًا","بعد العشاء","عند الفجر"],"answer":3,"explanation":"أستيقظ عند الفجر."},{"question":"كيف يذهب إلى المدرسة؟","options":["بالقطار","بالحافلة","بالطائرة","بالسيارة"],"answer":1,"explanation":"بالحافلة."},{"question":"ماذا يفعل في يوم العطلة؟","options":["يغسل الأطباق فقط","يذهب إلى العمل","يشاهد التلفاز","لا يفعل شيئًا"],"answer":2,"explanation":"يشاهد التلفاز."},{"question":"ما «الفقرة»؟","options":["كلمة واحدة","رقم","حرف","جزء قصير من نص"],"answer":3,"explanation":"الفقرة: عدة جمل."}]},{"body":["نكتب عن يومك أنت. أولًا اسأل نفسك: متى أستيقظ؟ أين أصلي؟ ماذا أفعل بعد الصلاة؟","ثانيًا: كيف أذهب إلى العمل أو المدرسة؟ بالسيارة أو بالحافلة؟","ثالثًا: ماذا أفعل يوم العطلة؟","نستعمل: أستيقظ، أصلي، أقرأ، أذهب، أشاهد. كل الأفعال مع «أنا» وتبدأ بحرف أ.","اكتب ثلاث جمل على الأقل، ثم اقرأها بصوت عالٍ."],"examples":["أَسْتَيْقِظُ مُبَكِّرًا. أَقْرَأُ الْقُرْآنَ.","أَذْهَبُ إِلَى الْعَمَلِ بِالسَّيَّارَةِ.","يَوْمَ الْعُطْلَةِ أُشَاهِدُ التِّلْفَازَ."],"questions":[{"question":"كل الأفعال مع «أنا» تبدأ بحرف:","options":["أ","ن","ي","ت"],"answer":0,"explanation":"أ للمتكلم."},{"question":"اكمل: أنا ... الصحيفة","options":["أقرأ","نقرأ","تقرأ","يقرأ"],"answer":0,"explanation":"أقرأ."},{"question":"اختر سؤالًا عن الوقت:","options":["ماذا أستيقظ؟","متى أستيقظ؟","أين أستيقظ؟","كم أستيقظ؟"],"answer":1,"explanation":"متى = وقت."},{"question":"اكمل: أنا ... التلفاز يوم العطلة","options":["تشاهد","تشاهدين","أشاهد","يشاهد"],"answer":2,"explanation":"أشاهد."}]}]},{"id":"abyb1-031","title":"أين تذهب يا سالم؟ إلى المطعم","summary":"الحوار الأول من الوحدة الخامسة: الطعام والشراب، والوجبات الثلاث.","segments":[{"body":["الوحدة الخامسة عن «الطعام والشراب». الطعام ما نأكله، والشراب ما نشربه.","قاسم يسأل سالمًا: أين تذهب يا سالم؟ سالم: إلى المطعم. «المطعم» مكان نأكل فيه.","قاسم: كم وجبة تأكل في اليوم؟ «الوجبة» هي الأكلة في وقت معين. «كم» تسأل عن العدد.","سالم: آكل ثلاث وجبات: الفطور، والغداء، والعشاء.","الفطور في الصباح. الغداء في الظهر. العشاء في الليل."],"examples":["قَاسِم: أَيْنَ تَذْهَبُ يَا سَالِمُ؟","سَالِم: إِلَى الْمَطْعَمِ.","قَاسِم: كَمْ وَجْبَةً تَأْكُلُ فِي الْيَوْمِ؟","سَالِم: آكُلُ ثَلَاثَ وَجَبَاتٍ: الْفُطُورَ، وَالْغَدَاءَ، وَالْعَشَاءَ."],"questions":[{"question":"ما «المطعم»؟","options":["مكان ننام فيه","مكان ندرس فيه","مكان نأكل فيه","مكان نصلي فيه"],"answer":2,"explanation":"المطعم لأكل الطعام."},{"question":"«كم» تسأل عن:","options":["العدد","الاسم","المكان","الوقت"],"answer":0,"explanation":"كم = كم عددًا."},{"question":"الوجبة في الصباح:","options":["الغداء","القهوة","الفطور","العشاء"],"answer":2,"explanation":"الفطور."},{"question":"كم وجبة يأكل سالم؟","options":["خمسًا","ثلاث","واحدة","اثنتين"],"answer":1,"explanation":"ثلاث وجبات."}]},{"body":["قاسم: هذا كثير جدًا. أنا آكل وجبة واحدة. سالم: هذا قليل جدًا.","«كثير» ضد «قليل». «جدًا» تعني: بدرجة كبيرة.","قاسم: ماذا تأكل في الغداء؟ سالم: آكل الأرز والخبز. وماذا تأكل أنت؟","قاسم: آكل السمك والسلطة والفاكهة. «السمك» حيوان يعيش في الماء. «السلطة» خضار.","الحرف «و» في «الأرز والخبز» تعني: وأيضًا."],"examples":["قَاسِم: هَذَا كَثِيرٌ جِدًّا. أَنَا آكُلُ وَجْبَةً وَاحِدَةً.","سَالِم: هَذَا قَلِيلٌ جِدًّا.","قَاسِم: مَاذَا تَأْكُلُ فِي الْغَدَاءِ؟","سَالِم: آكُلُ الْأَرُزَّ وَالْخُبْزَ.","قَاسِم: آكُلُ السَّمَكَ وَالسَّلَطَةَ وَالْفَاكِهَةَ."],"questions":[{"question":"ضد «كثير»:","options":["قليل","سريع","جميل","كبير"],"answer":0,"explanation":"كثير وقليل ضدان."},{"question":"ماذا يأكل سالم في الغداء؟","options":["السمك والسلطة","اللحم","لا شيء","الأرز والخبز"],"answer":3,"explanation":"سالم: الأرز والخبز."},{"question":"ماذا يأكل قاسم في الغداء؟","options":["الدجاج","السمك والسلطة والفاكهة","الأرز والخبز","التمر"],"answer":1,"explanation":"السمك والسلطة والفاكهة."},{"question":"الحرف «و» في «الأرز والخبز» يربط بين:","options":["سؤالين","شيئين","فعلين فقط","مكانين فقط"],"answer":1,"explanation":"و = وأيضًا."}]}]},{"id":"abyb1-032","title":"ما وزنك؟ سمين ونحيف","summary":"الوزن والكيلو، وكلمتا سمين ونحيف.","segments":[{"body":["سالم يسأل: ما وزنك؟ «الوزن» هو ثقل الجسم، نقيسه بالكيلو.","قاسم: ستون كيلو. وما وزنك أنت؟ سالم: مئة كيلو.","«كيلو» وحدة الوزن. ٦٠ كيلو، ١٠٠ كيلو.","السؤال «ما وزنك؟» فيه الكاف في آخر «وزنك»، وتعني: وزنك أنت.","للمرأة نقول: ما وزنكِ؟ بكسر الكاف."],"examples":["سَالِم: مَا وَزْنُكَ؟","قَاسِم: سِتُّونَ كِيلُو. وَمَا وَزْنُكَ أَنْتَ؟","سَالِم: مِئَةُ كِيلُو."],"questions":[{"question":"نقيس الوزن بـ:","options":["الساعة","اللتر","الكيلو","المتر"],"answer":2,"explanation":"الوزن بالكيلو."},{"question":"اختر السؤال عن الوزن:","options":["متى تأكل؟","ما وزنك؟","أين تسكن؟","كم عمرك؟"],"answer":1,"explanation":"ما وزنك؟"},{"question":"وزن قاسم:","options":["ستون كيلو","مئة كيلو","لا يعرف","عشرة كيلو"],"answer":0,"explanation":"٦٠ كيلو."},{"question":"وزن سالم:","options":["مئة كيلو","ستون كيلو","واحد كيلو","خمسون كيلو"],"answer":0,"explanation":"١٠٠ كيلو."}]},{"body":["قاسم يقول لسالم: أنت سمين جدًا. «سمين» أي: وزنه كثير.","سالم يقول: وأنت نحيف جدًا. «نحيف» أي: وزنه قليل.","سمين ضد نحيف.","نصف الشخص بعد الضمير: أنت سمين. هو نحيف.","لا نقول هذا لكل أحد، فبعض الناس لا يحبون ذلك. هنا هو مثال في الدرس فقط."],"examples":["قَاسِم: أَنْتَ سَمِينٌ جِدًّا.","سَالِم: وَأَنْتَ نَحِيفٌ جِدًّا."],"questions":[{"question":"ضد «سمين»:","options":["كبير","جميل","كثير","نحيف"],"answer":3,"explanation":"سمين ضد نحيف."},{"question":"من وزنه ١٠٠ كيلو في الحوار؟","options":["سالم","قاسم","طارق","فيصل"],"answer":0,"explanation":"سالم."},{"question":"«نحيف» أي:","options":["جائع","طويل","وزنه قليل","وزنه كثير"],"answer":2,"explanation":"نحيف = thin."},{"question":"اكمل: أنت ... جدًا (وزنك قليل)","options":["سمين","نحيف","كبير","كثير"],"answer":1,"explanation":"نحيف."}]}]},{"id":"abyb1-033","title":"الطعام: الأرز والخبز والسمك والفاكهة","summary":"مفردات الطعام: الأرز، الخبز، السمك، الفاكهة، الفطور، الغداء، العشاء.","segments":[{"body":["نتعلم أسماء الطعام: أرز، خبز، سمك، فاكهة، لحم، دجاج، سلطة.","«اللحم» من البقر أو الغنم. «الدجاج» طائر نأكله.","ونتعلم: يأكل. هو فعل. يأكل الرجل الخبز.","«وجبة» أكلة في وقت: الفطور والغداء والعشاء. وجمعها: وجبات.","الأكل في المطعم أو في البيت على المائدة."],"examples":["أَرُزّ، خُبْز، سَمَك، فَاكِهَة.","لَحْم، دَجَاج، سَلَطَة.","وَجْبَة، وَجَبَات."],"questions":[{"question":"أي كلمة طعام؟","options":["كتاب","حافلة","مسجد","دجاج"],"answer":3,"explanation":"الدجاج نأكله."},{"question":"جمع «وجبة»:","options":["وجبين","وجبون","وجبات","أوجاب"],"answer":2,"explanation":"وجبات."},{"question":"الأكل يكون غالبًا على:","options":["المائدة","السرير","الحافلة","الكتاب"],"answer":0,"explanation":"على المائدة."},{"question":"«يأكل» فعل بمعنى:","options":["goes","sleeps","drinks","eats"],"answer":3,"explanation":"أكل = eat."}]},{"body":["نتعلم الوجبات بالترتيب: فطور، غداء، عشاء. ومعها الفاكهة بعد الأكل.","أمثلة: أنا أفطر الخبز والحليب. وأنت؟ آكل الأرز والسمك في الغداء.","نسأل: ماذا تأكل في الفطور؟ ماذا تأكل في الغداء؟ ماذا تأكل في العشاء؟","الكلمة بعد «في» هي اسم الوجبة: في الفطور، في الغداء، في العشاء.","«في» تدل على الوقت أو المكان."],"examples":["مَاذَا تَأْكُلُ فِي الْفُطُورِ؟","آكُلُ الْخُبْزَ.","مَاذَا تَأْكُلُ فِي الْغَدَاءِ؟","آكُلُ الْأَرُزَّ وَالسَّمَكَ."],"questions":[{"question":"اكمل: ماذا تأكل ... الغداء؟","options":["ما","في","من","هل"],"answer":1,"explanation":"في الغداء."},{"question":"ما الجواب المناسب: ماذا تأكل في الغداء؟","options":["أذهب بالحافلة","أصلي","آكل الأرز","أنام"],"answer":2,"explanation":"نجيب عن الطعام."},{"question":"الفاكهة تأتي غالبًا:","options":["في الحافلة","قبل الفجر","في المسجد","بعد الأكل"],"answer":3,"explanation":"بعد الأكل."},{"question":"اكمل: آكل ... في الفطور","options":["الحافلة","الخبز","الكتاب","المسجد"],"answer":1,"explanation":"الخبز."}]}]},{"id":"abyb1-034","title":"ماذا تطلبين من الطعام؟ بعض السمك من فضلك","summary":"الحوار الثاني: الضيافة في الطائرة، وطلب الطعام والشراب بأدب.","segments":[{"body":["الحوار الثاني بين المضيفة والمسافرة. «المضيفة» تخدم المسافرين في الطائرة.","المضيفة: ماذا تطلبين من الطعام؟ «تطلبين» للمرأة. «تطلب» أي: تقول ما تريد.","المسافرة: بعض السمك والأرز من فضلك. «بعض» أي: جزء قليل.","«من فضلك» عبارة مهذبة نقولها عندما نطلب شيئًا.","المضيفة: وماذا تطلبين من الشراب؟ المسافرة: ماء من فضلك."],"examples":["الْمُضِيفَة: مَاذَا تَطْلُبِينَ مِنَ الطَّعَامِ؟","الْمُسَافِرَة: بَعْضَ السَّمَكِ وَالْأَرُزِّ مِنْ فَضْلِكِ.","الْمُضِيفَة: وَمَاذَا تَطْلُبِينَ مِنَ الشَّرَابِ؟","الْمُسَافِرَة: مَاءً مِنْ فَضْلِكِ."],"questions":[{"question":"من «المضيفة»؟","options":["من تدرس","من تطبخ في البيت","من تقود الطائرة","من تخدم المسافرين"],"answer":3,"explanation":"تخدم في الطائرة."},{"question":"«من فضلك» تقال عند:","options":["الوداع","النوم","الطلب","الحزن"],"answer":2,"explanation":"للطلب بأدب."},{"question":"«بعض» تعني:","options":["لا شيء","جزء قليل","كل شيء","دائمًا"],"answer":1,"explanation":"بعض = some."},{"question":"ماذا طلبت المسافرة من الشراب؟","options":["حليب","قهوة","ماء","شاي"],"answer":2,"explanation":"ماء."}]},{"body":["المضيفة: وماذا تفضلين من الفاكهة؟ «تفضلين» أي: تحبين أكثر.","المسافرة: التمر أو العنب. «التمر» ثمر النخل. «العنب» فاكهة صغيرة مستديرة.","المضيفة: هل تشربين الشاي؟ المسافرة: لا، أفضل القهوة.","المضيفة: القهوة بالحليب؟ المسافرة: نعم، القهوة بالحليب.","المضيفة: هل تريدين شيئًا آخر؟ المسافرة: لا، وشكرًا. المضيفة: عفوًا."],"examples":["الْمُضِيفَة: وَمَاذَا تُفَضِّلِينَ مِنَ الْفَاكِهَةِ؟","الْمُسَافِرَة: التَّمْرَ أَوِ الْعِنَبَ.","الْمُضِيفَة: هَلْ تَشْرَبِينَ الشَّايَ؟","الْمُسَافِرَة: لَا، أُفَضِّلُ الْقَهْوَةَ.","الْمُضِيفَة: هَلْ تُرِيدِينَ شَيْئًا آخَرَ؟","الْمُسَافِرَة: لَا، وَشُكْرًا.","الْمُضِيفَة: عَفْوًا."],"questions":[{"question":"«تفضلين» أي:","options":["تكتبين","تحبين أكثر","تذهبين","تنامين"],"answer":1,"explanation":"فضّل = prefer."},{"question":"ماذا فضلت المسافرة: الشاي أم القهوة؟","options":["الشاي","القهوة","الماء","الحليب"],"answer":1,"explanation":"أفضل القهوة."},{"question":"ما التمر؟","options":["شراب","نوع من السمك","ثمر النخل","خضار"],"answer":2,"explanation":"التمر من النخل."},{"question":"نرد على «شكرًا» بـ:","options":["نعم","لا","عفوًا","مرحبًا"],"answer":2,"explanation":"عفوًا."}]}]},{"id":"abyb1-035","title":"أنا جوعان جدًا: الحوار الثالث","summary":"الزوج والزوجة والغداء والضيوف.","segments":[{"body":["الحوار الثالث بين زوج وزوجة. الزوج يدخل البيت ويقول: السلام عليكم.","الزوجة: وعليكم السلام. الزوج: أنا جوعان جدًا. «جوعان» أي: يريد الأكل.","الزوجة: الغداء على المائدة. «المائدة» طاولة الأكل.","الزوج: ما هذا؟ سمك ولحم ودجاج وأرز وسلطة وفاكهة! هذا كثير جدًا.","الزوجة: لا تأكل، لا تأكل. اجلس."],"examples":["الزَّوْج: السَّلَامُ عَلَيْكُمْ.","الزَّوْجَة: وَعَلَيْكُمُ السَّلَامُ.","الزَّوْج: أَنَا جَوْعَانُ جِدًّا.","الزَّوْجَة: الْغَدَاءُ عَلَى الْمَائِدَةِ.","الزَّوْج: مَا هَذَا؟ هَذَا كَثِيرٌ جِدًّا.","الزَّوْجَة: لَا تَأْكُلْ. اجْلِسْ."],"questions":[{"question":"«جوعان» أي:","options":["تعبان","حزين","يريد النوم","يريد الأكل"],"answer":3,"explanation":"جوعان = hungry."},{"question":"أين الغداء؟","options":["على المائدة","في الحافلة","في المدرسة","في المسجد"],"answer":0,"explanation":"على المائدة."},{"question":"«المائدة» هي:","options":["كتاب","حافلة","طاولة الأكل","سرير"],"answer":2,"explanation":"المائدة: الطاولة."},{"question":"ماذا يقول الزوج في أول الحوار؟","options":["عفوًا","السلام عليكم","شكرًا","مع السلامة"],"answer":1,"explanation":"السلام عليكم."}]},{"body":["الزوج: لماذا؟ أنا جوعان. الزوجة: لدينا ضيوف. «لدينا» أي: عندنا. «الضيوف» الناس الذين يزورون البيت.","الزوج: لدينا ضيوف! من؟ الزوجة: والدي ووالدتي وأخي.","الزوج: أين الضيوف؟ الزوجة: في غرفة الجلوس.","«لماذا» تسأل عن السبب. و«من» تسأل عن الشخص.","«يجلس» أي: يضع جسمه على الكرسي. «اجلس» أمر: افعل الجلوس."],"examples":["الزَّوْج: لِمَاذَا؟ أَنَا جَوْعَانُ.","الزَّوْجَة: لَدَيْنَا ضُيُوفٌ.","الزَّوْج: لَدَيْنَا ضُيُوفٌ! مَنْ؟","الزَّوْجَة: وَالِدِي وَوَالِدَتِي وَأَخِي.","الزَّوْج: أَيْنَ الضُّيُوفُ؟","الزَّوْجَة: فِي غُرْفَةِ الْجُلُوسِ."],"questions":[{"question":"«لماذا» تسأل عن:","options":["العدد","المكان","السبب","الوقت"],"answer":2,"explanation":"لماذا = why."},{"question":"«من» تسأل عن:","options":["السبب","العدد","الشخص","الوقت"],"answer":2,"explanation":"من = who."},{"question":"من الضيوف؟","options":["والدها ووالدتها وأخوها","أصدقاء الزوج","لا أحد","الجيران"],"answer":0,"explanation":"والدي ووالدتي وأخي."},{"question":"أين الضيوف؟","options":["في غرفة الجلوس","في الحافلة","في المسجد","في المطبخ"],"answer":0,"explanation":"في غرفة الجلوس."}]}]},{"id":"abyb1-036","title":"الشراب: ماء وقهوة وشاي وحليب","summary":"مفردات الشراب، وفعل يشرب، ويطلب، ويجلس.","segments":[{"body":["نتعلم أسماء الشراب: ماء، قهوة، شاي، حليب.","«الشراب» ما نشربه. وفعله: يشرب. هو يشرب الماء.","مع أنا: أشرب. مع أنت: تشرب. مع أنتِ: تشربين.","نسأل: هل تشرب الشاي؟ ونجيب: نعم، أشرب الشاي. أو: لا، أفضل القهوة.","«هل» تبدأ سؤالًا جوابه نعم أو لا."],"examples":["مَاء، قَهْوَة، شَاي، حَلِيب.","أَنَا أَشْرَبُ. أَنْتَ تَشْرَبُ. أَنْتِ تَشْرَبِينَ.","هَلْ تَشْرَبُ الشَّايَ؟"],"questions":[{"question":"أي كلمة شراب؟","options":["خبز","سمك","أرز","حليب"],"answer":3,"explanation":"الحليب نشربه."},{"question":"«هل» تبدأ سؤالًا جوابه:","options":["نعم أو لا","مكان","اسم","وقت"],"answer":0,"explanation":"سؤال نعم/لا."},{"question":"للمرأة نقول:","options":["تشرب","تشربين","يشرب","أشرب"],"answer":1,"explanation":"تشربين."},{"question":"اكمل: أنا ... القهوة","options":["تشرب","تشربين","أشرب","يشرب"],"answer":2,"explanation":"أشرب."}]},{"body":["أفعال الدرس: يأكل، يشرب، يطلب، يجلس.","يطلب الطعام من المطعم. يجلس الضيف في غرفة الجلوس.","نتدرب على الأضداد: كثير وقليل. سمين ونحيف. ينام ويستيقظ. نعم ولا.","الأضداد تساعد على حفظ الكلمات: كلمة وضدها معًا.","اختر كلمة واكتب ضدها."],"examples":["يَأْكُلُ، يَشْرَبُ، يَطْلُبُ، يَجْلِسُ.","كَثِير ≠ قَلِيل.","سَمِين ≠ نَحِيف.","يَنَامُ ≠ يَسْتَيْقِظُ."],"questions":[{"question":"ضد «نعم»:","options":["لا","قليل","سمين","كثير"],"answer":0,"explanation":"نعم ولا."},{"question":"ضد «قليل»:","options":["جوعان","سمين","كثير","نحيف"],"answer":2,"explanation":"كثير."},{"question":"من يطلب الطعام من المطعم؟","options":["الحافلة","الزبون","القلم","الصحيفة"],"answer":1,"explanation":"الزبون."},{"question":"ضد «ينام»:","options":["يستيقظ","يشرب","يأكل","يجلس"],"answer":0,"explanation":"يستيقظ."}]}]},{"id":"abyb1-037","title":"ماذا تأكل في الغداء؟ التراكيب والنفي","summary":"نسأل بماذا وأين، وننفي الفعل بلا.","segments":[{"body":["السؤال عن المكان: أين الغداء؟ والجواب: الغداء على المائدة.","نبدل الكلمة: أين الفطور؟ أين العشاء؟ أين الفاكهة؟ أين القهوة؟","السؤال عن الفعل: ماذا تأكل في الغداء؟ والجواب: آكل اللحم.","نبدل الطعام: آكل السمك. آكل الدجاج. آكل السلطة. آكل الأرز. آكل الفاكهة. آكل الخبز.","«ماذا» تسأل عن الشيء، و«أين» عن المكان."],"examples":["أَيْنَ الْغَدَاءُ؟ الْغَدَاءُ عَلَى الْمَائِدَةِ.","مَاذَا تَأْكُلُ فِي الْغَدَاءِ؟ آكُلُ اللَّحْمَ."],"questions":[{"question":"اختر السؤال عن الشيء:","options":["ماذا تأكل؟","أين تأكل؟","متى تأكل؟","كم تأكل؟"],"answer":0,"explanation":"ماذا = what."},{"question":"أين الغداء؟ الجواب:","options":["الساعة الواحدة","نعم","آكل اللحم","على المائدة"],"answer":3,"explanation":"مكان."},{"question":"ماذا تأكل في الغداء؟ الجواب:","options":["لا","في المسجد","غدًا","آكل السمك"],"answer":3,"explanation":"نوع الطعام."},{"question":"«أين» تسأل عن:","options":["الشخص","المكان","الوقت","الشيء"],"answer":1,"explanation":"أين = where."}]},{"body":["النفي: نضع «لا» قبل الفعل. مثال: يأكل الطعام. لا يأكل الطعام.","مع أنت: تأكل الطعام. لا تأكل الطعام. مع أنا: لا آكل.","لاحظ أن «لا» تغير المعنى فقط. شكل الفعل لا يتغير.","ونطلب الطعام بأدب: ماذا تطلب من الطعام؟ بعض السمك من فضلك.","للمرأة: ماذا تطلبين؟ بعض السمك من فضلك."],"examples":["يَأْكُلُ الطَّعَامَ. لَا يَأْكُلُ الطَّعَامَ.","تَشْرَبُ الْحَلِيبَ. لَا تَشْرَبُ الْحَلِيبَ.","مَاذَا تَطْلُبُ مِنَ الطَّعَامِ؟ بَعْضَ السَّمَكِ مِنْ فَضْلِكَ."],"questions":[{"question":"نفي «تشرب»:","options":["لا تشرب","هل تشرب","لا أشرب","لا يشرب"],"answer":0,"explanation":"لا + تشرب."},{"question":"نفي «يغسل الملابس»:","options":["غسل","هل يغسل","لا يغسل الملابس","يغسلون"],"answer":2,"explanation":"لا يغسل."},{"question":"«لا» نضعها:","options":["قبل الحرف الأول من الجملة فقط","قبل الفعل","بعد الاسم","في آخر الجملة"],"answer":1,"explanation":"قبل الفعل."},{"question":"اكمل: بعض السمك ...","options":["كم","من فضلك","لماذا","أين"],"answer":1,"explanation":"من فضلك."}]}]},{"id":"abyb1-038","title":"الأعداد الترتيبية والقاف والكاف","summary":"الأول إلى الخامس، والفرق بين صوت ق وصوت ك.","segments":[{"body":["نكرر الترتيب: الأولى، الثانية، الثالثة، الرابعة، الخامسة. للمؤنث: مثل الخيل الأولى والثانية.","المثال في الكتاب: سباق خيل. الأولى هي الخيل الأولى في السباق.","للمذكر: الأول، الثاني، الثالث، الرابع، الخامس.","نتدرب: الأول ثم الثاني ثم الثالث ثم الرابع ثم الخامس.","نربط العدد بترتيبه: ١ الأول، ٢ الثاني، ٣ الثالث، ٤ الرابع، ٥ الخامس."],"examples":["الْأُولَى، الثَّانِيَةُ، الثَّالِثَةُ، الرَّابِعَةُ، الْخَامِسَةُ."],"questions":[{"question":"٤ بالترتيب:","options":["الخامس","الأول","الرابع","الثالث"],"answer":2,"explanation":"الرابع."},{"question":"٢ بالترتيب:","options":["الثالث","الأول","الثاني","الخامس"],"answer":2,"explanation":"الثاني."},{"question":"الخامس هو رقم:","options":["٥","١","٣","٤"],"answer":0,"explanation":"خمسة."},{"question":"المؤنث من «الثاني»:","options":["الثانية","الثاني","الثنائي","الثانيان"],"answer":0,"explanation":"الثانية."}]},{"body":["الصوت «ق» يخرج من آخر الفم. مثل: قاسم، قليل، قهوة، برتقال.","الصوت «ك» أخف، يخرج أمام «ق». مثل: كتاب، كبير، كلام.","نتدرب على الفرق: قلم وكلم. قل وكل. حق وحك. فلق وفلك.","الفرق مهم لأن المعنى يتغير: «قلب» غير «كلب».","نستمع ونعيد حتى نسمع الفرق. من القرآن: «قل أعوذ برب الفلق»."],"examples":["قَاسِم، قَلِيل، قَهْوَة.","كِتَاب، كَبِير.","قَلَم، كَلَّم.","﴿قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ﴾"],"questions":[{"question":"أي كلمة فيها «ق»؟","options":["كلام","قهوة","كتاب","كبير"],"answer":1,"explanation":"قهوة."},{"question":"أي كلمة فيها «ك»؟","options":["قاسم","قليل","كتاب","قهوة"],"answer":2,"explanation":"كتاب."},{"question":"الفرق بين «ق» و«ك» مهم لأن:","options":["المعنى يتغير","الكلمة تطول","الكلمة تقصر","لا فرق"],"answer":0,"explanation":"المعنى يتغير."},{"question":"الصوت «ق» يخرج من:","options":["الشفتين","آخر الفم","الأسنان فقط","الأنف"],"answer":1,"explanation":"من آخر الفم."}]}]},{"id":"abyb1-039","title":"أين تصلي الصلوات الخمس؟","summary":"الحوار الأول من الوحدة السادسة (الصلاة): مصطفى وقصي.","segments":[{"body":["الوحدة السادسة عن «الصلاة». نراجع أسماء الصلوات: الفجر، الظهر، العصر، المغرب، العشاء.","مصطفى يسأل: أين تصلي الصلوات الخمس؟ قصي: أصلي الظهر والعصر والمغرب والعشاء في مسجد بلال.","مصطفى: وأين تصلي الفجر؟ قصي: أصلي الفجر في البيت.","مصطفى: لماذا تصلي الفجر في البيت؟ «لماذا» تسأل عن السبب.","قصي: لا أسمع الأذان. «الأذان» نداء يدعو الناس إلى الصلاة."],"examples":["مُصْطَفَى: أَيْنَ تُصَلِّي الصَّلَوَاتِ الْخَمْسَ؟","قُصَيّ: أُصَلِّي الظُّهْرَ وَالْعَصْرَ وَالْمَغْرِبَ وَالْعِشَاءَ فِي مَسْجِدِ بِلَالٍ.","مُصْطَفَى: وَأَيْنَ تُصَلِّي الْفَجْرَ؟","قُصَيّ: أُصَلِّي الْفَجْرَ فِي الْبَيْتِ.","مُصْطَفَى: لِمَاذَا تُصَلِّي الْفَجْرَ فِي الْبَيْتِ؟","قُصَيّ: لَا أَسْمَعُ الْأَذَانَ."],"questions":[{"question":"أين يصلي قصي الفجر؟","options":["في المدرسة","في السيارة","في المسجد","في البيت"],"answer":3,"explanation":"في البيت."},{"question":"«لماذا» تسأل عن:","options":["المكان","الوقت","السبب","العدد"],"answer":2,"explanation":"لماذا = why."},{"question":"ما «الأذان»؟","options":["وقت الغداء","طعام","نداء للصلاة","اسم مسجد"],"answer":2,"explanation":"الأذان ينادي للصلاة."},{"question":"لماذا يصلي قصي الفجر في البيت؟","options":["لا وقت له","المسجد بعيد جدًا","لا يسمع الأذان","لا يحب الصلاة"],"answer":2,"explanation":"لا أسمع الأذان."}]},{"body":["مصطفى: هل تستيقظ متأخرًا؟ قصي: نعم، بعد صلاة الفجر.","مصطفى: استيقظ مبكرًا. «استيقظ» أمر: افعل الاستيقاظ. قصي: لا أستطيع، أعمل في الليل.","«أستطيع» أي: عندي القدرة. «لا أستطيع» أي: ليس عندي قدرة.","مصطفى: ضع المنبه بجانبك. «المنبه» ساعة توقظ من النوم. «ضع» أمر من «يضع».","قصي: هذه فكرة طيبة، جزاك الله خيرًا. هذا شكر للمساعدة."],"examples":["مُصْطَفَى: هَلْ تَسْتَيْقِظُ مُتَأَخِّرًا؟","قُصَيّ: نَعَمْ، بَعْدَ صَلَاةِ الْفَجْرِ.","مُصْطَفَى: اسْتَيْقِظْ مُبَكِّرًا.","قُصَيّ: لَا أَسْتَطِيعُ، أَعْمَلُ فِي اللَّيْلِ.","مُصْطَفَى: ضَعِ الْمُنَبِّهَ بِجَانِبِكَ.","قُصَيّ: هَذِهِ فِكْرَةٌ طَيِّبَةٌ، جَزَاكَ اللهُ خَيْرًا."],"questions":[{"question":"ما «المنبه»؟","options":["كتاب","طعام","مسجد","ساعة توقظ من النوم"],"answer":3,"explanation":"المنبه يوقظ."},{"question":"«لا أستطيع» أي:","options":["ليس عندي قدرة","لا أريد","لا أعرف","لا أسمع"],"answer":0,"explanation":"أستطيع = I can."},{"question":"لماذا لا يستطيع قصي الاستيقاظ مبكرًا؟","options":["يدرس","يعمل في الليل","يسافر","يمرض"],"answer":1,"explanation":"أعمل في الليل."},{"question":"«جزاك الله خيرًا» نقولها:","options":["للسؤال","للوداع","للنفي","للشكر"],"answer":3,"explanation":"شكر."}]}]},{"id":"abyb1-040","title":"أنا مسافر إلى مكة","summary":"الحوار الثاني: السفر إلى مكة والمدينة، وصلاة الجمعة.","segments":[{"body":["الحوار الثاني بين عصام وصالح. عصام: أنا مسافر إلى مكة. إلى أين أنت مسافر؟","«مسافر» أي: يذهب إلى بلد بعيد. «إلى أين» تسأل عن جهة السفر.","صالح: أنا مسافر إلى المدينة. لماذا أنت مسافر إلى مكة؟","عصام: للصلاة في المسجد الحرام. «المسجد الحرام» في مكة.","صالح: للصلاة في المسجد النبوي. «المسجد النبوي» في المدينة."],"examples":["عِصَام: أَنَا مُسَافِرٌ إِلَى مَكَّةَ. إِلَى أَيْنَ أَنْتَ مُسَافِرٌ؟","صَالِح: أَنَا مُسَافِرٌ إِلَى الْمَدِينَةِ.","عِصَام: لِلصَّلَاةِ فِي الْمَسْجِدِ الْحَرَامِ.","صَالِح: لِلصَّلَاةِ فِي الْمَسْجِدِ النَّبَوِيِّ."],"questions":[{"question":"أين المسجد الحرام؟","options":["في المدينة","في دمشق","في مكة","في القاهرة"],"answer":2,"explanation":"في مكة."},{"question":"أين المسجد النبوي؟","options":["في المدينة","في تركيا","في مكة","في مصر"],"answer":0,"explanation":"في المدينة."},{"question":"«إلى أين» تسأل عن:","options":["الاسم","السبب","جهة الذهاب","الوقت"],"answer":2,"explanation":"إلى أين = to where."},{"question":"«مسافر» أي:","options":["ينام","يذهب إلى بلد بعيد","يأكل","يقرأ"],"answer":1,"explanation":"traveler."}]},{"body":["صالح يسأل: أين ستصلي الجمعة؟ عصام: في المسجد الحرام إن شاء الله.","«إن شاء الله» نقولها عند الكلام عن المستقبل، أي: إذا أراد الله.","عصام: وأين ستصلي الجمعة أنت؟ صالح: في المسجد النبوي إن شاء الله.","عصام: كيف ستسافر إلى المدينة؟ صالح: أركب الطائرة.","«كيف» تسأل عن الطريقة. «أركب» أي: أصعد على وسيلة المواصلات."],"examples":["صَالِح: أَيْنَ سَتُصَلِّي الْجُمُعَةَ؟","عِصَام: فِي الْمَسْجِدِ الْحَرَامِ، إِنْ شَاءَ اللهُ.","عِصَام: كَيْفَ سَتُسَافِرُ إِلَى الْمَدِينَةِ؟","صَالِح: أَرْكَبُ الطَّائِرَةَ."],"questions":[{"question":"«كيف» تسأل عن:","options":["الوقت","الاسم","العدد","الطريقة"],"answer":3,"explanation":"كيف = how."},{"question":"نقول «إن شاء الله» عن:","options":["الألوان","الحاضر فقط","المستقبل","الماضي"],"answer":2,"explanation":"للمستقبل."},{"question":"كيف سيسافر صالح؟","options":["بالحافلة","بالسيارة","بالطائرة","ماشيًا"],"answer":2,"explanation":"أركب الطائرة."},{"question":"ما نوع «ستصلي»؟","options":["اسم","فعل للمستقبل","حرف","سؤال"],"answer":1,"explanation":"س + مضارع."}]}]},{"id":"abyb1-041","title":"هيا بنا إلى المسجد: الحوار الثالث","summary":"صادق وصابر، القريب والبعيد، والاعتذار.","segments":[{"body":["الحوار الثالث بين صادق وصابر. صادق: هذا أذان العصر.","صابر: هيا بنا إلى المسجد. «هيا بنا» تعني: لنذهب معًا.","صادق: أنا أصلي في البيت. صابر: الصلاة في المسجد أفضل. «أفضل» أي: أحسن.","صادق: المسجد بعيد. صابر: المسجد قريب.","«قريب» ضد «بعيد». القريب قرب منك، والبعيد بعيد عنك."],"examples":["صَادِق: هَذَا أَذَانُ الْعَصْرِ.","صَابِر: هَيَّا بِنَا إِلَى الْمَسْجِدِ.","صَادِق: أَنَا أُصَلِّي فِي الْبَيْتِ.","صَابِر: الصَّلَاةُ فِي الْمَسْجِدِ أَفْضَلُ.","صَادِق: الْمَسْجِدُ بَعِيدٌ.","صَابِر: الْمَسْجِدُ قَرِيبٌ."],"questions":[{"question":"ضد «بعيد»:","options":["قريب","جميل","كثير","كبير"],"answer":0,"explanation":"قريب."},{"question":"«هيا بنا» تعني:","options":["شكرًا","لنذهب معًا","اجلس","مع السلامة"],"answer":1,"explanation":"let's go."},{"question":"ما رأي صابر عن الصلاة؟","options":["لا تصلِّ","في البيت أفضل","في المسجد أفضل","غدًا"],"answer":2,"explanation":"في المسجد أفضل."},{"question":"أي صلاة وقتها في الحوار؟","options":["العصر","العشاء","الفجر","الظهر"],"answer":0,"explanation":"أذان العصر."}]},{"body":["صابر: هل أنت مريض؟ صادق: لا، أنا بخير. «مريض» ضد «بخير».","صابر: أنت كسلان. «كسلان» أي: لا يحب العمل أو الحركة.","صادق: هذا صحيح، آسف. «صحيح» أي: حق. «آسف» اعتذار عن الخطأ.","صابر: أنا ذاهب إلى المسجد. صادق: انتظر، أنا ذاهب معك.","«ينتظر» أي: يبقى حتى يأتي شخص أو شيء."],"examples":["صَابِر: هَلْ أَنْتَ مَرِيضٌ؟","صَادِق: لَا، أَنَا بِخَيْرٍ.","صَابِر: أَنْتَ كَسْلَانُ.","صَادِق: هَذَا صَحِيحٌ، آسِفٌ.","صَابِر: أَنَا ذَاهِبٌ إِلَى الْمَسْجِدِ.","صَادِق: انْتَظِرْ، أَنَا ذَاهِبٌ مَعَكَ."],"questions":[{"question":"«كسلان» أي:","options":["لا يحب الحركة","مريض","جائع","سعيد"],"answer":0,"explanation":"lazy."},{"question":"«آسف» نقولها عند:","options":["السفر","الخطأ","النوم","الأكل"],"answer":1,"explanation":"للاعتذار."},{"question":"ماذا قال صادق في النهاية؟","options":["مع السلامة","لا أذهب","انتظر، أنا ذاهب معك","أنا مريض"],"answer":2,"explanation":"انتظر."},{"question":"«صحيح» تعني:","options":["خطأ","كثير","بعيد","حق"],"answer":3,"explanation":"صحيح = right."}]}]},{"id":"abyb1-042","title":"الصلاة: كلمات الوحدة","summary":"الظهر والعصر والمغرب والعشاء، يسمع ويعمل ويستطيع، مكة والمدينة.","segments":[{"body":["نراجع كلمات الوحدة: الظهر، العصر، المغرب، العشاء، الليل.","وأفعال: يسمع، يعمل، يستطيع، يضع. أسمع الأذان. أعمل في الليل.","«بجانبك» أي: قريب منك. ضع المنبه بجانبك.","وأماكن: مكة، المدينة، المسجد الحرام، المسجد النبوي.","وسائل: يركب الطائرة. «طائرة» تطير في السماء."],"examples":["الظُّهْر، الْعَصْر، الْمَغْرِب، الْعِشَاء.","يَسْمَعُ، يَعْمَلُ، يَسْتَطِيعُ، يَضَعُ.","مَكَّة، الْمَدِينَة، طَائِرَة."],"questions":[{"question":"نسمع الأذان بـ:","options":["الفم","العين","اليد","الأذن"],"answer":3,"explanation":"بالأذن."},{"question":"نركب:","options":["الكتاب","المسجد","القرآن","الطائرة"],"answer":3,"explanation":"نركب الطائرة."},{"question":"أي كلمة اسم مدينة؟","options":["الفجر","المدينة","المنبه","الأذان"],"answer":1,"explanation":"المدينة."},{"question":"«يعمل» أي:","options":["يأكل","يقرأ","ينام","يقوم بعمل"],"answer":3,"explanation":"work."}]},{"body":["كلمات أخرى: ينتظر، صحيح، قريب، بعيد، مريض، كسلان، آسف.","الأضداد: قريب وبعيد. مريض وبخير. صحيح وخطأ. مبكر ومتأخر.","نربط كل كلمة بمثال: أنا مريض. المسجد قريب. هذا صحيح.","نكرر الكلمة مع ضدها: قريب، بعيد. قريب، بعيد.","ثم نضعها في جملة قصيرة من عندنا."],"examples":["قَرِيب ≠ بَعِيد.","مَرِيض ≠ بِخَيْر.","هَذَا صَحِيح."],"questions":[{"question":"ضد «مريض»:","options":["بخير","آسف","كسلان","بعيد"],"answer":0,"explanation":"بخير."},{"question":"ضد «صحيح»:","options":["قريب","جميل","كبير","خطأ"],"answer":3,"explanation":"خطأ."},{"question":"اكمل: المسجد ... من البيت (قليل المسافة)","options":["بعيد","كسلان","قريب","مريض"],"answer":2,"explanation":"قريب."},{"question":"اختر الاعتذار:","options":["مرحبًا","نعم","آسف","شكرًا"],"answer":2,"explanation":"آسف."}]}]},{"id":"abyb1-043","title":"الأعداد الترتيبية من الأول إلى العاشر","summary":"الأول، الثاني ... العاشر.","segments":[{"body":["نكمل الترتيب إلى العاشر: الأول، الثاني، الثالث، الرابع، الخامس.","ثم: السادس، السابع، الثامن، التاسع، العاشر.","٦ السادس. ٧ السابع. ٨ الثامن. ٩ التاسع. ١٠ العاشر.","في الكتاب صورة سباق: أول من وصل هو الأول، وآخر من وصل العاشر.","نتدرب على الربط: الثامن مع ٨، العاشر مع ١٠."],"examples":["الْأَوَّل، الثَّانِي، الثَّالِث، الرَّابِع، الْخَامِس.","السَّادِس، السَّابِع، الثَّامِن، التَّاسِع، الْعَاشِر."],"questions":[{"question":"٨ بالترتيب:","options":["العاشر","الثامن","التاسع","السابع"],"answer":1,"explanation":"٨ = الثامن."},{"question":"١٠ بالترتيب:","options":["الثامن","التاسع","العاشر","الخامس"],"answer":2,"explanation":"العاشر."},{"question":"السادس هو رقم:","options":["٦","٩","٧","٨"],"answer":0,"explanation":"٦."},{"question":"بعد السابع:","options":["العاشر","السادس","التاسع","الثامن"],"answer":3,"explanation":"٧ ثم ٨."}]},{"body":["نقرأ الأعداد ترتيبيًا: ٦، ٧، ٨، ٩، ١٠ ثم نقول: السادس، السابع، الثامن، التاسع، العاشر.","ونستعملها: الدور العاشر. الدرس التاسع. المسجد الثامن.","وللمؤنث نزيد تاء: السادسة، السابعة، الثامنة، التاسعة، العاشرة.","نقول: الساعة العاشرة. الصلاة السادسة؟ لا، الصلوات خمس فقط.","نحفظ العشرة مرتبة."],"examples":["الدَّوْرُ الْعَاشِر.","السَّاعَةُ الثَّامِنَةُ.","السَّادِسَةُ، السَّابِعَةُ، التَّاسِعَةُ."],"questions":[{"question":"مؤنث «السابع»:","options":["السابعة","السابعين","السبعون","السبعة"],"answer":0,"explanation":"السابعة."},{"question":"الساعة ١٠ نقول:","options":["الساعة العشرة","الساعة عشرة فقط","الساعة العاشر","الساعة العاشرة"],"answer":3,"explanation":"الساعة العاشرة."},{"question":"٩ بالترتيب المذكر:","options":["السابع","التاسع","الثامن","العاشر"],"answer":1,"explanation":"التاسع."},{"question":"اكمل: الدور ... (٦)","options":["الثامن","السابع","الخامس","السادس"],"answer":3,"explanation":"السادس."}]}]},{"id":"abyb1-044","title":"إلى أين تذهب؟ ولماذا؟","summary":"التراكيب: إلى أين، لماذا، أنا ذاهب إلى، ضع، أصلي في.","segments":[{"body":["مثال من الكتاب: إلى أين تذهب؟ أذهب إلى المسجد الحرام.","ثم نسأل: لماذا؟ نجيب: لأصلي الجمعة. «لـ» قبل الفعل تعني: من أجل.","أنا ذاهب إلى المسجد. أنا ذاهب إلى المدرسة. أنا ذاهب إلى البيت. أنا ذاهب إلى الطبيب.","«ذاهب» اسم فاعل: من يذهب الآن.","للمرأة: أنا ذاهبة."],"examples":["إِلَى أَيْنَ تَذْهَبُ؟ أَذْهَبُ إِلَى الْمَسْجِدِ الْحَرَامِ.","لِمَاذَا؟ لِأُصَلِّيَ الْجُمُعَةَ.","أَنَا ذَاهِبٌ إِلَى الْمَدْرَسَةِ."],"questions":[{"question":"«إلى أين» جوابها:","options":["عدد","اسم مكان","اسم شخص","وقت"],"answer":1,"explanation":"مكان."},{"question":"«لماذا» جوابها يبدأ غالبًا بـ:","options":["في","هل","ما","ل"],"answer":3,"explanation":"لأصلي..."},{"question":"للمرأة نقول:","options":["أنا ذاهب","أنا ذهب","أنا ذاهبين","أنا ذاهبة"],"answer":3,"explanation":"ذاهبة."},{"question":"اكمل: أنا ذاهب ... الطبيب","options":["عن","إلى","هل","من"],"answer":1,"explanation":"إلى."}]},{"body":["نسأل عن السفر: لماذا أنت مسافر إلى مكة؟ نبدل: هو مسافر إلى مصر. هي مسافرة إلى تركيا. أنت مسافر إلى سوريا.","للرجل: مسافر. وللمرأة: مسافرة.","الأمر: ضع المنبه بجانبك. اقرأ القرآن. انتظر. اكنس الغرفة. اغسل الملابس. شاهد التلفاز. كل التمر.","الأمر هو أن نطلب فعلًا من شخص. يبدأ غالبًا من الفعل بدون حرف المضارعة.","مثال: يقرأ القرآن، فنقول: اقرأ القرآن."],"examples":["هُوَ مُسَافِرٌ إِلَى مِصْرَ. هِيَ مُسَافِرَةٌ إِلَى تُرْكِيَا.","ضَعِ الْمُنَبِّهَ بِجَانِبِكَ.","اقْرَأِ الْقُرْآنَ. انْتَظِرْ. اغْسِلِ الْمَلَابِسَ. كُلِ التَّمْرَ."],"questions":[{"question":"أمر من «يقرأ»:","options":["اقرأ","يقرأ","قرأ","تقرأ"],"answer":0,"explanation":"اقرأ."},{"question":"أمر من «يغسل»:","options":["تغسل","اغسل","غسلت","يغسل"],"answer":1,"explanation":"اغسل."},{"question":"هي ... إلى تركيا","options":["مسافرة","مسافرون","مسافر","سافر"],"answer":0,"explanation":"مسافرة."},{"question":"الأمر هو:","options":["شكر","سؤال","طلب فعل","نفي"],"answer":2,"explanation":"أمر = طلب."}]}]},{"id":"abyb1-045","title":"صوت الصاد والسين","summary":"التمييز بين ص وس.","segments":[{"body":["الصوت «ص» ثقيل، مفخم. والصوت «س» خفيف.","أمثلة بـ«ص»: صالح، عصام، مصطفى، قصي، صابر.","أمثلة بـ«س»: سالم، سمع، سلم، سبح.","الفرق مهم: «صور» غير «سور». «صالح» غير «سالح».","نستمع ونعيد: صبح، سبح. صور، سور. صدا، سدا."],"examples":["صَالِح، عِصَام، مُصْطَفَى، قُصَيّ، صَابِر.","سَالِم، سَمِعَ، سَلَّمَ.","صُوَر، سُوَر."],"questions":[{"question":"أي اسم فيه «ص»؟","options":["قاسم","سالم","طارق","صالح"],"answer":3,"explanation":"صالح."},{"question":"أي اسم فيه «س»؟","options":["سالم","عصام","صابر","صالح"],"answer":0,"explanation":"سالم."},{"question":"الصوت «ص» يكون:","options":["مثل ك","صامتًا","ثقيلًا","خفيفًا"],"answer":2,"explanation":"مفخم."},{"question":"الفرق بين «ص» و«س» مهم لأن:","options":["الكلمة تقصر","لا فرق","المعنى يتغير","الكلمة تطول"],"answer":2,"explanation":"يتغير المعنى."}]},{"body":["نقرأ من القرآن: ﴿وَالْعَصْرِ﴾ فيها صاد، ﴿إِنَّ الْإِنسَانَ لَفِي خُسْرٍ﴾ فيها سين.","وفي الآية: ﴿وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ﴾ أصوات صاد وسين معًا.","نقرأ ببطء ونفرق بين الصاد والسين.","ونستمع إلى المعلم أو إلى تسجيل ثم نعيد.","التكرار هو أفضل طريقة لتعلم الأصوات."],"examples":["﴿وَالْعَصْرِ﴾","﴿إِنَّ الْإِنْسَانَ لَفِي خُسْرٍ﴾","﴿وَتَوَاصَوْا بِالصَّبْرِ﴾"],"questions":[{"question":"في كلمة «العصر» يوجد صوت:","options":["ص","ق","ط","ك"],"answer":0,"explanation":"عصر فيها ص."},{"question":"في كلمة «خسر» يوجد صوت:","options":["س","ق","ك","ص"],"answer":0,"explanation":"خسر."},{"question":"أفضل طريقة لتعلم الأصوات:","options":["الكتابة فقط","التكرار","الصمت","النوم"],"answer":1,"explanation":"التكرار."},{"question":"نقرأ الآية:","options":["بلا تدريب","بلا صوت","بسرعة كبيرة","ببطء"],"answer":3,"explanation":"ببطء."}]}]},{"id":"abyb1-046","title":"الصلاة والسفر: مراجعة الوحدة","summary":"مراجعة الحوارات والكلمات في الوحدة السادسة.","segments":[{"body":["نراجع الحوارات الثلاثة. الأول: قصي يصلي الفجر في البيت لأنه لا يسمع الأذان.","الثاني: عصام مسافر إلى مكة وصالح إلى المدينة، لصلاة الجمعة.","الثالث: صابر يدعو صادقًا إلى المسجد، والمسجد قريب.","في كل حوار سؤال عن مكان أو سبب أو طريقة.","أين؟ مكان. لماذا؟ سبب. كيف؟ طريقة. متى؟ وقت. من؟ شخص. ماذا؟ شيء."],"examples":["أَيْنَ؟ لِمَاذَا؟ كَيْفَ؟ مَتَى؟ مَنْ؟ مَاذَا؟"],"questions":[{"question":"أين؟ تسأل عن:","options":["السبب","المكان","الوقت","الطريقة"],"answer":1,"explanation":"مكان."},{"question":"كيف؟ تسأل عن:","options":["الطريقة","الشخص","المكان","العدد"],"answer":0,"explanation":"طريقة."},{"question":"من؟ تسأل عن:","options":["الوقت","الشخص","المكان","الشيء"],"answer":1,"explanation":"شخص."},{"question":"ماذا؟ تسأل عن:","options":["الوقت","الشيء","الشخص","السبب"],"answer":1,"explanation":"شيء."}]},{"body":["نكمل: عصام ... إلى مكة.","قصي يصلي الفجر في ... لأنه لا يسمع الأذان.","المسجد ... من البيت، يقول صابر.","صالح يركب ... إلى المدينة.","ونقول عند الاعتذار: آسف."],"examples":["عِصَامٌ مُسَافِرٌ إِلَى مَكَّةَ.","قُصَيٌّ يُصَلِّي الْفَجْرَ فِي الْبَيْتِ.","الْمَسْجِدُ قَرِيبٌ.","صَالِحٌ يَرْكَبُ الطَّائِرَةَ."],"questions":[{"question":"عصام مسافر إلى:","options":["مصر","تركيا","مكة","المدينة"],"answer":2,"explanation":"مكة."},{"question":"قصي يصلي الفجر في:","options":["البيت","الحافلة","المسجد","المدرسة"],"answer":0,"explanation":"البيت."},{"question":"صالح يركب:","options":["الحافلة","السيارة","القطار","الطائرة"],"answer":3,"explanation":"الطائرة."},{"question":"المسجد في كلام صابر:","options":["قريب","كبير جدًا","مغلق","بعيد"],"answer":0,"explanation":"قريب."}]}]},{"id":"abyb1-047","title":"الدراسة خمسة أيام في الأسبوع","summary":"الحوار الأول من الوحدة السابعة (الدراسة): غانم وغالب، وأيام الأسبوع.","segments":[{"body":["الوحدة السابعة عن «الدراسة». الدراسة هي التعلم في المدرسة أو الجامعة.","غانم: انظر إلى اللوحة، اقرأ الجدول الدراسي. «الجدول الدراسي» ورقة فيها أيام الدراسة والمواد.","غالب: الدراسة خمسة أيام في الأسبوع. «الأسبوع» سبعة أيام.","غانم: نعم، يوم السبت ويوم الأحد ويوم الاثنين ويوم الثلاثاء ويوم الأربعاء.","غالب: العطلة يوم الخميس ويوم الجمعة."],"examples":["غَانِم: انْظُرْ إِلَى اللَّوْحَةِ، اقْرَأِ الْجَدْوَلَ الدِّرَاسِيَّ.","غَالِب: الدِّرَاسَةُ خَمْسَةُ أَيَّامٍ فِي الْأُسْبُوعِ.","غَانِم: نَعَمْ، يَوْمُ السَّبْتِ وَيَوْمُ الْأَحَدِ وَيَوْمُ الِاثْنَيْنِ وَيَوْمُ الثُّلَاثَاءِ وَيَوْمُ الْأَرْبِعَاءِ.","غَالِب: الْعُطْلَةُ يَوْمُ الْخَمِيسِ وَيَوْمُ الْجُمُعَةِ."],"questions":[{"question":"كم يومًا في الأسبوع؟","options":["ستة","سبعة","خمسة","عشرة"],"answer":1,"explanation":"الأسبوع سبعة أيام."},{"question":"كم يومًا الدراسة؟","options":["خمسة","ثلاثة","يومان","سبعة"],"answer":0,"explanation":"خمسة أيام."},{"question":"أي يوم عطلة في الحوار؟","options":["الأربعاء","الخميس","الأحد","الاثنين"],"answer":1,"explanation":"الخميس والجمعة."},{"question":"ما «الجدول الدراسي»؟","options":["مطعم","ورقة فيها أيام الدراسة والمواد","مسجد","كتاب قصص"],"answer":1,"explanation":"جدول المواد."}]},{"body":["غانم: أكتب المواد الدراسية. «المواد» الأشياء التي ندرسها.","غالب: الثقافة الإسلامية، واللغة العربية، والرياضيات، والعلوم، والحاسوب. «الحاسوب» الكمبيوتر.","غالب: متى تبدأ الاختبارات؟ غانم: في شهر شعبان. «الشهر» ثلاثون يومًا تقريبًا.","غالب: ومتى ينتهي العام الدراسي؟ غانم: في شهر رمضان.","غالب: العطلة ثلاثة أشهر. غانم: الحمد لله، العطلة طويلة. ثم: بدأت الحصة، وجاء المعلم، هيا بنا إلى الصف."],"examples":["غَانِم: أَكْتُبُ الْمَوَادَّ الدِّرَاسِيَّةَ.","غَالِب: الثَّقَافَةُ الْإِسْلَامِيَّةُ، وَاللُّغَةُ الْعَرَبِيَّةُ، وَالرِّيَاضِيَّاتُ، وَالْعُلُومُ، وَالْحَاسُوبُ.","غَالِب: مَتَى تَبْدَأُ الِاخْتِبَارَاتُ؟","غَانِم: فِي شَهْرِ شَعْبَانَ.","غَالِب: وَمَتَى يَنْتَهِي الْعَامُ الدِّرَاسِيُّ؟","غَانِم: فِي شَهْرِ رَمَضَانَ.","غَالِب: الْعُطْلَةُ ثَلَاثَةُ أَشْهُرٍ.","غَانِم: الْحَمْدُ لِلهِ، الْعُطْلَةُ طَوِيلَةٌ."],"questions":[{"question":"ما «الحاسوب»؟","options":["الكتاب","القلم","الكمبيوتر","الباب"],"answer":2,"explanation":"computer."},{"question":"متى تبدأ الاختبارات؟","options":["في الصباح","في رمضان","في شعبان","في الجمعة"],"answer":2,"explanation":"شعبان."},{"question":"متى ينتهي العام الدراسي؟","options":["في شعبان","في الأحد","في العصر","في رمضان"],"answer":3,"explanation":"رمضان."},{"question":"كم تدوم العطلة؟","options":["أسبوعًا","ثلاثة أشهر","شهرًا","يومين"],"answer":1,"explanation":"ثلاثة أشهر."}]}]},{"id":"abyb1-048","title":"أنا طالبة في جامعة دمشق","summary":"الحوار الثاني: ندى وإلهام في الجامعة، والكليات.","segments":[{"body":["الحوار الثاني بين ندى وإلهام. ندى: السلام عليكم. إلهام: وعليكم السلام.","ندى: اسمي ندى، أنا سورية. إلهام: اسمي إلهام، أنا سعودية.","«سورية» من سوريا. «سعودية» من السعودية. للمرأة نزيد ة.","ندى: أنا طالبة في جامعة دمشق. إلهام: أنا طالبة في جامعة أم القرى.","«الطالبة» امرأة تدرس. «الجامعة» مكان الدراسة بعد المدرسة."],"examples":["نَدَى: اسْمِي نَدَى، أَنَا سُورِيَّةٌ.","إِلْهَام: اسْمِي إِلْهَامُ، أَنَا سُعُودِيَّةٌ.","نَدَى: أَنَا طَالِبَةٌ فِي جَامِعَةِ دِمَشْقَ.","إِلْهَام: أَنَا طَالِبَةٌ فِي جَامِعَةِ أُمِّ الْقُرَى."],"questions":[{"question":"ندى من:","options":["تركيا","السعودية","مصر","سوريا"],"answer":3,"explanation":"سورية."},{"question":"إلهام من:","options":["سوريا","اليمن","السعودية","عمان"],"answer":2,"explanation":"سعودية."},{"question":"ما «الجامعة»؟","options":["مطعم","مسجد","سوق","مكان الدراسة بعد المدرسة"],"answer":3,"explanation":"University."},{"question":"أين تدرس ندى؟","options":["مدرسة","مكتبة","جامعة دمشق","جامعة أم القرى"],"answer":2,"explanation":"دمشق."}]},{"body":["ندى: في أي كلية تدرسين؟ «الكلية» قسم في الجامعة. «تدرسين» للمرأة.","إلهام: أدرس في كلية التربية. وفي أي كلية تدرسين أنت؟ ندى: أدرس في كلية الطب.","إلهام: سأكون مدرسة إن شاء الله. «سأكون» أي: في المستقبل أصير.","ندى: وسأكون طبيبة إن شاء الله.","«مدرسة» هنا بمعنى معلمة. وهي مثل «مدرِّسة»."],"examples":["نَدَى: فِي أَيِّ كُلِّيَّةٍ تَدْرُسِينَ؟","إِلْهَام: أَدْرُسُ فِي كُلِّيَّةِ التَّرْبِيَةِ.","إِلْهَام: سَأَكُونُ مُدَرِّسَةً إِنْ شَاءَ اللهُ.","نَدَى: وَسَأَكُونُ طَبِيبَةً إِنْ شَاءَ اللهُ."],"questions":[{"question":"أين تدرس إلهام؟","options":["كلية الطب","كلية اللغة","كلية التربية","كلية العلوم"],"answer":2,"explanation":"التربية."},{"question":"ماذا ستكون ندى؟","options":["مهندسة","طبيبة","طالبة فقط","مدرسة"],"answer":1,"explanation":"طبيبة."},{"question":"ما «الكلية»؟","options":["كتاب","قسم في الجامعة","بيت","مطعم"],"answer":1,"explanation":"college."},{"question":"«سأكون» أي:","options":["كنت","لا أكون","أنا الآن","في المستقبل أصير"],"answer":3,"explanation":"سـ مستقبل."}]}]},{"id":"abyb1-049","title":"أين تذهب يا غسان؟ الحوار الثالث","summary":"اليوم الدراسي، المكتبة، المختبر، الاستراحة.","segments":[{"body":["الحوار الثالث بين قاسم وغسان. قاسم: أين تذهب يا غسان؟ غسان: أذهب إلى المدرسة.","قاسم: الوقت مبكر، الساعة الآن السادسة صباحًا. غسان: المدرسة بعيدة عن البيت.","قاسم: متى يبدأ اليوم الدراسي؟ غسان: يبدأ الساعة السابعة صباحًا.","قاسم: هل تذهب بالحافلة؟ غسان: لا، أذهب بالسيارة.","«الآن» أي: في هذا الوقت. «صباحًا» أي: في الصباح."],"examples":["قَاسِم: أَيْنَ تَذْهَبُ يَا غَسَّانُ؟","غَسَّان: أَذْهَبُ إِلَى الْمَدْرَسَةِ.","قَاسِم: الْوَقْتُ مُبَكِّرٌ. السَّاعَةُ الْآنَ السَّادِسَةُ صَبَاحًا.","غَسَّان: الْمَدْرَسَةُ بَعِيدَةٌ عَنِ الْبَيْتِ.","قَاسِم: مَتَى يَبْدَأُ الْيَوْمُ الدِّرَاسِيُّ؟","غَسَّان: يَبْدَأُ السَّاعَةَ السَّابِعَةَ صَبَاحًا."],"questions":[{"question":"متى يبدأ اليوم الدراسي؟","options":["الساعة الواحدة","الساعة الثانية","الساعة السابعة","الساعة العاشرة"],"answer":2,"explanation":"السابعة."},{"question":"كيف يذهب غسان؟","options":["بالحافلة","بالطائرة","بالسيارة","ماشيًا"],"answer":2,"explanation":"بالسيارة."},{"question":"«صباحًا» أي:","options":["في الليل","في العصر","في الظهر","في الصباح"],"answer":3,"explanation":"morning."},{"question":"المدرسة ... عن البيت","options":["بعيدة","قريبة جدًا","صغيرة","مغلقة"],"answer":0,"explanation":"بعيدة."}]},{"body":["قاسم: متى ينتهي اليوم الدراسي؟ غسان: ينتهي الساعة الواحدة ظهرًا.","قاسم: كم حصة تدرس في اليوم؟ غسان: أدرس ست حصص في اليوم. «الحصة» وقت درس واحد.","قاسم: ماذا تفعل في الاستراحة؟ غسان: أذهب إلى المكتبة أو إلى المختبر.","«المكتبة» مكان الكتب. «المختبر» مكان التجارب العلمية. «الاستراحة» وقت راحة بين الحصص.","جمع «حصة»: حصص."],"examples":["قَاسِم: مَتَى يَنْتَهِي الْيَوْمُ الدِّرَاسِيُّ؟","غَسَّان: يَنْتَهِي السَّاعَةَ الْوَاحِدَةَ ظُهْرًا.","قَاسِم: كَمْ حِصَّةً تَدْرُسُ فِي الْيَوْمِ؟","غَسَّان: أَدْرُسُ سِتَّ حِصَصٍ فِي الْيَوْمِ.","قَاسِم: مَاذَا تَفْعَلُ فِي الِاسْتِرَاحَةِ؟","غَسَّان: أَذْهَبُ إِلَى الْمَكْتَبَةِ أَوْ إِلَى الْمُخْتَبَرِ."],"questions":[{"question":"كم حصة يدرس غسان؟","options":["ست","ثلاث","اثنتين","عشرًا"],"answer":0,"explanation":"ست حصص."},{"question":"ما «المكتبة»؟","options":["مكان النوم","مكان الطعام","مكان الصلاة فقط","مكان الكتب"],"answer":3,"explanation":"library."},{"question":"متى ينتهي اليوم الدراسي؟","options":["الساعة السابعة","عند الفجر","الساعة الواحدة ظهرًا","بعد العشاء"],"answer":2,"explanation":"الواحدة."},{"question":"جمع «حصة»:","options":["حصون","حصي","حصات","حصص"],"answer":3,"explanation":"حصص."}]}]},{"id":"abyb1-050","title":"مفردات الدراسة","summary":"المواد، الصف، اللوحة، الحصة، الاختبار، يبدأ، ينتهي، ينتظر.","segments":[{"body":["كلمات المدرسة: صف، لوحة، حصة، اختبار، جدول دراسي، مواد دراسية.","«الصف» غرفة الدراسة. «اللوحة» سطح نكتب عليه. «الاختبار» امتحان.","المواد: اللغة العربية، العلوم، الرياضيات، الحاسوب، الثقافة الإسلامية.","«الرياضيات» علم الأعداد والحساب. «العلوم» مثل الفيزياء والكيمياء.","نسأل: ماذا تدرس؟ ونجيب: أدرس العلوم."],"examples":["صَفّ، لَوْحَة، حِصَّة، اخْتِبَار.","اللُّغَةُ الْعَرَبِيَّةُ، الْعُلُومُ، الرِّيَاضِيَّاتُ، الْحَاسُوبُ."],"questions":[{"question":"ما «الاختبار»؟","options":["مطعم","شراب","حافلة","امتحان"],"answer":3,"explanation":"exam."},{"question":"الرياضيات علم:","options":["الطعام","الأعداد","الصلاة","السفر"],"answer":1,"explanation":"الحساب."},{"question":"نكتب على:","options":["الأطباق","اللوحة","الحافلة","الفاكهة"],"answer":1,"explanation":"اللوحة."},{"question":"«الصف» هو:","options":["مطعم","سيارة","غرفة الدراسة","ملعب"],"answer":2,"explanation":"classroom."}]},{"body":["أفعال الدراسة: يكتب، يدرس، يبدأ، ينتهي، ينتظر، جاء.","مثال: يبدأ اليوم الدراسي الساعة السابعة. وينتهي الساعة الواحدة.","«جاء المعلم» أي: وصل المعلم. «جاء» ماضٍ. «يجيء» مضارع.","«ينتظر» أي: يبقى حتى يأتي أحد.","نكون جملًا قصيرة بكل كلمة."],"examples":["يَكْتُبُ، يَدْرُسُ، يَبْدَأُ، يَنْتَهِي، يَنْتَظِرُ.","جَاءَ الْمُعَلِّمُ."],"questions":[{"question":"ضد «يبدأ»:","options":["ينتهي","يكتب","يأتي","يدرس"],"answer":0,"explanation":"ينتهي."},{"question":"«جاء المعلم» أي:","options":["نام المعلم","وصل المعلم","ذهب المعلم","كتب المعلم"],"answer":1,"explanation":"وصل."},{"question":"نكتب بـ:","options":["السيارة","القلم","الحافلة","الباب"],"answer":1,"explanation":"بالقلم."},{"question":"اكمل: ... اليوم الدراسي الساعة السابعة","options":["يبدأ","يغسل","يطبخ","ينام"],"answer":0,"explanation":"يبدأ."}]}]},{"id":"abyb1-051","title":"أيام الأسبوع وأشهر السنة","summary":"أيام الأسبوع، وأسماء أشهر: شعبان ورمضان، والجمع.","segments":[{"body":["أيام الأسبوع: السبت، الأحد، الاثنين، الثلاثاء، الأربعاء، الخميس، الجمعة.","نقول: يوم السبت. يوم الأحد. يوم الجمعة.","الجمعة يوم مهم عند المسلمين، فيه صلاة الجمعة.","نسأل: كم يومًا الدراسة؟ ونجيب: خمسة أيام.","جمع «يوم»: أيام. جمع «شهر»: أشهر."],"examples":["السَّبْت، الْأَحَد، الِاثْنَيْن، الثُّلَاثَاء، الْأَرْبِعَاء، الْخَمِيس، الْجُمُعَة.","يَوْم، أَيَّام. شَهْر، أَشْهُر."],"questions":[{"question":"اليوم بعد السبت:","options":["الأحد","الجمعة","الاثنين","الخميس"],"answer":0,"explanation":"الأحد."},{"question":"جمع «يوم»:","options":["يومون","أيام","يومان","أيم"],"answer":1,"explanation":"أيام."},{"question":"جمع «شهر»:","options":["شهرون","أشهر","شهران","شهور فقط"],"answer":1,"explanation":"أشهر."},{"question":"آخر يوم في ترتيب الكتاب:","options":["الخميس","الأحد","الجمعة","السبت"],"answer":2,"explanation":"الجمعة."}]},{"body":["من الأشهر: شعبان ورمضان. رمضان شهر الصيام عند المسلمين.","قبل رمضان شهر شعبان. وفي الكتاب: الاختبارات في شعبان، وانتهاء العام في رمضان.","كم شهرًا العطلة؟ ثلاثة أشهر.","العدد مع الجمع: ثلاثة أشهر، خمسة أيام. نستعمل جمع القلة بعد العدد من ٣ إلى ١٠.","مثال: ثلاثة أشهر. خمسة أيام. ست حصص."],"examples":["فِي شَهْرِ شَعْبَانَ. فِي شَهْرِ رَمَضَانَ.","ثَلَاثَةُ أَشْهُرٍ. خَمْسَةُ أَيَّامٍ. سِتُّ حِصَصٍ."],"questions":[{"question":"الشهر الذي فيه صيام المسلمين:","options":["الجمعة","رمضان","الأحد","شعبان"],"answer":1,"explanation":"رمضان."},{"question":"بعد العدد ثلاثة نستعمل:","options":["المفرد","المثنى فقط","حرفًا","الجمع"],"answer":3,"explanation":"ثلاثة أيام."},{"question":"اكمل: خمسة ...","options":["يومين","أيام","يوم","يومان"],"answer":1,"explanation":"خمسة أيام."},{"question":"اكمل: ثلاثة ...","options":["شهرين","أشهر","شهران","شهر"],"answer":1,"explanation":"ثلاثة أشهر."}]}]},{"id":"abyb1-052","title":"الأعداد الترتيبية للمؤنث","summary":"الأولى إلى العاشرة، والربط بين العدد والترتيب.","segments":[{"body":["نعرف الترتيب للمذكر. وللمؤنث: الأولى، الثانية، الثالثة، الرابعة، الخامسة.","ثم: السادسة، السابعة، الثامنة، التاسعة، العاشرة.","نستعملها مع المؤنث: الحصة الأولى، السيارة الثانية، الساعة العاشرة.","لاحظ: الحصة مؤنث، فنقول: الحصة الأولى، لا الحصة الأول.","والمذكر: اليوم الأول، الصف الثاني."],"examples":["الْأُولَى، الثَّانِيَةُ، الثَّالِثَةُ، الرَّابِعَةُ، الْخَامِسَةُ.","السَّادِسَةُ، السَّابِعَةُ، الثَّامِنَةُ، التَّاسِعَةُ، الْعَاشِرَةُ."],"questions":[{"question":"الحصة ... (١)","options":["الأول","الأولى","الأولة","الواحد"],"answer":1,"explanation":"الحصة مؤنث."},{"question":"اليوم ... (١)","options":["الأول","الأولة","الأولى","الواحدة"],"answer":0,"explanation":"اليوم مذكر."},{"question":"الساعة ... (٨)","options":["الثماني","الثامنة","الثامن","الثمانية"],"answer":1,"explanation":"الثامنة."},{"question":"الحصة ... (١٠)","options":["العشر","العاشرة","العشرة","العاشر"],"answer":1,"explanation":"العاشرة."}]},{"body":["نربط الترتيب بالأعداد: السادسة ٦، السابعة ٧، الثامنة ٨، التاسعة ٩، العاشرة ١٠.","نقرأ الأعداد ترتيبًا: ٩، ٦، ٧، ٨، ١٠ ثم نرتبها.","الترتيب الصحيح: السادس ثم السابع ثم الثامن ثم التاسع ثم العاشر.","نسأل: ما الحصة الأولى اليوم؟ الحصة الأولى اللغة العربية.","نستعمل الترتيب في الجدول والمواعيد."],"examples":["السَّادِسَةُ، السَّابِعَةُ، الثَّامِنَةُ، التَّاسِعَةُ، الْعَاشِرَةُ.","الْحِصَّةُ الْأُولَى: اللُّغَةُ الْعَرَبِيَّةُ."],"questions":[{"question":"بعد السابعة:","options":["العاشرة","الثامنة","التاسعة","السادسة"],"answer":1,"explanation":"٧ ثم ٨."},{"question":"٩ بالترتيب المؤنث:","options":["التاسع","التاسعة","الثامنة","العاشرة"],"answer":1,"explanation":"التاسعة."},{"question":"قبل العاشرة:","options":["السادسة","الثامنة","الحادية","التاسعة"],"answer":3,"explanation":"٩ قبل ١٠."},{"question":"نستعمل الترتيب في:","options":["الجدول والمواعيد","الوزن فقط","الأكل فقط","اللون فقط"],"answer":0,"explanation":"للترتيب."}]}]},{"id":"abyb1-053","title":"التراكيب: بعيد عن، المذكر والمؤنث، سأكون","summary":"المدرسة بعيدة عن البيت، مدرس ومدرسة، سأكون إن شاء الله.","segments":[{"body":["مثال من الكتاب: المدرسة بعيدة عن البيت. نبدل: المسجد بعيد عن الجامعة. الصف بعيد عن المختبر. الكلية بعيدة عن الشقة. المكتبة بعيدة عن المختبر. الغرفة بعيدة عن الحمام.","نضع «عن» بعد «بعيد».","المؤنث: بعيدة. المذكر: بعيد.","الاسم المؤنث يعطي صفة مؤنثة: المدرسة بعيدة. المسجد بعيد.","نتدرب بعدة أمثلة لنثبت."],"examples":["الْمَدْرَسَةُ بَعِيدَةٌ عَنِ الْبَيْتِ.","الْمَسْجِدُ بَعِيدٌ عَنِ الْجَامِعَةِ.","الْغُرْفَةُ بَعِيدَةٌ عَنِ الْحَمَّامِ."],"questions":[{"question":"اكمل: المدرسة ... عن البيت","options":["قريب","بعيدة","بعيد","بعيدون"],"answer":1,"explanation":"المدرسة مؤنث."},{"question":"اكمل: المسجد ... عن الجامعة","options":["بعيدين","بعيد","بعيدة","بعيدات"],"answer":1,"explanation":"المسجد مذكر."},{"question":"بعد «بعيد» نضع:","options":["ما","إلى","هل","عن"],"answer":3,"explanation":"بعيد عن."},{"question":"أي جملة صحيحة؟","options":["الكلية بعيدة عن الشقة","الكلية بعيدة إلى الشقة","الكلية بعيد عن الشقة","الكلية بعيد من الشقة"],"answer":0,"explanation":"بعيدة عن."}]},{"body":["نحول المذكر إلى مؤنث: مدرس ← مدرسة. معلم ← معلمة. مهندس ← مهندسة. طبيب ← طبيبة. طالب ← طالبة.","نزيد التاء المربوطة ة في الآخر.","نقول: سأكون مدرسًا إن شاء الله (رجل). وسأكون مدرسة إن شاء الله (امرأة).","«سأكون» أي: سأصير في المستقبل.","الكلمة بعد «سأكون» تتغير مع الشخص: مدرسًا أو مدرسة."],"examples":["مُدَرِّس ← مُدَرِّسَة.","مُعَلِّم ← مُعَلِّمَة.","طَبِيب ← طَبِيبَة.","طَالِب ← طَالِبَة.","سَأَكُونُ مُدَرِّسًا، إِنْ شَاءَ اللهُ."],"questions":[{"question":"مؤنث «مهندس»:","options":["مهندس","مهندسة","مهندسون","مهندسين"],"answer":1,"explanation":"مهندسة."},{"question":"مؤنث «طالب»:","options":["طلبة","طالب","طلاب","طالبة"],"answer":3,"explanation":"طالبة."},{"question":"المرأة تقول:","options":["سأكون طبيبون","سأكون طبيبًا","سأكون طبيبة","سأكون الطب"],"answer":2,"explanation":"طبيبة."},{"question":"«سأكون» أي:","options":["في المستقبل أصير","الآن","لا أكون","كنت"],"answer":0,"explanation":"مستقبل."}]}]},{"id":"abyb1-054","title":"الدراسة: مراجعة الوحدة","summary":"مراجعة الحوارات والمفردات والتراكيب في الوحدة السابعة.","segments":[{"body":["الحوار الأول: غانم وغالب يتكلمان عن الجدول والأيام والعطلة.","الحوار الثاني: ندى وإلهام طالبتان في الجامعة.","الحوار الثالث: قاسم وغسان عن بدء اليوم الدراسي وانتهائه والاستراحة.","من الأسئلة المهمة: كم؟ متى؟ أين؟ ماذا؟","نكرر: كم يومًا؟ ثلاثة أيام. كم حصة؟ ست حصص. متى تبدأ؟ الساعة السابعة."],"examples":["كَمْ يَوْمًا؟ ثَلَاثَةُ أَيَّامٍ.","كَمْ حِصَّةً؟ سِتُّ حِصَصٍ.","مَتَى تَبْدَأُ؟ السَّاعَةَ السَّابِعَةَ."],"questions":[{"question":"كم تسأل عن:","options":["المكان","الوقت","الشخص","العدد"],"answer":3,"explanation":"كم = العدد."},{"question":"متى تسأل عن:","options":["الوقت","العدد","المكان","الشخص"],"answer":0,"explanation":"وقت."},{"question":"غالب وغانم يتكلمان عن:","options":["الطعام","الصلاة فقط","السفر","الجدول والعطلة"],"answer":3,"explanation":"عن الدراسة."},{"question":"ندى وإلهام:","options":["طالبتان","طبيبتان","مهندستان","معلمتان"],"answer":0,"explanation":"طالبتان."}]},{"body":["نراجع أضداد الدراسة: يبدأ وينتهي. قريب وبعيد. مبكر ومتأخر. طويل وقصير.","ونراجع: العطلة طويلة، والدراسة خمسة أيام.","ونتذكر: الاختبارات في شعبان، والعام ينتهي في رمضان.","في المستقبل نقول: سأكون مدرسًا، سأكون طبيبة.","اكتب أنت: ماذا ستكون إن شاء الله؟"],"examples":["يَبْدَأُ ≠ يَنْتَهِي.","سَأَكُونُ طَبِيبًا، إِنْ شَاءَ اللهُ."],"questions":[{"question":"ضد «يبدأ»:","options":["يأكل","ينتهي","يكتب","يذهب"],"answer":1,"explanation":"ينتهي."},{"question":"ضد «طويل»:","options":["بعيد","كثير","قصير","كبير"],"answer":2,"explanation":"قصير."},{"question":"متى تبدأ الاختبارات في الحوار؟","options":["في شعبان","في الأحد","في الجمعة","في رمضان"],"answer":0,"explanation":"شعبان."},{"question":"اكمل: ... طبيبًا إن شاء الله","options":["أكون الآن","لا أكون","سأكون","كنت"],"answer":2,"explanation":"سأكون."}]}]},{"id":"abyb1-055","title":"أعمل طبيبًا: ماذا تعمل أنت؟","summary":"الحوار الأول من الوحدة الثامنة (العمل): عثمان وعلي.","segments":[{"body":["الوحدة الثامنة عن «العمل». العمل هو ما نفعله لنكسب المال.","عثمان: أعمل طبيبًا. ماذا تعمل أنت؟ «الطبيب» يعالج المرضى.","علي: أعمل مهندسًا. «المهندس» يصمم المباني والآلات.","عثمان: أين تعمل؟ علي: أعمل في شركة. «الشركة» مؤسسة تجارية.","وأين تعمل أنت؟ عثمان: أعمل في المستشفى. «المستشفى» مكان فيه أطباء ومرضى."],"examples":["عُثْمَان: أَعْمَلُ طَبِيبًا. مَاذَا تَعْمَلُ أَنْتَ؟","عَلِيّ: أَعْمَلُ مُهَنْدِسًا.","عُثْمَان: أَيْنَ تَعْمَلُ؟","عَلِيّ: أَعْمَلُ فِي شَرِكَةٍ. وَأَيْنَ تَعْمَلُ أَنْتَ؟","عُثْمَان: أَعْمَلُ فِي الْمُسْتَشْفَى."],"questions":[{"question":"ماذا يعمل عثمان؟","options":["طبيب","معلم","طيار","مهندس"],"answer":0,"explanation":"طبيبًا."},{"question":"أين يعمل علي؟","options":["في شركة","في مستشفى","في مطعم","في مدرسة"],"answer":0,"explanation":"في شركة."},{"question":"أين يعمل عثمان؟","options":["في الشركة","في الجامعة","في البيت","في المستشفى"],"answer":3,"explanation":"المستشفى."},{"question":"ما «المستشفى»؟","options":["مطعم","مكان فيه أطباء ومرضى","سوق","مدرسة"],"answer":1,"explanation":"hospital."}]},{"body":["علي: كم ساعة تعمل في اليوم؟ عثمان: أعمل ثماني ساعات في اليوم.","وكم ساعة تعمل أنت؟ علي: أعمل سبع ساعات.","«كم ساعة» تسأل عن العدد. بعد «كم» نضع اسمًا منصوبًا: كم ساعةً.","عثمان: هل تحب عملك؟ علي: نعم، أحب عملي.","عثمان: وأنا أحب عملي أيضًا. «أحب» أي: أريد وأرتاح لـ."],"examples":["عَلِيّ: كَمْ سَاعَةً تَعْمَلُ فِي الْيَوْمِ؟","عُثْمَان: أَعْمَلُ ثَمَانِيَ سَاعَاتٍ فِي الْيَوْمِ.","عُثْمَان: هَلْ تُحِبُّ عَمَلَكَ؟","عَلِيّ: نَعَمْ، أُحِبُّ عَمَلِي.","عُثْمَان: وَأَنَا أُحِبُّ عَمَلِي أَيْضًا."],"questions":[{"question":"كم ساعة يعمل عثمان؟","options":["سبع","ثماني","عشر","ست"],"answer":1,"explanation":"ثماني ساعات."},{"question":"كم ساعة يعمل علي؟","options":["ست","خمس","سبع","ثماني"],"answer":2,"explanation":"سبع."},{"question":"«أحب» أي:","options":["أنام","أرتاح لـ وأريد","أذهب","أكره"],"answer":1,"explanation":"love/like."},{"question":"هل يحب علي عمله؟","options":["أحيانًا لا","لا يعرف","نعم","لا"],"answer":2,"explanation":"نعم."}]}]},{"id":"abyb1-056","title":"سأعمل طبيبًا إن شاء الله","summary":"الحوار الثاني: ماذا ستعمل بعد الدراسة؟ المهن والكليات.","segments":[{"body":["الحوار الثاني بين طلاب. الأول يسأل: ماذا سنعمل بعد الدراسة؟","الثاني: أنا أدرس الطب في كلية الطب، سأعمل طبيبًا إن شاء الله.","الثالث: أنا أدرس الصيدلة في كلية الصيدلة، سأعمل صيدليًا.","الرابع: أنا أدرس التمريض في كلية التمريض، سأعمل ممرضًا.","«الصيدلي» يبيع الدواء. «الممرض» يساعد الطبيب في رعاية المريض."],"examples":["الطَّالِبُ الْأَوَّلُ: مَاذَا سَنَعْمَلُ بَعْدَ الدِّرَاسَةِ؟","الطَّالِبُ الثَّانِي: أَنَا أَدْرُسُ الطِّبَّ فِي كُلِّيَّةِ الطِّبِّ، سَأَعْمَلُ طَبِيبًا إِنْ شَاءَ اللهُ.","الطَّالِبُ الثَّالِثُ: أَنَا أَدْرُسُ الصَّيْدَلَةَ، سَأَعْمَلُ صَيْدَلِيًّا.","الطَّالِبُ الرَّابِعُ: أَنَا أَدْرُسُ التَّمْرِيضَ، سَأَعْمَلُ مُمَرِّضًا."],"questions":[{"question":"من يبيع الدواء؟","options":["الصيدلي","المهندس","المعلم","الطيار"],"answer":0,"explanation":"الصيدلي."},{"question":"من يدرس التمريض سيعمل:","options":["مهندسًا","طيارًا","ممرضًا","معلمًا"],"answer":2,"explanation":"ممرضًا."},{"question":"من يدرس الطب سيعمل:","options":["صيدليًا","مهندسًا","طبيبًا","طيارًا"],"answer":2,"explanation":"طبيبًا."},{"question":"«بعد الدراسة» أي:","options":["عندما تنتهي الدراسة","في العطلة فقط","قبلها","اليوم"],"answer":0,"explanation":"after studying."}]},{"body":["الطالب الخامس: أدرس الهندسة في كلية الهندسة، سأعمل مهندسًا.","الطالب السادس: أدرس الطيران في كلية الطيران، سأعمل طيارًا.","الطالب الأول: أدرس التربية في كلية التربية، سأعمل مدرسًا.","«الطيار» يقود الطائرة. «المدرس» يعلم الطلاب.","الجملة تتكرر: أدرس ... في كلية ...، سأعمل ... إن شاء الله."],"examples":["الطَّالِبُ الْخَامِسُ: أَدْرُسُ الْهَنْدَسَةَ فِي كُلِّيَّةِ الْهَنْدَسَةِ، سَأَعْمَلُ مُهَنْدِسًا.","الطَّالِبُ السَّادِسُ: أَدْرُسُ الطَّيَرَانَ فِي كُلِّيَّةِ الطَّيَرَانِ، سَأَعْمَلُ طَيَّارًا.","الطَّالِبُ الْأَوَّلُ: أَدْرُسُ التَّرْبِيَةَ فِي كُلِّيَّةِ التَّرْبِيَةِ، سَأَعْمَلُ مُدَرِّسًا."],"questions":[{"question":"من يقود الطائرة؟","options":["الممرض","الطيار","الصيدلي","المدرس"],"answer":1,"explanation":"الطيار."},{"question":"من يدرس الهندسة؟","options":["الصيدلي","الطبيب","الطيار","المهندس"],"answer":3,"explanation":"مهندس."},{"question":"من يدرس في كلية التربية؟","options":["الطيار","المدرس","المهندس","الطبيب"],"answer":1,"explanation":"مدرس."},{"question":"نقول في آخر الجملة:","options":["أين","لا","إن شاء الله","مع السلامة"],"answer":2,"explanation":"للمستقبل."}]}]},{"id":"abyb1-057","title":"أنا مدرسة: ما مهنتك؟","summary":"الحوار الثالث: مريم وزينب، المرحلة الدراسية، والأطفال.","segments":[{"body":["الحوار الثالث بين مريم وزينب. مريم: أنا مدرسة. ما مهنتك؟","«المهنة» هي العمل الذي يعمله الشخص. زينب: أنا مدرسة أيضًا.","مريم: في أي مرحلة تدرسين؟ «المرحلة» جزء من التعليم.","زينب: أدرس في المرحلة الابتدائية. وفي أي مرحلة تدرسين أنت؟","مريم: أدرس في المرحلة المتوسطة."],"examples":["مَرْيَم: أَنَا مُدَرِّسَةٌ. مَا مِهْنَتُكِ؟","زَيْنَب: أَنَا مُدَرِّسَةٌ أَيْضًا.","مَرْيَم: فِي أَيِّ مَرْحَلَةٍ تُدَرِّسِينَ؟","زَيْنَب: أُدَرِّسُ فِي الْمَرْحَلَةِ الِابْتِدَائِيَّةِ.","مَرْيَم: أُدَرِّسُ فِي الْمَرْحَلَةِ الْمُتَوَسِّطَةِ."],"questions":[{"question":"ما «المهنة»؟","options":["المدينة","الاسم","اللون","العمل الذي يعمله الشخص"],"answer":3,"explanation":"profession."},{"question":"في أي مرحلة تدرس زينب؟","options":["الابتدائية","المتوسطة","الجامعية","الثانوية"],"answer":0,"explanation":"الابتدائية."},{"question":"في أي مرحلة تدرس مريم؟","options":["الابتدائية","لا تدرس","المتوسطة","الجامعية"],"answer":2,"explanation":"المتوسطة."},{"question":"مهنة مريم وزينب:","options":["مهندسة","مدرسة","طبيبة","طيارة"],"answer":1,"explanation":"مدرستان."}]},{"body":["زينب: هل لك أطفال؟ «طفل» ولد صغير. وجمعه أطفال.","مريم: نعم، لي أطفال. زينب: كم طفلًا لك؟ مريم: لي خمسة أطفال.","«لي» أي: عندي. «لك» أي: عندك.","زينب: هل تحبين عملك؟ مريم: نعم، أحب عملي. زينب: وأنا أحب عملي أيضًا.","للمرأة نقول: تحبين. وللرجل: تحب."],"examples":["زَيْنَب: هَلْ لَكِ أَطْفَالٌ؟","مَرْيَم: نَعَمْ، لِي أَطْفَالٌ.","زَيْنَب: كَمْ طِفْلًا لَكِ؟","مَرْيَم: لِي خَمْسَةُ أَطْفَالٍ.","زَيْنَب: هَلْ تُحِبِّينَ عَمَلَكِ؟","مَرْيَم: نَعَمْ، أُحِبُّ عَمَلِي."],"questions":[{"question":"جمع «طفل»:","options":["طفلات","أطفل","أطفال","طفلون"],"answer":2,"explanation":"أطفال."},{"question":"«لي أطفال» أي:","options":["أنا طفل","عندي أطفال","لا أطفال","أحب الأطفال"],"answer":1,"explanation":"I have children."},{"question":"كم طفلًا لمريم؟","options":["واحد","ثلاثة","خمسة","عشرة"],"answer":2,"explanation":"خمسة."},{"question":"نقول للمرأة:","options":["هل يحب عملها؟","هل تحب عملك؟","هل تحبين عملك؟","هل أحب عملك؟"],"answer":2,"explanation":"تحبين."}]}]},{"id":"abyb1-058","title":"المهن والأماكن: طبيب ومهندس وطيار","summary":"مفردات المهن: طبيب، مهندس، صيدلي، ممرض، طيار، مدرس، وأماكن العمل.","segments":[{"body":["المهن: طبيب، مهندس، صيدلي، ممرض، طيار، مدرس.","للمؤنث نزيد ة: طبيبة، مهندسة، صيدلية، ممرضة، طيارة، مدرسة.","أماكن العمل: مستشفى، شركة، مدرسة، صيدلية.","الدراسة لهذه المهن في الكليات: كلية الطب، الهندسة، الصيدلة، التمريض، الطيران، التربية.","مثال: الطبيب يعمل في المستشفى. المدرس يعمل في المدرسة."],"examples":["طَبِيب، مُهَنْدِس، صَيْدَلِيّ، مُمَرِّض، طَيَّار، مُدَرِّس.","طَبِيبَة، مُهَنْدِسَة، مُمَرِّضَة، مُدَرِّسَة."],"questions":[{"question":"أين يعمل الطبيب؟","options":["في المستشفى","في المطعم","في المسجد","في الحافلة"],"answer":0,"explanation":"المستشفى."},{"question":"مؤنث «ممرض»:","options":["ممرضين","ممرض","ممرضون","ممرضة"],"answer":3,"explanation":"ممرضة."},{"question":"أين يعمل المدرس؟","options":["في الطائرة","في الشركة فقط","في المستشفى","في المدرسة"],"answer":3,"explanation":"المدرسة."},{"question":"الدراسة للطب في:","options":["كلية الطيران","كلية التربية","كلية الهندسة","كلية الطب"],"answer":3,"explanation":"كلية الطب."}]},{"body":["كلمات أخرى: أحب، ساعة، طفل، أطفال، مهنة، مرحلة.","المراحل: الابتدائية، المتوسطة، ثم الثانوية.","الطفل الصغير يدرس في المرحلة الابتدائية.","نسأل: ما مهنتك؟ ونجيب: مهنتي طبيب. أو: أنا طبيب.","للمرأة: ما مهنتك؟ مهنتي مدرسة."],"examples":["مَا مِهْنَتُكَ؟ مِهْنَتِي طَبِيبٌ.","الْمَرْحَلَةُ الِابْتِدَائِيَّةُ، الْمَرْحَلَةُ الْمُتَوَسِّطَةُ."],"questions":[{"question":"ما الجواب: ما مهنتك؟","options":["لا","أنا في البيت","مهنتي مهندس","غدًا"],"answer":2,"explanation":"المهنة."},{"question":"المرحلة الأولى:","options":["الجامعية","الابتدائية","الثانوية","المتوسطة"],"answer":1,"explanation":"ابتدائية."},{"question":"الطفل الصغير يدرس في:","options":["الابتدائية","المستشفى","الشركة","الجامعة"],"answer":0,"explanation":"الابتدائية."},{"question":"«مهنتك» تسأل عن:","options":["المكان","العمل","الاسم","الوقت"],"answer":1,"explanation":"المهنة."}]}]},{"id":"abyb1-059","title":"الساعة من الأولى إلى الثانية عشرة","summary":"نقول الساعة بالأعداد الترتيبية المؤنثة.","segments":[{"body":["نقول الساعة بالترتيب المؤنث: الساعة الواحدة، الثانية، الثالثة، الرابعة، الخامسة، السادسة.","ثم: السابعة، الثامنة، التاسعة، العاشرة، الحادية عشرة، الثانية عشرة.","«الحادية عشرة» ١١. «الثانية عشرة» ١٢.","مثال: الساعة الآن الخامسة. الساعة الآن العاشرة.","نسأل: كم الساعة؟ ونجيب: الساعة الثانية."],"examples":["الْوَاحِدَةُ، الثَّانِيَةُ، الثَّالِثَةُ، الرَّابِعَةُ، الْخَامِسَةُ، السَّادِسَةُ.","السَّابِعَةُ، الثَّامِنَةُ، التَّاسِعَةُ، الْعَاشِرَةُ، الْحَادِيَةَ عَشْرَةَ، الثَّانِيَةَ عَشْرَةَ."],"questions":[{"question":"١١ نقول:","options":["العاشرة","الحادي عشر","الحادية عشرة","الثانية عشرة"],"answer":2,"explanation":"الحادية عشرة."},{"question":"١٢ نقول:","options":["العاشرة","الثالثة عشرة","الثانية عشرة","الحادية عشرة"],"answer":2,"explanation":"الثانية عشرة."},{"question":"الساعة ٩:","options":["التاسعة","العاشرة","الثامنة","السابعة"],"answer":0,"explanation":"التاسعة."},{"question":"الساعة ١:","options":["الأولى","الثانية","العاشرة","الواحدة"],"answer":3,"explanation":"الواحدة."}]},{"body":["نتدرب: ارسم عقارب الساعة حسب الوقت. الساعة الخامسة، الساعة الواحدة، الساعة الرابعة.","ثم انظر إلى الساعة وقل الوقت.","الجواب: الساعة الآن السابعة. الساعة الآن الثامنة.","نقول: أستيقظ الساعة السادسة. أعمل الساعة الثامنة.","الوقت مهم في العمل: متى يبدأ العمل؟"],"examples":["أَسْتَيْقِظُ السَّاعَةَ السَّادِسَةَ.","أَعْمَلُ السَّاعَةَ الثَّامِنَةَ.","كَمِ السَّاعَةُ؟ السَّاعَةُ الْآنَ السَّابِعَةُ."],"questions":[{"question":"كيف نسأل عن الوقت؟","options":["ماذا الساعة؟","أين الساعة؟","من الساعة؟","كم الساعة؟"],"answer":3,"explanation":"كم الساعة؟"},{"question":"اكمل: أعمل الساعة ... (٨)","options":["الثماني","الثامنة","الثامن","الثمانية"],"answer":1,"explanation":"الثامنة."},{"question":"اكمل: أستيقظ الساعة ... (٦)","options":["السادسة","السادس","الست","الستة"],"answer":0,"explanation":"السادسة."},{"question":"الساعة الآن ٧:","options":["السادسة","السابعة","التاسعة","الثامنة"],"answer":1,"explanation":"السابعة."}]}]},{"id":"abyb1-060","title":"كم ساعة تعمل؟ كم طفلًا لك؟","summary":"التراكيب: كم مع العدد والمعدود.","segments":[{"body":["مثال: كم ساعة تعمل في اليوم؟ أعمل ثماني ساعات في اليوم.","بعد العدد من ٣ إلى ١٠ نضع الجمع: ثلاث ساعات، أربع ساعات، خمس ساعات.","وبعد كم نضع المفرد المنصوب: كم ساعةً؟ كم طفلًا؟","مثال: ثلاثة أطفال، أربعة أطفال، خمسة أطفال، ستة أطفال، سبعة أطفال، ثمانية أطفال، تسعة أطفال.","السؤال: كم طفلًا لك؟ الجواب: لي خمسة أطفال."],"examples":["كَمْ سَاعَةً تَعْمَلُ فِي الْيَوْمِ؟ أَعْمَلُ ثَمَانِيَ سَاعَاتٍ.","كَمْ طِفْلًا لَكَ؟ لِي خَمْسَةُ أَطْفَالٍ.","ثَلَاثَةُ أَطْفَالٍ، أَرْبَعَةُ أَطْفَالٍ."],"questions":[{"question":"بعد «كم» نضع:","options":["مفردًا","حرفًا","فعلًا","جمعًا"],"answer":0,"explanation":"كم ساعةً."},{"question":"بعد ثلاثة نضع:","options":["المثنى","المفرد","فعلًا","الجمع"],"answer":3,"explanation":"ثلاثة أطفال."},{"question":"اكمل: لي خمسة ...","options":["طفلين","طفل","أطفال","طفلان"],"answer":2,"explanation":"أطفال."},{"question":"اكمل: أعمل سبع ...","options":["ساعتين","ساعات","ساعة","ساعتان"],"answer":1,"explanation":"ساعات."}]},{"body":["للمذكر والمؤنث: الأعداد ٣ إلى ١٠ تعكس التأنيث. الطفل مذكر فنقول: ثلاثة أطفال. الساعة مؤنث فنقول: ثلاث ساعات.","لاحظ: ثلاثة أطفال (بالتاء) وثلاث ساعات (بلا تاء).","هذه قاعدة تحتاج تدريبًا: العدد يخالف المعدود.","نتدرب: أربعة أيام، أربع حصص. خمسة أشهر، خمس سنوات.","إذا ارتبكت، احفظ الأمثلة."],"examples":["ثَلَاثَةُ أَطْفَالٍ. ثَلَاثُ سَاعَاتٍ.","أَرْبَعَةُ أَيَّامٍ. أَرْبَعُ حِصَصٍ."],"questions":[{"question":"اختر الصحيح:","options":["ثلاثة ساعات","ثلاث ساعات","ثلاث ساعة","ثلاثة ساعة"],"answer":1,"explanation":"ساعة مؤنث."},{"question":"اختر الصحيح:","options":["أربع أيام","أربع يوم","أربعة أيام","أربعة يوم"],"answer":2,"explanation":"يوم مذكر."},{"question":"اختر الصحيح:","options":["خمسة حصة","خمس حصص","خمسة حصص","خمس حصة"],"answer":1,"explanation":"حصة مؤنث."},{"question":"العدد ٣ إلى ١٠ يخالف المعدود في:","options":["الوقت","اللون","التذكير والتأنيث","الطول"],"answer":2,"explanation":"يخالفه."}]}]},{"id":"abyb1-061","title":"العمل: مراجعة الوحدة والكتاب","summary":"مراجعة الحوارات والمهن، وخلاصة ما تعلمنا في الجزء الأول.","segments":[{"body":["نراجع الحوارات: عثمان وعلي عن العمل. الطلاب عن مهن المستقبل. مريم وزينب عن التدريس والأطفال.","من الأسئلة: ماذا تعمل؟ أين تعمل؟ كم ساعة تعمل؟ هل تحب عملك؟","ومن التراكيب: سأعمل ... إن شاء الله. لي أطفال. أحب عملي.","نكتب فقرة قصيرة: أنا ... أعمل في ... ثماني ساعات في اليوم. أحب عملي.","نقرأ الفقرة بصوت عالٍ."],"examples":["مَاذَا تَعْمَلُ؟ أَيْنَ تَعْمَلُ؟ كَمْ سَاعَةً تَعْمَلُ؟","أَنَا طَبِيبٌ. أَعْمَلُ فِي الْمُسْتَشْفَى. أُحِبُّ عَمَلِي."],"questions":[{"question":"اختر سؤالًا عن مكان العمل:","options":["من تعمل؟","كم تعمل؟","أين تعمل؟","متى تعمل؟"],"answer":2,"explanation":"أين."},{"question":"اكمل: ... عملي","options":["تحب","نحب","يحب","أحب"],"answer":3,"explanation":"أحب."},{"question":"«سأعمل» تعني:","options":["لا أعمل","عملت","أعمل الآن فقط","في المستقبل أعمل"],"answer":3,"explanation":"مستقبل."},{"question":"اكمل: لي ثلاثة ...","options":["طفلين","طفل","طفلة","أطفال"],"answer":3,"explanation":"أطفال."}]},{"body":["في الجزء الأول تعلمنا: التحية والتعارف، الأسرة، البيت، الحياة اليومية، الطعام، الصلاة، الدراسة، العمل.","تعلمنا الأفعال مع أنا وأنت وهو وهي، وأسئلة: ماذا؟ أين؟ متى؟ كم؟ لماذا؟","وتعلمنا الأعداد والترتيب والساعة، وأيام الأسبوع.","الخطوة التالية: الاستمرار في القراءة والحوار كل يوم.","أحسنت! أنهيت الوحدات الثماني من هذا الجزء."],"examples":["أَسْتَيْقِظُ، أَعْمَلُ، أَدْرُسُ، أُصَلِّي.","مَنْ؟ مَاذَا؟ أَيْنَ؟ مَتَى؟ كَمْ؟ لِمَاذَا؟"],"questions":[{"question":"أي سؤال عن الزمان؟","options":["كم؟","متى؟","من؟","أين؟"],"answer":1,"explanation":"متى."},{"question":"أي كلمة سؤال عن السبب؟","options":["كم","لماذا","أين","متى"],"answer":1,"explanation":"لماذا."},{"question":"أي كلمة سؤال عن الشخص؟","options":["أين","كم","ماذا","من"],"answer":3,"explanation":"من."},{"question":"كم وحدة أنهيت في هذا الجزء؟","options":["عشر","ثماني","ست","أربع"],"answer":1,"explanation":"ثماني وحدات."}]}]},{"id":"abyb1-062","title":"صوت العين وصوت الهمزة","summary":"الوحدة الثانية: التمييز بين ع وأ في السمع والنطق.","segments":[{"body":["في العربية صوتان قريبان: «ع» و«أ» (الهمزة). كثير من المتعلمين يخلطون بينهما.","«ع» يخرج من وسط الحلق. تضيّق الحلق قليلًا وتخرج الصوت. مثل: عمر، عمار.","«أ» (الهمزة) وقفة قصيرة في أول الحلق. الصوت يتوقف ثم يخرج. مثل: أحمد، أمّ.","الفرق يغيّر المعنى. «عليم» أي: يعرف كل شيء. «أليم» أي: مؤلم.","«علم» أي: معرفة، و«ألم» أي: وجع."],"examples":["عُمَر، عَمَّار، عَلَيْكُم، عَبْدُ اللهِ، الْعَبَّاس، عَمُّه، سَعْد","عَلِيم / أَلِيم","عَتَتْ / أَتَتْ","عَلَم / أَلَم","عَسِير / أَسِير"],"questions":[{"question":"«ع» يخرج من:","options":["الشفتين","اللسان فقط","وسط الحلق","الأنف"],"answer":2,"explanation":"العين من وسط الحلق."},{"question":"الهمزة هي:","options":["وقفة قصيرة في أول الحلق","صوت من الأسنان","صوت طويل من الأنف","حرف من الشفتين"],"answer":0,"explanation":"الهمزة وقفة قصيرة."},{"question":"أي كلمة تبدأ بعين؟","options":["أنت","أمّ","أحمد","عمر"],"answer":3,"explanation":"عمر تبدأ بالعين."},{"question":"أي كلمة تبدأ بهمزة؟","options":["عمّار","عليم","أليم","علم"],"answer":2,"explanation":"أليم تبدأ بالهمزة."}]},{"body":["نتدرب على كلمات تشبه بعضها. الأولى بالعين والثانية بالهمزة.","جاع: صار جائعًا. جاء: وصل. الكلمتان تختلفان في الحرف الأخير فقط.","عسير أي: صعب. أسير أي: محبوس عند عدوّه.","في القرآن: ﴿فَإِنَّ مَعَ الْعُسْرِ يُسْرًا﴾. كلمة «العسر» فيها عين.","وفي سورة النبأ: ﴿عَمَّ يَتَسَاءَلُونَ﴾. نسمع العين في أول الآية."],"examples":["جَاعَ / جَاءَ","أَجْزَاع / أَجْزَاء","﴿فَإِنَّ مَعَ الْعُسْرِ يُسْرًا﴾","﴿عَمَّ يَتَسَاءَلُونَ﴾"],"questions":[{"question":"«عليم» تعني:","options":["محبوس","يعرف كل شيء","مؤلم","صعب"],"answer":1,"explanation":"عليم من العلم."},{"question":"«أليم» تعني:","options":["عالم","مؤلم","كبير","سهل"],"answer":1,"explanation":"أليم أي موجع."},{"question":"«عسير» تعني:","options":["سهل","جديد","قريب","صعب"],"answer":3,"explanation":"عسير ضد يسير."},{"question":"في ﴿عَمَّ يَتَسَاءَلُونَ﴾ أول صوت هو:","options":["هاء","همزة","عين","غين"],"answer":2,"explanation":"عمّ تبدأ بالعين."}]}]},{"id":"abyb1-063","title":"الكتابة: الحروف ط ظ ا","summary":"كتابة الطاء والظاء والألف في أول الكلمة ووسطها وآخرها.","segments":[{"body":["الطاء «ط» والظاء «ظ» حرفان متشابهان. الفرق: نقطة فوق الظاء.","كلمات فيها طاء: طالب، فاطمة، خيط. كلمات فيها ظاء: ظفر، نظارة، حافظ.","الطاء في أول الكلمة: طـ. في الوسط: ـطـ. في الآخر: ـط.","الظاء مثلها: ظـ، ـظـ، ـظ. ونضع النقطة فوق الحرف في كل الأشكال.","نكتب بالقلم على الحرف أولًا، ثم نكتب الكلمة كاملة."],"examples":["طَالِب، فَاطِمَة، خَيْط","ظُفْر، نَظَّارَة، حَافِظ","طَبِيب، طَبِيبَة"],"questions":[{"question":"ما الفرق بين ط وظ؟","options":["لا فرق","الطاء أكبر فقط","نقطة فوق الظاء","نقطتان تحت الطاء"],"answer":2,"explanation":"الظاء عليها نقطة."},{"question":"أي كلمة فيها ظاء؟","options":["نظارة","فاطمة","طالب","خيط"],"answer":0,"explanation":"نظّارة فيها ظاء."},{"question":"أي كلمة فيها طاء؟","options":["خيط","حافظ","ظفر","نظارة"],"answer":0,"explanation":"خيط فيها طاء."},{"question":"شكل الطاء في آخر الكلمة:","options":["ـط","ظ","ـطـ","طـ"],"answer":0,"explanation":"في الآخر نكتب ـط."}]},{"body":["الألف «ا» حرف خاص. شكلها عمود قصير. لا نصلها بالحرف الذي بعدها.","إذا جاءت الألف بعد حرف، نصلها به من الخلف فقط. مثل: سوريا، مساء، طالب.","في الكلمة «هذا» الألف في الآخر. وفي «والد» الألف في الوسط.","نتدرب: نلاحظ الحرف ونعيد على النقاط، ثم نصل الحرفين المتطابقين.","ونكتب الحرف الناقص في كل كلمة، مثل: توضّأ، ثلاثة، هيا بنا، تسعة."],"examples":["سُورِيَا، مَسَاء","هَذَا، حَمَّام، أَكْبَر، وَالِد، قَرَأَ","تَوَضَّأ، ثَلَاثَة، هَيَّا بِنَا، تِسْعَة"],"questions":[{"question":"الألف تُوصل بالحرف:","options":["بالحرفين","الذي قبلها فقط","الذي بعدها فقط","لا توصل أبدًا"],"answer":1,"explanation":"لا نصل الألف بما بعدها."},{"question":"أي كلمة فيها ألف في الوسط؟","options":["طبيب","هذا","والد","أخت"],"answer":2,"explanation":"والد فيها ألف في الوسط."},{"question":"أي كلمة فيها ظاء وألف معًا؟","options":["غرفة","نظارة","طبيب","خيط"],"answer":1,"explanation":"نظّارة فيها ظاء وألف."},{"question":"الحرف الناقص في «ثلا..ة»:","options":["ط","ظ","ث","ع"],"answer":2,"explanation":"ثلاثة."}]}]},{"id":"abyb1-064","title":"صوت الغين وصوت القاف","summary":"الوحدة السابعة: التمييز بين غ وق.","segments":[{"body":["في هذه الوحدة نتعلم الفرق بين «غ» و«ق». الغين فوقها نقطة. القاف فوقها نقطتان.","الغين صوت ناعم من الحلق. مثل: غسان، غيث، غالب.","القاف صوت قوي من آخر اللسان. مثل: قال، قام، قد.","أسماء فيها غين: غسان، غيث، غالب، غانم، غدير، غزالة.","الصوتان يغيّران المعنى: غد (اليوم التالي) وقد (حرف يفيد التحقيق)."],"examples":["غَسَّان، غَيْث، غَالِب، غَانِم، غَدِير، غَزَالَة","غَدٌ / قَدْ","غَرّ / قَرّ"],"questions":[{"question":"كم نقطة فوق القاف؟","options":["ثلاث نقاط","لا نقاط","نقطة","نقطتان"],"answer":3,"explanation":"فوق القاف نقطتان."},{"question":"أي اسم يبدأ بغين؟","options":["فاروق","قيس","قاسم","غسان"],"answer":3,"explanation":"غسان."},{"question":"«غد» تعني:","options":["الآن","الصباح فقط","أمس","اليوم التالي"],"answer":3,"explanation":"غد: tomorrow."},{"question":"الصوت القوي من آخر اللسان هو:","options":["هـ","غ","ع","ق"],"answer":3,"explanation":"القاف."}]},{"body":["نتدرب على أزواج: غال وقال، غام وقام، غر وقر، غد وقد، غلبت وقلبت.","قال: تكلم. قام: وقف. غال: عزيز الثمن.","في القرآن: ﴿غُلِبَتِ الرُّومُ﴾ فيها غين.","وفي سورة الشرح: ﴿فَإِذَا فَرَغْتَ فَانصَبْ﴾ فيها غين.","نسمع الكلمتين مرتين ثم نكررهما بصوت واضح."],"examples":["غَالَ / قَالَ","غَامَ / قَامَ","غَلَبْتُ / قَلَبْتُ","﴿غُلِبَتِ الرُّومُ﴾","﴿فَإِذَا فَرَغْتَ فَانصَبْ﴾"],"questions":[{"question":"«قام» تعني:","options":["غاب","تكلم","وقف","نام"],"answer":2,"explanation":"قام أي وقف."},{"question":"«قال» تعني:","options":["تكلم","أكل","وقف","جلس"],"answer":0,"explanation":"قال أي تكلم."},{"question":"في ﴿غُلِبَتِ الرُّومُ﴾ الحرف الأول:","options":["فاء","عين","غين","قاف"],"answer":2,"explanation":"غلبت تبدأ بالغين."},{"question":"أي كلمة تبدأ بقاف؟","options":["غر","قد","غد","غام"],"answer":1,"explanation":"قد."}]}]},{"id":"abyb1-065","title":"صوت الضاد وصوت الدال","summary":"الوحدة الثامنة: التمييز بين ض ود.","segments":[{"body":["الضاد «ض» حرف عربي مشهور. ننطقه من جانب اللسان مع الأضراس.","الدال «د» أسهل: طرف اللسان يلمس أصول الأسنان العليا.","كلمات فيها ضاد: رمضان، يتوضأ، ضيوف، ممرضة، ممرض، أيضًا.","أزواج: ضالين ودالين، ضر ودر، ضل ودل، ضار ودار، ضلال ودلال.","الخطأ في الضاد قد يغير الكلمة كلها."],"examples":["رَمَضَان، يَتَوَضَّأ، ضُيُوف، مُمَرِّضَة، مُمَرِّض، أَيْضًا","ضَالِّين / دَالِّين","ضَرّ / دَرّ"],"questions":[{"question":"أي كلمة فيها ضاد؟","options":["رمضان","دار","حمام","سعيد"],"answer":0,"explanation":"رمضان."},{"question":"نطق الدال من:","options":["الشفتين","الحلق","طرف اللسان مع الأسنان","الأنف"],"answer":2,"explanation":"الدال من طرف اللسان."},{"question":"«ممرض» فيها حرف:","options":["ض","ذ","ظ","د"],"answer":0,"explanation":"ممرض فيها ضاد."},{"question":"«يتوضأ» تبدأ بحرف:","options":["ي","د","و","ض"],"answer":0,"explanation":"تبدأ بالياء."}]},{"body":["أزواج أخرى: بعض وبعد، مريض ومريد، رفض ورفد، قروض وقرود، فرض وفرد.","«بعض» أي جزء من الشيء. «بعد» عكس قبل.","«مريض» أي: عنده مرض. «فرض» أي: واجب. «فرد» أي: شخص واحد.","في سورة الفاتحة: ﴿غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ﴾.","وفي الواقعة وغيرها آيات فيها ضاد: ﴿وَطَلْحٍ مَنْضُودٍ﴾."],"examples":["بَعْض / بَعْد","مَرِيض / مَرِيد","فَرْض / فَرْد","﴿غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ﴾"],"questions":[{"question":"«بعد» عكسها:","options":["بعض","فرد","قبل","مريض"],"answer":2,"explanation":"بعد ضد قبل."},{"question":"«مريض» تعني:","options":["يسافر","يأكل","عنده مرض","يعمل"],"answer":2,"explanation":"مريض: sick."},{"question":"«فرض» تعني:","options":["جزء","شخص واحد","قبل","واجب"],"answer":3,"explanation":"فرض أي واجب."},{"question":"في آخر الفاتحة نسمع كلمة فيها ضاد:","options":["الدين","الضالين","العالمين","الرحيم"],"answer":1,"explanation":"الضالين."}]}]},{"id":"abyb1-066","title":"قراءة الوحدة الثامنة: عمر الطيار وفاطمة المدرسة","summary":"فقرتان قصيرتان وأسئلة عليهما، من تدريبات القراءة في الوحدة.","segments":[{"body":["الفقرة الأولى عن عمر. نقرأ ثم نجيب.","«الإجازة» أو «العطلة» أيام لا نعمل فيها. «مبكرًا» أي: في أول الوقت.","عمر يبدأ العمل الساعة السادسة صباحًا، وينتهي الساعة الواحدة ظهرًا.","يعمل سبع ساعات في اليوم وخمسة أيام في الأسبوع.","عطلته يوم الخميس ويوم الجمعة. يذهب إلى الشركة بالسيارة."],"examples":["عُمَرُ طَيَّارٌ، دَرَسَ الطَّيَرَانَ فِي كُلِّيَّةِ الطَّيَرَانِ، وَهُوَ يَعْمَلُ فِي شَرِكَةِ الطَّيَرَانِ.","يَذْهَبُ عُمَرُ إِلَى الشَّرِكَةِ مُبَكِّرًا.","يَبْدَأُ الْعَمَلُ السَّاعَةَ السَّادِسَةَ صَبَاحًا، وَيَنْتَهِي السَّاعَةَ الْوَاحِدَةَ ظُهْرًا.","يَعْمَلُ سَبْعَ سَاعَاتٍ فِي الْيَوْمِ، وَخَمْسَةَ أَيَّامٍ فِي الْأُسْبُوعِ.","الْعُطْلَةُ يَوْمُ الْخَمِيسِ وَيَوْمُ الْجُمُعَةِ."],"questions":[{"question":"ما مهنة عمر؟","options":["طيار","طبيب","مهندس","مدرس"],"answer":0,"explanation":"طيار."},{"question":"متى يبدأ عمر العمل؟","options":["الساعة السادسة صباحًا","الساعة الثامنة مساءً","الساعة الواحدة ظهرًا","الساعة الثالثة"],"answer":0,"explanation":"السادسة صباحًا."},{"question":"كم يومًا يعمل في الأسبوع؟","options":["ثلاثة أيام","يومين","سبعة أيام","خمسة أيام"],"answer":3,"explanation":"خمسة أيام."},{"question":"كيف يذهب إلى الشركة؟","options":["سيرًا","بالطائرة","بالسيارة","بالحافلة"],"answer":2,"explanation":"بالسيارة."}]},{"body":["الفقرة الثانية عن فاطمة. هي مدرسة في المرحلة الابتدائية.","«الحصة» وقت الدرس. «الاستراحة» وقت راحة بين الحصص.","تستيقظ فاطمة الساعة الخامسة فجرًا، وتذهب إلى المدرسة الساعة السادسة صباحًا.","يبدأ اليوم الدراسي السابعة صباحًا وينتهي الثانية عشرة ظهرًا.","تدرّس خمس حصص في اليوم، وتذهب في الاستراحة إلى المكتبة."],"examples":["فَاطِمَةُ مُدَرِّسَةٌ فِي الْمَرْحَلَةِ الِابْتِدَائِيَّةِ. تَسْتَيْقِظُ السَّاعَةَ الْخَامِسَةَ فَجْرًا.","يَبْدَأُ الْيَوْمُ الدِّرَاسِيُّ السَّاعَةَ السَّابِعَةَ صَبَاحًا وَيَنْتَهِي السَّاعَةَ الثَّانِيَةَ عَشْرَةَ ظُهْرًا.","تُدَرِّسُ فَاطِمَةُ خَمْسَ حِصَصٍ فِي الْيَوْمِ.","تَذْهَبُ فَاطِمَةُ فِي الِاسْتِرَاحَةِ إِلَى الْمَكْتَبَةِ، وَتَقْرَأُ كِتَابًا أَوْ صَحِيفَةً."],"questions":[{"question":"متى تستيقظ فاطمة؟","options":["الساعة الثانية عشرة","الساعة الخامسة فجرًا","الساعة السابعة","الساعة التاسعة"],"answer":1,"explanation":"الخامسة فجرًا."},{"question":"كم حصة تدرّس في اليوم؟","options":["حصة واحدة","ثلاث حصص","خمس حصص","عشر حصص"],"answer":2,"explanation":"خمس حصص."},{"question":"إلى أين تذهب في الاستراحة؟","options":["إلى البيت","إلى المطار","إلى السوق","إلى المكتبة"],"answer":3,"explanation":"إلى المكتبة."},{"question":"«الحصة» هي:","options":["اسم المادة","وقت الدرس","وقت النوم","اسم المدرسة"],"answer":1,"explanation":"الحصة وقت الدرس."}]}]},{"id":"abyb1-067","title":"الكتابة في الوحدة الثامنة: رتّب الحروف والكلمات","summary":"ترتيب الحروف لتكوين كلمة، وترتيب الكلمات لتكوين جملة.","segments":[{"body":["في الكتابة نرتب الحروف لنكوّن كلمة. المثال: ط ف ل تصير «طفل».","ي د ر س تصير «يدرس». ي ع م ل تصير «يعمل». ط ي ا ر تصير «طيار».","ط ب تصير «طب». هـ ن د س ة تصير «هندسة».","نرتب الحروف ثم نصل بينها، ثم ننسخ الكلمة.","في التمرين الثاني نكتب مع الصور: يعمل، ممرض، أطفال، طيار، شركة، صيدلي، مستشفى، طفل."],"examples":["طِفْل","يَدْرُس","يَعْمَل","طَيَّار","طِبّ","هَنْدَسَة"],"questions":[{"question":"رتب: ي د ر س","options":["يرسد","درسي","يدرس","سردي"],"answer":2,"explanation":"يدرس."},{"question":"رتب: ط ي ا ر","options":["يطار","ارطي","ريطا","طيار"],"answer":3,"explanation":"طيار."},{"question":"رتب: هـ ن د س ة","options":["دهسنة","سندهة","هندسة","نهدسة"],"answer":2,"explanation":"هندسة."},{"question":"رتب: ي ع م ل","options":["يعمل","لمعي","يمعل","عيلم"],"answer":0,"explanation":"يعمل."}]},{"body":["الآن نرتب كلمات لنكوّن جملة. المثال: المستشفى أعمل في تصير: أعمل في المستشفى.","أحب أنا عملي: أنا أحب عملي. الطب أنا أدرس: أنا أدرس الطب.","في الفراغ نختار كلمة مناسبة: صديقي أحمد ... (طالب).","كم ساعة ...؟ نختار «تعمل». هل ... عملك؟ نختار «تحب».","وفي الجملة: أعمل في ... نختار «الشركة» أو «المستشفى»."],"examples":["أَعْمَلُ فِي الْمُسْتَشْفَى.","أَنَا أُحِبُّ عَمَلِي.","أَنَا أَدْرُسُ الطِّبَّ.","كَمْ سَاعَةً تَعْمَلُ؟","هَلْ تُحِبُّ عَمَلَكَ؟"],"questions":[{"question":"رتب: أدرس أنا الطب","options":["الطب أنا أدرس","أدرس الطب أنا","أنا الطب أدرس","أنا أدرس الطب"],"answer":3,"explanation":"أنا أدرس الطب."},{"question":"اكمل: كم ساعة ... في اليوم؟","options":["أطفال","تعمل","طبيب","مستشفى"],"answer":1,"explanation":"تعمل."},{"question":"اكمل: هل ... عملك؟","options":["طبيب","تحب","تنام","تأكل"],"answer":1,"explanation":"تحب."},{"question":"رتب: عملي أحب أنا","options":["أنا عملي أحب","أحب عملي أنا","عملي أنا أحب","أنا أحب عملي"],"answer":3,"explanation":"أنا أحب عملي."}]}]},{"id":"abyb1-068","title":"اختبر نفسك (1): الوحدتان الأولى والثانية","summary":"مراجعة المفردات والتراكيب من الوحدتين 1 و2.","segments":[{"body":["هذا اختبار قصير. أولًا: نصنف الكلمات في مجموعات. البلد: مصر، سوريا، باكستان، تركيا.","الضمير: أنت، هو، هي، أنا. الرقم: واحد، ثلاثة، خمسة، تسعة.","الأسرة: والد، أخت، ابن، جدة. المكان: غرفة، حمام، مسجد، مصلى.","المهنة: مدرس، طالب، طبيبة، مهندسة.","في الجملة نختار الكلمة المناسبة: أحمد في المسجد ... (يصلي). هذا ... الفجر (أذان)."],"examples":["مِصْر، سُورِيَا، بَاكِسْتَان، تُرْكِيَا","أَنْتَ، هُوَ، هِيَ","وَاحِد، ثَلَاثَة، خَمْسَة، تِسْعَة","أَحْمَدُ فِي الْمَسْجِدِ يُصَلِّي.","هَذَا أَذَانُ الْفَجْرِ."],"questions":[{"question":"أي كلمة اسم بلد؟","options":["باكستان","طالب","حمام","هي"],"answer":0,"explanation":"باكستان بلد."},{"question":"أي كلمة ضمير؟","options":["هو","غرفة","مصر","ثلاثة"],"answer":0,"explanation":"هو ضمير."},{"question":"أي كلمة مهنة؟","options":["مهندسة","خمسة","مسجد","جدة"],"answer":0,"explanation":"مهندسة مهنة."},{"question":"اكمل: أحمد في المسجد ...","options":["يصلي","يسافر","ينام","يأكل"],"answer":0,"explanation":"يصلي."}]},{"body":["ثانيًا: التراكيب. نصحح الخطأ: «هذه هو النظارة» خطأ. الصحيح: هذه هي النظارة.","«هيا بنا في المسجد» خطأ. الصحيح: هيا بنا إلى المسجد.","«والدتي سعيدة طبيبًا» خطأ. الصحيح: والدتي سعيدة طبيبة.","أدوات الاستفهام: من (للشخص)، ما (للشيء)، أين (للمكان)، هل (نعم أو لا).","نختار الكلمة الصحيحة: هذا / هذه. نقول: هذه شجرة، وهذا مسجد."],"examples":["هَذِهِ هِيَ النَّظَّارَةُ يَا أَبِي.","هَيَّا بِنَا إِلَى الْمَسْجِدِ.","وَالِدَتِي سَعِيدَةُ طَبِيبَةٌ.","مَنْ هَذَا؟ مَا هَذَا؟ أَيْنَ الْمِعْطَف؟ هَلْ أَنْتَ بَاكِسْتَانِيّ؟"],"questions":[{"question":"الجملة الصحيحة:","options":["هذه هو النظارة","هذا هو النظارة","هذه هي النظارة","هذا هي النظارة"],"answer":2,"explanation":"هذه مع هي للمؤنث."},{"question":"اكمل: هيا بنا ... المسجد","options":["إلى","من","هل","على"],"answer":0,"explanation":"هيا بنا إلى."},{"question":"سؤال عن المكان:","options":["من هذا؟","هل أنت؟","ما اسمك؟","أين المعطف؟"],"answer":3,"explanation":"أين للمكان."},{"question":"نقول:","options":["هذه شجرة","هذا شجرة","هذه مسجد","هذا شجرة كبير"],"answer":0,"explanation":"شجرة مؤنث فنقول هذه."}]}]},{"id":"abyb1-069","title":"اختبر نفسك (2): الوحدتان الثالثة والرابعة","summary":"مراجعة المفردات والتراكيب من الوحدتين 3 و4.","segments":[{"body":["أولًا: المفردات. نصل الشيء بمكانه. الفرن في المطبخ. السرير في غرفة النوم.","الأريكة في غرفة الجلوس. المرآة في الحمام. الكتاب في المدرسة. الصلاة في المسجد.","نضيف كلمتين لكل مجموعة. أثاث: مرآة، سرير، أريكة. غرف: حمام، مطبخ، غرفة نوم.","أعداد ترتيبية: الأول، الثاني، الثالث. أفعال: يذهب، يقرأ، يغسل. أعداد: سبعة.","الكلمة الغريبة في «طبيب، مدرس، مهندس، سيارة» هي «سيارة»."],"examples":["الْفُرْنُ فِي الْمَطْبَخِ.","السَّرِيرُ فِي غُرْفَةِ النَّوْمِ.","الْأَرِيكَةُ فِي غُرْفَةِ الْجُلُوسِ.","الْمِرْآةُ فِي الْحَمَّامِ."],"questions":[{"question":"أين الفرن؟","options":["في المدرسة","في المسجد","في المطبخ","في الحمام"],"answer":2,"explanation":"الفرن في المطبخ."},{"question":"أين السرير؟","options":["في المدرسة","في المطبخ","في المسجد","في غرفة النوم"],"answer":3,"explanation":"السرير في غرفة النوم."},{"question":"الكلمة الغريبة:","options":["مدرس","سيارة","طبيب","مهندس"],"answer":1,"explanation":"سيارة ليست مهنة."},{"question":"أي كلمة عدد ترتيبي؟","options":["الثالث","يذهب","هل","سبعة"],"answer":0,"explanation":"الثالث ترتيبي."}]},{"body":["ثانيًا: التراكيب. نصل بين جزأي الجملة: يغسل الملابس والأطباق. يشاهد التلفاز.","يذهب إلى المدرسة. يكنس الغرفة. يقرأ الصحيفة. يصلي للصلاة. يسكن في حي الجامعة. يتوضأ للصلاة.","نختار الكلمة الصحيحة: في الشقة أربع (غرف). كم ... في الشقة؟ (غرف).","«متى» يسأل عن الوقت: متى تذهب إلى المدرسة؟","أذهب الساعة السابعة. الساعة هنا مؤنثة، فنقول: هذه الشقة، هي كبيرة."],"examples":["فِي الشَّقَّةِ أَرْبَعُ غُرَفٍ.","مَتَى تَذْهَبُ إِلَى الْمَدْرَسَةِ؟","أَذْهَبُ السَّاعَةَ السَّابِعَةَ.","هَذِهِ الشَّقَّةُ كَبِيرَةٌ."],"questions":[{"question":"اكمل: في الشقة أربع ...","options":["طبيب","غرف","سرير","غرفة"],"answer":1,"explanation":"أربع غرف."},{"question":"سؤال عن الوقت:","options":["أين تذهب؟","متى تذهب؟","هل تذهب؟","من تذهب؟"],"answer":1,"explanation":"متى للوقت."},{"question":"اكمل: هذه الشقة ...","options":["كبير","كبيرين","كبار","كبيرة"],"answer":3,"explanation":"الشقة مؤنثة."},{"question":"ما معنى «يتوضأ»؟","options":["يسافر","ينام","يأكل","يغسل أعضاء الوضوء قبل الصلاة"],"answer":3,"explanation":"الوضوء قبل الصلاة."}]}]},{"id":"abyb1-070","title":"اختبر نفسك (3): الوحدتان الخامسة والسادسة","summary":"مراجعة المفردات والتراكيب من الوحدتين 5 و6.","segments":[{"body":["أولًا: المفردات. نصل الكلمة بما يناسبها: طعام وشراب. نحيف وسمين. شاي وقهوة.","لحم ودجاج. قليل وكثير. يأكل ويشرب. قريب وبعيد.","الكلمة الغريبة: «ظهر، عصر، مغرب، أذان». «أذان» ليس اسم صلاة.","الكلمة الغريبة: «سمك، شراب، دجاج، لحم». «شراب» ليس طعامًا.","نكمل الجمل: هل تشرب القهوة؟ لا، أفضل الشاي."],"examples":["طَعَامٌ وَشَرَابٌ","نَحِيفٌ وَسَمِينٌ","قَلِيلٌ وَكَثِيرٌ","قَرِيبٌ وَبَعِيدٌ","هَلْ تَشْرَبُ الْقَهْوَةَ؟ لَا، أُفَضِّلُ الشَّايَ."],"questions":[{"question":"ضد «قريب»:","options":["بعيد","سمين","قليل","كثير"],"answer":0,"explanation":"بعيد."},{"question":"ضد «نحيف»:","options":["قليل","كبير","سمين","قريب"],"answer":2,"explanation":"سمين."},{"question":"الكلمة الغريبة:","options":["لحم","سمك","شراب","دجاج"],"answer":2,"explanation":"شراب."},{"question":"الكلمة الغريبة بين أسماء الصلوات:","options":["مغرب","أذان","ظهر","عصر"],"answer":1,"explanation":"أذان ليس صلاة."}]},{"body":["ثانيًا: نصحح الأخطاء. «ماذا تطلب من الطعام يا فاطمة؟» جملة صحيحة.","«هل تشربين الشاي يا أحمد؟» خطأ. نقول لأحمد: هل تشرب الشاي؟","«المسجد بعيدة عن البيت» خطأ. المسجد مذكر: المسجد بعيد عن البيت.","«أنا مسافر إلى الحرم» ونقول: أنا ذاهب إلى المسجد. بعد «ذاهب» نستعمل إلى.","قراءة: محمد من مصر، مسافر إلى مكة للصلاة في المسجد الحرام، وسيصلي الصلوات الخمس هناك."],"examples":["هَلْ تَشْرَبُ الشَّايَ يَا أَحْمَدُ؟","الْمَسْجِدُ بَعِيدٌ عَنِ الْبَيْتِ.","أَنَا ذَاهِبٌ إِلَى الْمَسْجِدِ.","مُحَمَّدٌ مِنْ مِصْرَ، مُسَافِرٌ إِلَى مَكَّةَ لِلصَّلَاةِ."],"questions":[{"question":"نسأل أحمد:","options":["هل يشربن؟","هل تشربين الشاي؟","هل تشرب الشاي؟","هل تشربون؟"],"answer":2,"explanation":"للمذكر: تشرب."},{"question":"الجملة الصحيحة:","options":["المسجد بعيد عن البيت","المسجد بعيدة عن البيت","المسجد بعيدات","المسجد بعيدان"],"answer":0,"explanation":"المسجد مذكر."},{"question":"اكمل: أنا ذاهب ... المسجد","options":["هل","إلى","من أين","ماذا"],"answer":1,"explanation":"إلى."},{"question":"إلى أين يسافر محمد؟","options":["إلى البيت","إلى الجامعة","إلى مكة","إلى القاهرة"],"answer":2,"explanation":"إلى مكة."}]}]},{"id":"abyb1-071","title":"اختبر نفسك (4): الوحدتان السابعة والثامنة","summary":"مراجعة المفردات والتراكيب والقراءة من الوحدتين 7 و8.","segments":[{"body":["أولًا: المفردات. نضيف كلمتين لكل مجموعة. كليات: كلية الطب، كلية الهندسة، كلية التربية.","مهن: طب، طبيب، مدرس. أماكن: مختبر، مكتبة، جامعة. مواد دراسية: رياضيات، علوم.","أشخاص: طيار، طالب. أوقات: صباح، ظهر، مساء.","نضع علامة على الكلمة الغريبة: جامعة، كلية، مدرسة، طفل. الغريبة: طفل.","الكلمة الغريبة: يدرس، ينظر، يكتب، حصة. الغريبة: حصة، فهي اسم لا فعل."],"examples":["كُلِّيَّةُ الطِّبِّ، كُلِّيَّةُ الْهَنْدَسَةِ","رِيَاضِيَّات، عُلُوم","صَبَاح، ظُهْر، مَسَاء","يَدْرُسُ، يَنْظُرُ، يَكْتُبُ"],"questions":[{"question":"الكلمة الغريبة:","options":["مدرسة","كلية","جامعة","طفل"],"answer":3,"explanation":"الباقي أماكن للدراسة."},{"question":"الكلمة الغريبة:","options":["يكتب","ينظر","حصة","يدرس"],"answer":2,"explanation":"حصة اسم والباقي أفعال."},{"question":"مادة دراسية:","options":["رياضيات","شركة","مساء","طيار"],"answer":0,"explanation":"رياضيات."},{"question":"وقت من أوقات اليوم:","options":["مختبر","هندسة","صباح","طبيب"],"answer":2,"explanation":"صباح."}]},{"body":["ثانيًا: التراكيب. نصل جزأي الجملة: بدأت الحصة. سأكون مدرسة. أذهب بالسيارة. أكتب على اللوحة.","نختار الكلمة الصحيحة: لي خمسة (أطفال). هل (تحب) عملك يا زينب؟","سأعمل (مهندسًا) إن شاء الله. أنا (أدرس) الطب. أعمل سبع (ساعات).","قراءة: زينب مدرسة في الجامعة، تذهب الساعة السابعة، وتدرّس أربع حصص في اليوم.","نجيب بنعم أو لا: زينب مدرسة؟ نعم. تذهب الساعة الثامنة؟ لا، تذهب الساعة السابعة."],"examples":["لِي خَمْسَةُ أَطْفَالٍ.","هَلْ تُحِبِّينَ عَمَلَكِ يَا زَيْنَبُ؟","سَأَعْمَلُ مُهَنْدِسًا إِنْ شَاءَ اللهُ.","أَعْمَلُ سَبْعَ سَاعَاتٍ."],"questions":[{"question":"اكمل: لي خمسة ...","options":["طفل","طفلة","أطفال","أولاد"],"answer":2,"explanation":"بعد خمسة نستعمل الجمع: أطفال."},{"question":"اكمل: سأعمل ... إن شاء الله","options":["هل","مهندس الطيران","المهندس","مهندسًا"],"answer":3,"explanation":"مهندسًا."},{"question":"اكمل: أعمل سبع ...","options":["ساعة","شركة","ساعات","حصة"],"answer":2,"explanation":"سبع ساعات."},{"question":"هل تذهب زينب الساعة الثامنة؟","options":["لا تذهب أبدًا","نعم","لا، السابعة","تذهب مساءً"],"answer":2,"explanation":"الجواب لا، السابعة."}]}]},{"id":"abyb1-072","title":"الاختبار النصفي (1): فهم المسموع والقراءة","summary":"من الوحدات 1 إلى 8: نختار الجواب المناسب ونقرأ فقرتين.","segments":[{"body":["نبدأ بفهم المسموع. نستمع إلى سؤال ثم نختار الجواب.","سؤال: هل أكلت السمك والسلطة؟ الجواب: نعم، في الغداء.","سؤال: أين يصلي أحمد الفجر؟ الجواب: يصلي في المسجد.","سؤال: ما اسمك؟ الجواب: اسمي إلهام.","سؤال: أين تعمل؟ الجواب: أعمل في شركة. سؤال: كم ساعة تعمل؟ الجواب: أعمل سبع ساعات."],"examples":["هَلْ أَكَلْتَ السَّمَكَ وَالسَّلَطَةَ؟ نَعَمْ، فِي الْغَدَاءِ.","أَيْنَ تَعْمَلُ؟ أَعْمَلُ فِي شَرِكَةٍ.","كَمْ سَاعَةً تَعْمَلُ؟ أَعْمَلُ سَبْعَ سَاعَاتٍ."],"questions":[{"question":"سؤال: أين تعمل؟ الجواب:","options":["أعمل سبع ساعات","اسمي إلهام","نعم","أعمل في شركة"],"answer":3,"explanation":"أين للمكان."},{"question":"سؤال: كم ساعة تعمل؟ الجواب:","options":["في الغداء","أنا طبيب","أعمل سبع ساعات","أعمل في شركة"],"answer":2,"explanation":"كم للعدد."},{"question":"سؤال: ما اسمك؟ الجواب:","options":["سبع ساعات","أنا بخير","في البيت","اسمي إلهام"],"answer":3,"explanation":"اسمي."},{"question":"سؤال: هل أكلت السمك؟ الجواب المناسب:","options":["أنا مدرسة","في الشركة","سبع ساعات","نعم، في الغداء"],"answer":3,"explanation":"نعم."}]},{"body":["القراءة الأولى: حسان يسكن في شقة في حي المطار، وأحمد يسكن في بيت في حي الجامعة.","أين يسكن حسان؟ في شقة. هل يسكن حسان في بيت؟ لا. من يسكن في حي الجامعة؟ أحمد.","القراءة الثانية: عثمان سمين جدًا، يأكل أربع وجبات في اليوم.","الفطور الساعة السادسة صباحًا، والغداء الواحدة بعد الظهر، والعشاء السابعة مساءً.","يأكل عثمان في الفطور السمك والبيض، وفي الغداء اللحم والدجاج، ويشرب الشاي ثم القهوة."],"examples":["حَسَّانُ يَسْكُنُ فِي شَقَّةٍ فِي حَيِّ الْمَطَارِ.","أَحْمَدُ يَسْكُنُ فِي بَيْتٍ فِي حَيِّ الْجَامِعَةِ.","عُثْمَانُ يَأْكُلُ أَرْبَعَ وَجَبَاتٍ فِي الْيَوْمِ."],"questions":[{"question":"أين يسكن حسان؟","options":["في المسجد","في شقة في حي المطار","في بيت في حي الجامعة","في المدرسة"],"answer":1,"explanation":"في شقة في حي المطار."},{"question":"من يسكن في حي الجامعة؟","options":["سعيد","عثمان","أحمد","حسان"],"answer":2,"explanation":"أحمد."},{"question":"كم وجبة يأكل عثمان؟","options":["وجبتين","ست وجبات","أربع وجبات","وجبة واحدة"],"answer":2,"explanation":"أربع وجبات."},{"question":"متى العشاء؟","options":["الساعة السابعة مساءً","الثانية فجرًا","الواحدة ظهرًا","الساعة السادسة صباحًا"],"answer":0,"explanation":"السابعة مساءً."}]}]},{"id":"abyb1-073","title":"الاختبار النصفي (2): المفردات","summary":"من الوحدات 1 إلى 8: ألوان وظروف وأعداد وأفعال وجنسيات ومهن وضمائر وأسرة وأيام.","segments":[{"body":["نضيف كلمتين لكل مجموعة. ألوان: أبيض، أسود، أحمر، أخضر.","ظروف: فوق، شمال، تحت، يمين. أعداد: ثالث، رابع، خامس، سادس.","أفعال: يذهب، يشاهد، يأكل، يشرب. جنسيات: باكستاني، سوري، مصري، تركي.","مهن: طالب، مدرس، طبيب، مهندس. ضمائر: أنا، هو، أنت، هي.","أسرة: أب، أخ، أم، أخت. أيام: الجمعة، السبت، الأحد، الإثنين."],"examples":["أَبْيَض، أَسْوَد","فَوْق، شِمَال","ثَالِث، رَابِع","بَاكِسْتَانِيّ، سُورِيّ","أَنَا، هُوَ، أَنْتَ، هِيَ"],"questions":[{"question":"ألوان:","options":["ثالث ورابع","أب وأخ","فوق وتحت","أبيض وأسود"],"answer":3,"explanation":"أبيض وأسود."},{"question":"ظروف (أماكن):","options":["هو وهي","السبت والجمعة","فوق وشمال","طالب ومدرس"],"answer":2,"explanation":"فوق وشمال."},{"question":"جنسيات:","options":["أبيض وأسود","باكستاني وسوري","ثالث ورابع","أب وأخ"],"answer":1,"explanation":"جنسيات."},{"question":"أيام:","options":["يأكل ويشرب","طالب ومدرس","الجمعة والسبت","أنا وهو"],"answer":2,"explanation":"أيام."}]},{"body":["نضع علامة على الكلمة العربية الغريبة في كل مجموعة.","مدرسة، بيت، جامعة، كلية: الغريبة «بيت» لأنه ليس مكان دراسة.","شاي، لحم، دجاج، سمك: الغريبة «شاي» لأنه شراب.","أخ، أب، سجادة، ابن: الغريبة «سجادة» لأنها ليست من الأسرة.","يقرأ، يصلي، يشاهد، مدرس: الغريبة «مدرس» لأنها اسم."],"examples":["مَدْرَسَة، بَيْت، جَامِعَة، كُلِّيَّة","شَايٌ، لَحْمٌ، دَجَاجٌ، سَمَك","أَخٌ، أَبٌ، سَجَّادَةٌ، ابْنٌ","يَقْرَأُ، يُصَلِّي، يُشَاهِدُ، مُدَرِّسٌ"],"questions":[{"question":"الغريبة: أخ، أب، سجادة، ابن","options":["أخ","ابن","أب","سجادة"],"answer":3,"explanation":"سجادة ليست من الأسرة."},{"question":"الغريبة: شاي، لحم، دجاج، سمك","options":["سمك","دجاج","شاي","لحم"],"answer":2,"explanation":"شاي شراب."},{"question":"الغريبة: يقرأ، يصلي، يشاهد، مدرس","options":["يقرأ","يصلي","يشاهد","مدرس"],"answer":3,"explanation":"مدرس اسم."},{"question":"الغريبة: مطبخ، غرفة، حمام، طفل","options":["مطبخ","حمام","غرفة","طفل"],"answer":3,"explanation":"طفل ليس مكانًا في البيت."}]}]},{"id":"abyb1-074","title":"الاختبار النصفي (3): التراكيب والقواعد","summary":"من الوحدات 1 إلى 8: أدوات الاستفهام، الجمل الصحيحة، واختيار الفعل المناسب.","segments":[{"body":["نختار أداة الاستفهام المناسبة. من أين: عن البلد. متى: عن الوقت.","لماذا: عن السبب. كيف: عن الحال. ما: عن الشيء. من: عن الشخص.","كم: عن العدد. أين: عن المكان. في أي: عن الاختيار. هل: جوابها نعم أو لا.","كيف حالك؟ ما اسمك؟ متى تستيقظ متأخرًا؟ أين تعمل؟","كم حصة تدرس في اليوم؟ هل هذا كتاب؟ في أي كلية تدرسين؟"],"examples":["كَيْفَ حَالُكَ؟","مَا اسْمُكَ؟","مَتَى تَسْتَيْقِظُ؟","كَمْ حِصَّةً تَدْرُسُ فِي الْيَوْمِ؟","هَلْ هَذَا كِتَابٌ؟"],"questions":[{"question":"أداة سؤال عن الحال:","options":["كم","كيف","أين","متى"],"answer":1,"explanation":"كيف حالك؟"},{"question":"أداة سؤال عن العدد:","options":["كم","كيف","لماذا","من"],"answer":0,"explanation":"كم."},{"question":"أداة سؤال عن السبب:","options":["لماذا","متى","هل","من أين"],"answer":0,"explanation":"لماذا."},{"question":"أداة جوابها نعم أو لا:","options":["أين","هل","من","ما"],"answer":1,"explanation":"هل."}]},{"body":["نضع علامة صح على الجملة الصحيحة وخطأ على الخطأ.","هل أنت باكستاني؟ جملة صحيحة. هذا أخي، هو مدرس: صحيحة. هذا أخي، هي مدرس: خطأ.","لي خمسة أطفال: صحيحة. لي خمسة طفل: خطأ.","نكتب الفعل الصحيح: (أصلي) لصلاة الجمعة. علي (يشرب) الطعام الآن. صديقي (ينتظر) الحافلة.","متى (تنتهي) الدراسة؟ هل (تحب) عملك؟ علي (يسكن) في حي المطار."],"examples":["هَلْ أَنْتَ بَاكِسْتَانِيّ؟","هَذَا أَخِي، هُوَ مُدَرِّسٌ.","لِي خَمْسَةُ أَطْفَالٍ.","عَلِيٌّ يَسْكُنُ فِي حَيِّ الْمَطَارِ.","مَتَى تَنْتَهِي الدِّرَاسَةُ؟"],"questions":[{"question":"الجملة الصحيحة:","options":["لي خمسة أطفال","لي خمسة طفلة","لي خمسة أطفالًا كثيرة","لي خمسة طفل"],"answer":0,"explanation":"بعد خمسة نستعمل الجمع."},{"question":"اكمل: علي ... في حي المطار","options":["نسكن","تسكنين","يسكن","أسكن"],"answer":2,"explanation":"علي هو، فنقول يسكن."},{"question":"اكمل: متى ... الدراسة؟","options":["أنتهي","ننتهي","ينتهون","تنتهي"],"answer":3,"explanation":"الدراسة مؤنثة: تنتهي."},{"question":"هذا أخي ...","options":["هو مدرس","هل مدرس","أنا مدرس","هي مدرس"],"answer":0,"explanation":"أخي مذكر: هو."}]}]}]};
